INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88995, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "厕所是上大小便的地方。", "primary_collocate": null, "pronunciation": "cè suǒ", "ipa": "tsʰɤ˥˩ suo̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家有两个厕所。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站的厕所在哪里？", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进了厕所，关上门。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厕所的灯坏了。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，我可以去厕所吗？", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女厕所前面有很多人。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厕所要天天打扫。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的厕所在二楼。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不能进厕所。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在厕所里洗手。", "target_word": "厕所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共厕所", "label": "复合"}, {"form": "女厕所", "label": "复合"}, {"form": "间", "label": "量词"}, {"form": "廁所", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上大小便的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb1a83c7-686e-430e-8a43-46799c4d78f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88995, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厕所", "is_correct": true, "explanation": "正确：“我家有两个厕所”指家里的两处厕所，“厕所”是可以计数的场所。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是场所，“我家有两个时间”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是场所，“我家有两个颜色”说不通。"}, {"text": "感觉", "is_correct": false, "explanation": "搭配：“感觉”可以说“两种感觉”，但不能与“两个”搭配计数，“我家有两个感觉”说不通。"}], "explanations": {"厕所": "正确：“我家有两个厕所”指家里的两处厕所，“厕所”是可以计数的场所。", "时间": "语义：“时间”不是场所，“我家有两个时间”说不通。", "颜色": "语义：“颜色”不是场所，“我家有两个颜色”说不通。", "感觉": "搭配：“感觉”可以说“两种感觉”，但不能与“两个”搭配计数，“我家有两个感觉”说不通。"}, "sentence_index": 0, "correct_answer": "厕所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家新买了一把厕所。", "explanation": "这里应该用〈间〉。“把”多用于有柄的器具，厕所不能用“把”计数。"}, {"text": "客厅里放着一张厕所。", "explanation": "这里应该用〈间〉。“张”用于平面的东西，厕所不能用“张”计数。"}, {"text": "公园里有一条厕所。", "explanation": "这里应该用〈间〉。“条”用于细长的东西，厕所不能用“条”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厕所", "is_correct": true, "explanation": "正确：“厕所要天天打扫”，厕所是需要经常打扫的场所。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不需要人打扫，“天空要天天打扫”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不能用“打扫”，“空气要天天打扫”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能与“名字”搭配。"}], "explanations": {"厕所": "正确：“厕所要天天打扫”，厕所是需要经常打扫的场所。", "天空": "语义：“天空”不需要人打扫，“天空要天天打扫”说不通。", "空气": "语义：“空气”不能用“打扫”，“空气要天天打扫”说不通。", "名字": "搭配：“打扫”的对象是场所或物品，不能与“名字”搭配。"}, "sentence_index": 6, "correct_answer": "厕所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家新买了一本厕所。", "explanation": "这里应该用〈间〉。“本”用于书册，厕所不能用“本”计数。"}, {"text": "楼下新修了一幅厕所。", "explanation": "这里应该用〈间〉。“幅”用于画、布等，厕所不能用“幅”计数。"}, {"text": "公园里有一只厕所。", "explanation": "这里应该用〈间〉。“只”用于动物和成对的东西，厕所不能用“只”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去这只厕所洗手了。", "corrected_sentence": "他去这间厕所洗手了。", "error_description": "错误：“这只厕所”；正确：“这间厕所”。厕所作量词用“间”，“只”用于动物和成对的东西，不能用于厕所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商场有三只厕所。", "corrected_sentence": "这家商场有三间厕所。", "error_description": "错误：“三只厕所”；正确：“三间厕所”。厕所作量词用“间”，“只”用于动物和成对的东西，不能用于厕所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
