INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "弟弟是和你同一个爸爸妈妈、比你小的男子。", "primary_collocate": null, "pronunciation": "dì di", "ipa": "ti⁵¹ ti", "syllable_count": 2, "sentences": [{"text": "我弟弟比我小三岁。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟今年上小学，我已经上中学了。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的弟弟很喜欢踢足球。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给弟弟买了一个新书包。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟还小，不会自己穿衣服。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上送弟弟去学校。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟抱着小狗，笑得很开心。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是姐姐，所以要照顾弟弟。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟刚剪了头发，看起来像个小男孩。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和弟弟一起打篮球。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个弟弟", "label": "量词"}, {"form": "亲弟弟", "label": "复合"}], "register": "口语", "sense_fingerprint": "同一个爸爸妈妈、比自己小的男子（日常口语称呼）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟（dì di），指同一父母所生、比自己小的男子。"}, {"text": "弟子", "is_correct": false, "explanation": "zi 与 di 声母不同（z 与 d），意思是弟子（学生、门徒）。"}, {"text": "滴滴", "is_correct": false, "explanation": "dī dī 与 dì di 声调不同，意思是滴滴（水滴声或汽车喇叭声）。"}, {"text": "嘀嘀", "is_correct": false, "explanation": "dí dí 与 dì di 声调不同，意思是嘀嘀（喇叭或信号的声音）。"}, {"text": "地址", "is_correct": false, "explanation": "第二音节 zhǐ 与 di 声母不同（zh 与 d），声调也不同，意思是地址。"}], "explanations": {"弟弟": "正确答案：弟弟（dì di），指同一父母所生、比自己小的男子。", "弟子": "zi 与 di 声母不同（z 与 d），意思是弟子（学生、门徒）。", "滴滴": "dī dī 与 dì di 声调不同，意思是滴滴（水滴声或汽车喇叭声）。", "嘀嘀": "dí dí 与 dì di 声调不同，意思是嘀嘀（喇叭或信号的声音）。", "地址": "第二音节 zhǐ 与 di 声母不同（zh 与 d），声调也不同，意思是地址。"}, "sentence_index": null, "correct_answer": "弟弟"}, "level_3": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟指比自己小的兄弟，与“比我小三岁”相符。"}, {"text": "哥哥", "is_correct": false, "explanation": "语义：“哥哥”指年长的兄长，与“比我小三岁”矛盾。"}, {"text": "爷爷", "is_correct": false, "explanation": "语义：“爷爷”属于长辈，不可能比“我”小三岁。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“比……小”比较的是人的年龄，“书包”不能用来比较年龄。"}], "explanations": {"弟弟": "正确答案：弟弟指比自己小的兄弟，与“比我小三岁”相符。", "哥哥": "语义：“哥哥”指年长的兄长，与“比我小三岁”矛盾。", "爷爷": "语义：“爷爷”属于长辈，不可能比“我”小三岁。", "书包": "搭配：“比……小”比较的是人的年龄，“书包”不能用来比较年龄。"}, "sentence_index": 0, "correct_answer": "弟弟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在学校认识了一个新弟弟。", "explanation": "这里应该用〈同学〉。“弟弟”指同一父母所生、比自己小的男孩，不能用于学校里认识的同学。"}, {"text": "我家来了一只弟弟，他很活泼。", "explanation": "这里应该用〈个〉。“弟弟”指人，数人要用指人的量词，不能用于动物。"}, {"text": "我的弟弟是个女孩，她今年十岁。", "explanation": "这里应该用〈妹妹〉。“弟弟”指比自己小的男性，说女孩要用“妹妹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89001, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟（dì di），指同一父母所生、比自己小的男子。"}, {"text": "低地", "is_correct": false, "explanation": "dī dì 与 dì di 的第一音节声调不同，意思是低地（地势低的地方）。"}, {"text": "地理", "is_correct": false, "explanation": "第二音节 lǐ 与 di 声母和声调都不同，意思是地理（地表的自然状况）。"}, {"text": "地势", "is_correct": false, "explanation": "第二音节 shì 与 di 声母不同（sh 与 d），意思是地势（地面的高低起伏）。"}], "explanations": {"弟弟": "正确答案：弟弟（dì di），指同一父母所生、比自己小的男子。", "低地": "dī dì 与 dì di 的第一音节声调不同，意思是低地（地势低的地方）。", "地理": "第二音节 lǐ 与 di 声母和声调都不同，意思是地理（地表的自然状况）。", "地势": "第二音节 shì 与 di 声母不同（sh 与 d），意思是地势（地面的高低起伏）。"}, "sentence_index": null, "correct_answer": "弟弟"}, "level_3": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟指同父母所生、比自己小的男子，能够抱着小狗、笑得很开心。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“抱着小狗”要求人或动物作主语，“椅子”不能抱东西。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有情感，不会“笑得很开心”。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是没有生命的物体，不能抱小狗，也不会笑。"}], "explanations": {"弟弟": "正确答案：弟弟指同父母所生、比自己小的男子，能够抱着小狗、笑得很开心。", "椅子": "搭配：“抱着小狗”要求人或动物作主语，“椅子”不能抱东西。", "石头": "语义：“石头”没有情感，不会“笑得很开心”。", "闹钟": "语义：“闹钟”是没有生命的物体，不能抱小狗，也不会笑。"}, "sentence_index": 6, "correct_answer": "弟弟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟比我大两岁，已经上大学了。", "explanation": "这里应该用〈哥哥〉。“弟弟”指比自己小的男性兄弟，比“我”大的要说“哥哥”。"}, {"text": "我丈夫是我的弟弟，我们每天一起吃晚饭。", "explanation": "这里应该用〈老公〉。“弟弟”只指同父母所生的小兄弟，不能指配偶。"}, {"text": "我的女儿是我的弟弟，她刚上幼儿园。", "explanation": "这里应该用〈孩子〉。“弟弟”是同辈的小兄弟，不能用来指下一代的子女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两弟弟，他们都很活泼。", "corrected_sentence": "我家有两个弟弟，他们都很活泼。", "error_description": "“两”与“弟弟”之间要加量词“个”，应说“两个弟弟”，不能直接说“两弟弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家有一个的弟弟，他很爱笑。", "corrected_sentence": "我们家有一个弟弟，他很爱笑。", "error_description": "“一个”与“弟弟”之间不能加“的”，应说“一个弟弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
