INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同父母（或同父、同母）而年纪比自己小的男子。", "primary_collocate": null, "pronunciation": "dì di", "ipa": "ti⁵¹ ti", "syllable_count": 2, "sentences": [{"text": "我有一个弟弟，他比我小两岁。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟在北京工作，很少回家。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸有两个儿子，我是哥哥，他是我弟弟。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟小时候总是跟在我后面。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把自己的旧手机给了弟弟。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟去过很多地方，见过很多人。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥结婚了，弟弟下个月也要结婚。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我要陪弟弟去看电影。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和弟弟长得很像，大家都说我们是双胞胎。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的生日是五月，我的生日是三月。", "target_word": "弟弟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个弟弟", "label": "量词"}, {"form": "亲弟弟", "label": "复合"}], "register": "口语", "sense_fingerprint": "同父母（或同父、同母）、年纪比自己小的男子（亲属关系）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟（dì di），指同父母所生、年纪比自己小的男子。"}, {"text": "弟子", "is_correct": false, "explanation": "zi 与 di 声母不同（z 与 d），意思是弟子（学生、门徒）。"}, {"text": "滴滴", "is_correct": false, "explanation": "dī dī 与 dì di 声调不同，意思是滴滴（水滴声或汽车喇叭声）。"}, {"text": "地址", "is_correct": false, "explanation": "第二音节 zhǐ 与 di 声母不同（zh 与 d），声调也不同，意思是地址。"}], "explanations": {"弟弟": "正确答案：弟弟（dì di），指同父母所生、年纪比自己小的男子。", "弟子": "zi 与 di 声母不同（z 与 d），意思是弟子（学生、门徒）。", "滴滴": "dī dī 与 dì di 声调不同，意思是滴滴（水滴声或汽车喇叭声）。", "地址": "第二音节 zhǐ 与 di 声母不同（zh 与 d），声调也不同，意思是地址。"}, "sentence_index": null, "correct_answer": "弟弟"}, "level_3": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟指比自己小的兄弟，与“比我小两岁”相符。"}, {"text": "姐姐", "is_correct": false, "explanation": "语义：“姐姐”比自己年长，与“比我小两岁”矛盾。"}, {"text": "爷爷", "is_correct": false, "explanation": "语义：“爷爷”属于长辈，不可能比“我”小两岁。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“小”比较的是人的年龄，“书桌”不能用来比较年龄。"}], "explanations": {"弟弟": "正确答案：弟弟指比自己小的兄弟，与“比我小两岁”相符。", "姐姐": "语义：“姐姐”比自己年长，与“比我小两岁”矛盾。", "爷爷": "语义：“爷爷”属于长辈，不可能比“我”小两岁。", "书桌": "搭配：“小”比较的是人的年龄，“书桌”不能用来比较年龄。"}, "sentence_index": 0, "correct_answer": "弟弟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟比我大两岁，他常常带我去玩。", "explanation": "这里应该用〈哥哥〉。“弟弟”指比自己小的兄弟，比“我”年长的应说“哥哥”。"}, {"text": "我的弟弟是个女孩，她喜欢画画。", "explanation": "这里应该用〈妹妹〉。“弟弟”指男性，说女孩要用“妹妹”。"}, {"text": "我家有一条弟弟，他很活泼。", "explanation": "这里应该用〈个〉。“弟弟”指人，数人要用指人的量词，不能用于长条形的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟（dì di），指同父母所生、年纪比自己小的男子。"}, {"text": "低地", "is_correct": false, "explanation": "dī dì 与 dì di 的第一音节声调不同，意思是低地（地势低的地方）。"}, {"text": "地理", "is_correct": false, "explanation": "第二音节 lǐ 与 di 声母和声调都不同，意思是地理（地表的自然状况）。"}, {"text": "地势", "is_correct": false, "explanation": "第二音节 shì 与 di 声母不同（sh 与 d），意思是地势（地面的高低起伏）。"}], "explanations": {"弟弟": "正确答案：弟弟（dì di），指同父母所生、年纪比自己小的男子。", "低地": "dī dì 与 dì di 的第一音节声调不同，意思是低地（地势低的地方）。", "地理": "第二音节 lǐ 与 di 声母和声调都不同，意思是地理（地表的自然状况）。", "地势": "第二音节 shì 与 di 声母不同（sh 与 d），意思是地势（地面的高低起伏）。"}, "sentence_index": null, "correct_answer": "弟弟"}, "level_3": {"options": [{"text": "弟弟", "is_correct": true, "explanation": "正确答案：弟弟指比自己小的兄弟，与“下个月也要结婚”的人物相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不是人，不能结婚。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”没有生命，不会结婚。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“结婚”的主语要指人，“书架”不能与之搭配。"}], "explanations": {"弟弟": "正确答案：弟弟指比自己小的兄弟，与“下个月也要结婚”的人物相符。", "汽车": "语义：“汽车”不是人，不能结婚。", "房子": "语义：“房子”没有生命，不会结婚。", "书架": "搭配：“结婚”的主语要指人，“书架”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "弟弟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟是我姑姑的儿子，我们常常一起玩。", "explanation": "这里应该用〈表弟〉。“弟弟”指同父母所生的兄弟，姑姑的儿子是表亲，要用“表弟”。"}, {"text": "我丈夫是我的弟弟，他每天早上送我上班。", "explanation": "这里应该说〈老公〉。“弟弟”只指同父母所生的小兄弟，不能拿来指丈夫。"}, {"text": "我的老板是我的弟弟，他每天管理公司。", "explanation": "这里应该用〈上司〉。“弟弟”只指同父母的小兄弟，不能指工作中的领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有两弟弟，都比我小。", "corrected_sentence": "我有两个弟弟，都比我小。", "error_description": "“两”与“弟弟”之间要加量词“个”，应说“两个弟弟”，不能直接说“两弟弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有一个的弟弟，他刚上小学。", "corrected_sentence": "我有一个弟弟，他刚上小学。", "error_description": "“一个”与“弟弟”之间不能加“的”，应说“一个弟弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
