INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份形势对小公司很不利。", "corrected_sentence": "这种形势对小公司很不利。", "error_description": "错误：这份形势。正确：这种形势。“份”多用于文件、饭菜等，形势是抽象名词，应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "形势发展的很快，大家都在等待。", "corrected_sentence": "形势发展得很快，大家都在等待。", "error_description": "错误：发展的很快。正确：发展得很快。补语前应用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
