INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示制止或作罢，相当于「行了」「算了」。", "primary_collocate": null, "pronunciation": "dé le", "ipa": "tɤ˧˥ lə", "syllable_count": 2, "sentences": [{"text": "得了，别再说了，我不想听。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了得了，这件事就别提了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，我自己去吧，不麻烦你了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还想说，我说：“得了，别说了。”", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，你别哭了，我给你买新的。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，今天太晚了，明天再做吧。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，别吵了，大家都累了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，不去就不去，没什么大不了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，算我错了，行不行？", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说：“得了，别看手机了，快睡觉。”", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "得了得了", "label": "重叠"}], "register": "口语", "sense_fingerprint": "得了：叹词，制止或作罢，相当于算了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d43d41e-913a-4915-873f-c2b33d22f696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
