INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "得了", "is_correct": true, "explanation": "得了：dé le，叹词，表示制止或作罢。"}, {"text": "隔了", "is_correct": false, "explanation": "隔了（gé le）与得了（dé le）声母不同（g 与 d），声调相同，意思是隔开了。"}, {"text": "择了", "is_correct": false, "explanation": "择了（zé le）与得了（dé le）声母不同（z 与 d），声调相同，意思是选择了。"}, {"text": "答了", "is_correct": false, "explanation": "答了（dá le）与得了（dé le）韵母不同（a 与 e），声调相同，意思是回答了。"}], "explanations": {"得了": "得了：dé le，叹词，表示制止或作罢。", "隔了": "隔了（gé le）与得了（dé le）声母不同（g 与 d），声调相同，意思是隔开了。", "择了": "择了（zé le）与得了（dé le）声母不同（z 与 d），声调相同，意思是选择了。", "答了": "答了（dá le）与得了（dé le）韵母不同（a 与 e），声调相同，意思是回答了。"}, "sentence_index": null, "correct_answer": "得了"}, "level_3": {"options": [{"text": "得了", "is_correct": true, "explanation": "叹词“得了”：制止或作罢，与“别吵了，大家都累了”相合。"}, {"text": "吁", "is_correct": false, "explanation": "语域：“吁”是文言叹词，口语句子里不用。"}, {"text": "喏", "is_correct": false, "explanation": "语义：“喏”是恭敬地应答，不能用来制止吵闹。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊讶或赞叹，与“别吵了”的制止语气不合。"}], "explanations": {"得了": "叹词“得了”：制止或作罢，与“别吵了，大家都累了”相合。", "吁": "语域：“吁”是文言叹词，口语句子里不用。", "喏": "语义：“喏”是恭敬地应答，不能用来制止吵闹。", "哇": "语义：“哇”表示惊讶或赞叹，与“别吵了”的制止语气不合。"}, "sentence_index": 6, "correct_answer": "得了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "得了，早上好！", "explanation": "这里应该用〈你好〉。“得了”表示制止或作罢，不能用来问候。"}, {"text": "得了，欢迎光临。", "explanation": "这里应该用〈你好〉。“得了”不能用来打招呼或迎接客人。"}, {"text": "得了，我肚子好饿！", "explanation": "这里的“得了”表示制止、同意或作罢，不能用来表达饥饿这种身体感受，应直接说〈饿了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.v