INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "得了了，你还是先休息吧。", "corrected_sentence": "得了，你还是先休息吧。", "error_description": "“得了”后多加了一个“了”。叹词应写作“得了”，“得了了”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我得了，我们走吧。", "corrected_sentence": "得了，我们走吧。", "error_description": "“得了”是叹词，前面不能加主语“我”。加上“我”后，“得了”变成动词，意思是患上（病），与句子的制止语气不符。叹词应说“得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
