INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89023, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "族是同一个祖先传下来的一大家人。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "我们族里的老人都住在山下。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "族里有一个规矩，过年要回家。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们这个族里最老的人。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们族有三百多口人。", "target_word": "族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个族很大，大家都住在一个村子里。", "target_word": "族", "complexity_tier": "T3", "furigana": "zhè ge zú hěn dà, dà jiā dōu zhù zài yí ge cūn zi lǐ.", "sentence_source": "generated"}, {"text": "爷爷说，我们族是从北方搬来的。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "族里的孩子过年都要给老人拜年。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们族的人都姓王，住在这里。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，族里的人坐在一起吃饭。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家乡以后，族里的人很想他。", "target_word": "族", "complexity_tier": "T3", "furigana": "tā lí kāi jiā xiāng yǐ hòu, zú lǐ de rén hěn xiǎng tā.", "sentence_source": "generated"}], "morphological_forms": [{"form": "家族", "label": "复合"}, {"form": "民族", "label": "复合"}], "register": "中性", "sense_fingerprint": "同一祖先的一大家人（宗族）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "族", "is_correct": true, "explanation": "族 zú（第二声）指同一祖先传下来的一大家人，或一个民族。"}, {"text": "祖", "is_correct": false, "explanation": "祖 zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。"}, {"text": "组", "is_correct": false, "explanation": "组 zǔ（第三声）与 zú（第二声）声调不同，意思是小组。"}, {"text": "租", "is_correct": false, "explanation": "租 zū（第一声）与 zú（第二声）声调不同，意思是租用。"}, {"text": "竹", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh/z），意思是竹子。"}, {"text": "俗", "is_correct": false, "explanation": "sú 与 zú 声母不同（s/z），意思是风俗、习俗。"}], "explanations": {"族": "族 zú（第二声）指同一祖先传下来的一大家人，或一个民族。", "祖": "祖 zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。", "组": "组 zǔ（第三声）与 zú（第二声）声调不同，意思是小组。", "租": "租 zū（第一声）与 zú（第二声）声调不同，意思是租用。", "竹": "zhú 与 zú 声母不同（zh/z），意思是竹子。", "俗": "sú 与 zú 声母不同（s/z），意思是风俗、习俗。"}, "sentence_index": null, "correct_answer": "族"}, "level_3": {"options": [{"text": "族", "is_correct": true, "explanation": "族指同一祖先的家人群体，“族里的老人”符合语境。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是盛饭的器具，不能住人，“碗里的老人”不能住在山下。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“车里”指车的内部，不能与“老人都住在山下”的居住语境搭配。"}, {"text": "船", "is_correct": false, "explanation": "语义：船是水上的交通工具，不能指一群住在山下的老人。"}], "explanations": {"族": "族指同一祖先的家人群体，“族里的老人”符合语境。", "碗": "语义：碗是盛饭的器具，不能住人，“碗里的老人”不能住在山下。", "车": "搭配：“车里”指车的内部，不能与“老人都住在山下”的居住语境搭配。", "船": "语义：船是水上的交通工具，不能指一群住在山下的老人。"}, "sentence_index": 0, "correct_answer": "族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一只族有三百多口人。", "explanation": "这里应该用〈个〉。族是群体名词，量词用“个”，“只”一般用于动物或小件物品。"}, {"text": "我在族等你。", "explanation": "这里应该用〈家〉。族指一群人，不是地点；“在家等你”里的“家”指住所。"}, {"text": "我的族是医生。", "explanation": "这里应该用〈家人〉。族指整个家族这一群体，不能指一个人，也不能说“是医生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89023, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "族", "is_correct": true, "explanation": "族 zú（第二声）指同一祖先传下来的一大家人，或一个民族。"}, {"text": "阻", "is_correct": false, "explanation": "阻 zǔ（第三声）与 zú（第二声）声调不同，意思是阻止。"}, {"text": "逐", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh/z），意思是追逐。"}, {"text": "烛", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh/z），意思是蜡烛。"}], "explanations": {"族": "族 zú（第二声）指同一祖先传下来的一大家人，或一个民族。", "阻": "阻 zǔ（第三声）与 zú（第二声）声调不同，意思是阻止。", "逐": "zhú 与 zú 声母不同（zh/z），意思是追逐。", "烛": "zhú 与 zú 声母不同（zh/z），意思是蜡烛。"}, "sentence_index": null, "correct_answer": "族"}, "level_3": {"options": [{"text": "族", "is_correct": true, "explanation": "族指同一祖先的家人群体，“族里的孩子过年拜年”符合语境。"}, {"text": "锅", "is_correct": false, "explanation": "语义：锅是烹饪用具，不能装人，与“过年给老人拜年”不合。"}, {"text": "桌", "is_correct": false, "explanation": "搭配：“桌里”不是常用的方位搭配，与“过年给老人拜年”的家庭语境不搭配。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：瓶子里装不下孩子，“瓶里的孩子”不能过年给老人拜年。"}], "explanations": {"族": "族指同一祖先的家人群体，“族里的孩子过年拜年”符合语境。", "锅": "语义：锅是烹饪用具，不能装人，与“过年给老人拜年”不合。", "桌": "搭配：“桌里”不是常用的方位搭配，与“过年给老人拜年”的家庭语境不搭配。", "瓶": "语义：瓶子里装不下孩子，“瓶里的孩子”不能过年给老人拜年。"}, "sentence_index": 6, "correct_answer": "族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校有三千个族。", "explanation": "这里应该用〈学生〉。族是群体，不能用来数学校里的个人。"}, {"text": "孩子们在族上课。", "explanation": "这里应该用〈学校〉。族指同一祖先的群体，不是上课的场所。"}, {"text": "医生在医院里照顾族。", "explanation": "这里应该用〈病人〉。族是群体，不能指被照顾的个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只族里有很多人都姓李。", "corrected_sentence": "这个族里有很多人都姓李。", "error_description": "“族”是群体名词，量词应用“个”，不能用“只”（“只”多用于动物或小件物品）。错误在“这只”，应为“这个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "族上的长辈常常讲以前的事。", "corrected_sentence": "族里的长辈常常讲以前的事。", "error_description": "“族”内的位置应用方位词“里”，说“族里”，不能说“族上”。错误在方位词，应为“族里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
