INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "族是有共同语言和习俗的人群，即民族。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "这个族爱唱歌，也爱跳舞。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们那个族在山里住了很多年。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们族有自己的语言和节日。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妈妈是我们族的人。", "target_word": "族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个族的人过节都穿红色的衣服。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是哪个族的人？", "target_word": "族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们族过年的时候，大家一起跳舞。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族不大，只有几千人。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "族里有自己的老师教孩子说话。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们族住在南方的大山里。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民族", "label": "复合"}, {"form": "家族", "label": "复合"}], "register": "中性", "sense_fingerprint": "民族（有共同语言和习俗的群体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "族", "is_correct": true, "explanation": "族 zú（第二声）指有共同祖先的家庭群体，也指民族。"}, {"text": "祖", "is_correct": false, "explanation": "祖 zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。"}, {"text": "组", "is_correct": false, "explanation": "组 zǔ（第三声）与 zú（第二声）声调不同，意思是小组。"}, {"text": "租", "is_correct": false, "explanation": "租 zū（第一声）与 zú（第二声）声调不同，意思是租用。"}, {"text": "竹", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh/z），意思是竹子。"}, {"text": "俗", "is_correct": false, "explanation": "sú 与 zú 声母不同（s/z），意思是风俗、习俗。"}], "explanations": {"族": "族 zú（第二声）指有共同祖先的家庭群体，也指民族。", "祖": "祖 zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。", "组": "组 zǔ（第三声）与 zú（第二声）声调不同，意思是小组。", "租": "租 zū（第一声）与 zú（第二声）声调不同，意思是租用。", "竹": "zhú 与 zú 声母不同（zh/z），意思是竹子。", "俗": "sú 与 zú 声母不同（s/z），意思是风俗、习俗。"}, "sentence_index": null, "correct_answer": "族"}, "level_3": {"options": [{"text": "族", "is_correct": true, "explanation": "族指有共同语言和习俗的群体，“这个族爱唱歌跳舞”符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能“爱唱歌，也爱跳舞”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”不能作“爱唱歌，也爱跳舞”的主语，两者不搭配。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不会“爱”，也不会唱歌跳舞。"}], "explanations": {"族": "族指有共同语言和习俗的群体，“这个族爱唱歌跳舞”符合语境。", "石头": "语义：石头没有感情，不能“爱唱歌，也爱跳舞”。", "房子": "搭配：“房子”不能作“爱唱歌，也爱跳舞”的主语，两者不搭配。", "机器": "语义：机器不会“爱”，也不会唱歌跳舞。"}, "sentence_index": 0, "correct_answer": "族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一根族有一百人。", "explanation": "这里应该用〈个〉。族是群体名词，“根”只用于细长的东西。"}, {"text": "医生在照顾族。", "explanation": "这里应该用〈病人〉。族指群体，不能指被照顾的个人。"}, {"text": "我每天回族吃饭。", "explanation": "这里应该用〈家〉。族不是住所；“回族”是民族名，不能代替“回家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "族", "is_correct": true, "explanation": "族 zú（第二声）指有共同祖先的家庭群体，也指民族。"}, {"text": "阻", "is_correct": false, "explanation": "阻 zǔ（第三声）与 zú（第二声）声调不同，意思是阻止。"}, {"text": "逐", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh/z），意思是追逐。"}, {"text": "烛", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh/z），意思是蜡烛。"}], "explanations": {"族": "族 zú（第二声）指有共同祖先的家庭群体，也指民族。", "阻": "阻 zǔ（第三声）与 zú（第二声）声调不同，意思是阻止。", "逐": "zhú 与 zú 声母不同（zh/z），意思是追逐。", "烛": "zhú 与 zú 声母不同（zh/z），意思是蜡烛。"}, "sentence_index": null, "correct_answer": "族"}, "level_3": {"options": [{"text": "族", "is_correct": true, "explanation": "族指有共同语言和习俗的群体，“我们族过年跳舞”符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能“大家一起跳舞”，句子的主语应是人。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会跳舞，与“大家一起跳舞”不合。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是场所，不能作“大家一起跳舞”的主体。"}], "explanations": {"族": "族指有共同语言和习俗的群体，“我们族过年跳舞”符合语境。", "手机": "语义：手机不能“大家一起跳舞”，句子的主语应是人。", "冰箱": "语义：冰箱不会跳舞，与“大家一起跳舞”不合。", "厨房": "搭配：“厨房”是场所，不能作“大家一起跳舞”的主体。"}, "sentence_index": 6, "correct_answer": "族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座剧院有三千个族。", "explanation": "这里应该用〈观众〉。族指同一祖先的群体或民族，不能用来数剧院里的观众。"}, {"text": "我们在族里看电影。", "explanation": "这里应该用〈电影院〉。族不是放映电影的场所。"}, {"text": "这辆车上有三十个族。", "explanation": "这里应该用〈乘客〉。族不能用来数车上的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只族的人大多会两种语言。", "corrected_sentence": "这个族的人大多会两种语言。", "error_description": "“族”作群体名词，量词应用“个”，不能用“只”。错误在“这只”，应为“这个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "族上的人一般都会说两种话。", "corrected_sentence": "族里的人一般都会说两种话。", "error_description": "族内的位置应用方位词“里”，说“族里”，不能说“族上”。错误在方位词，应为“族里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
