INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特色是一个东西跟别的不一样的好地方。", "primary_collocate": null, "pronunciation": "tè sè", "ipa": "tʰɤ˥˩ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你觉得这家饭店有什么特色？", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机最大的特色是电池用得久。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的课很有特色，学生都爱听。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市没有特色，哪儿都一样。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的产品有三个特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的特色是价格便宜。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想开一家有自己特色的咖啡店。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的特色是故事简单，图片多。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房子的特色是窗户特别大。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "特色菜", "label": "复合词"}, {"form": "特色小吃", "label": "复合词"}, {"form": "一个特色", "label": "量词（个）"}], "register": "中性", "sense_fingerprint": "一个东西跟别的不一样的优点或长处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccf90837-6f53-4998-80b9-e0ed350bbcb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特色", "is_correct": true, "explanation": "正确：“特色”指饭店跟别家不一样的好地方，与“有什么”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：饭店没有脾气，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”一般用于人或动物，不能说饭店的体重。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：饭店不说年龄，句意不通。"}], "explanations": {"特色": "正确：“特色”指饭店跟别家不一样的好地方，与“有什么”相合。", "脾气": "语义：饭店没有脾气，句意不通。", "体重": "搭配：“体重”一般用于人或动物，不能说饭店的体重。", "年龄": "语义：饭店不说年龄，句意不通。"}, "sentence_index": 0, "correct_answer": "特色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的特色很便宜，只要两百块。", "explanation": "这里应该用〈价格〉。特色指事物跟别的不一样的好地方，不用来说价钱高低。"}, {"text": "这辆车的特色是油耗高。", "explanation": "这里应该用〈缺点〉。特色指好的地方，油耗高是不足，不能说特色。"}, {"text": "我们的产品有一张很好的特色。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子一类物品，不能修饰“特色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特色", "is_correct": true, "explanation": "正确：“特色”指咖啡店跟别家不一样的好地方，与“有自己的”相合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：咖啡店没有身高，句意不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：咖啡店没有学历，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只用于人或动物，不能说店的体温。"}], "explanations": {"特色": "正确：“特色”指咖啡店跟别家不一样的好地方，与“有自己的”相合。", "身高": "语义：咖啡店没有身高，句意不通。", "学历": "语义：咖啡店没有学历，句意不通。", "体温": "搭配：“体温”只用于人或动物，不能说店的体温。"}, "sentence_index": 6, "correct_answer": "特色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两队之间的特色很大。", "explanation": "这里应该用〈差距〉。特色指好的地方，不能用来说两者差别的大小。"}, {"text": "这个箱子的特色很大。", "explanation": "这里应该用〈体积〉。特色指好的地方，不用来形容物体的大小。"}, {"text": "他的特色很高。", "explanation": "这里应该用〈工资〉。特色是好的地方，不用来说数量高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市有一把很好的特色，东西又新鲜又便宜。", "corrected_sentence": "这家超市有一个很好的特色，东西又新鲜又便宜。", "error_description": "错误：“一把”。应改为“一个”。“把”用于有柄的物品，不能修饰“特色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家面馆有很特色，生意很好。", "corrected_sentence": "这家面馆很有特色，生意很好。", "error_description": "错误：“有很特色”。应改为“很有特色”。“很”修饰“有”，“有”后接“特色”才正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
