INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所表现出来的独特的色彩或风格。", "primary_collocate": null, "pronunciation": "tè sè", "ipa": "tʰɤ˥˩ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这座古城很有地方特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四川菜的特色是又麻又辣。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种建筑的特色是红墙和黄瓦。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家的音乐都有自己的特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画很有个人特色，一看就知道。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小镇的房子都是白墙灰瓦，很有江南特色。", "target_word": "特色", "complexity_tier": "T3", "furigana": "zhè zuò xiǎo zhèn de fáng zi dōu shì bái qiáng huī wǎ, hěn yǒu Jiāng nán tè sè.", "sentence_source": "generated"}, {"text": "这个小镇保留着传统的民族特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国各地的节日都有不同的特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京烤鸭的特色是皮脆肉嫩。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店的设计很有特色。", "target_word": "特色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "特色菜", "label": "复合词"}, {"form": "特色小吃", "label": "复合词"}, {"form": "一个特色", "label": "量词（个）"}], "register": "中性", "sense_fingerprint": "事物表现出来的独特风格或色彩，常指地方、文化、艺术的风格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccf90837-6f53-4998-80b9-e0ed350bbcb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特色", "is_correct": true, "explanation": "正确：“特色”指事物表现出的独特风格，与“很有地方”相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：古城不说体重，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是风格或色彩，与“很有地方”不合，句意不通。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指大小，不是风格或色彩，句意不通。"}], "explanations": {"特色": "正确：“特色”指事物表现出的独特风格，与“很有地方”相合。", "体重": "语义：古城不说体重，句意不通。", "价格": "语义：“价格”不是风格或色彩，与“很有地方”不合，句意不通。", "面积": "语义：“面积”指大小，不是风格或色彩，句意不通。"}, "sentence_index": 0, "correct_answer": "特色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水的特色很热，喝起来正好。", "explanation": "这里说的是冷热，特色指事物表现出来的色彩或风格，不能用来形容温度。"}, {"text": "这座小镇有一张独特的特色。", "explanation": "这里应该用〈种〉。“张”用于纸、桌子一类物品，不能修饰“特色”。"}, {"text": "这种药的特色很贵，一般人买不起。", "explanation": "这里说的是价钱，特色指事物表现出来的色彩或风格，不能用来说价格高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特色", "is_correct": true, "explanation": "正确：“特色”指传统的独特风格，与“保留着传统的”相合。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“民族”后接“人数”不成搭配，不能说民族的人数来表示风格。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”不能用于民族，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能用来说民族的风格，句意不通。"}], "explanations": {"特色": "正确：“特色”指传统的独特风格，与“保留着传统的”相合。", "人数": "搭配：“民族”后接“人数”不成搭配，不能说民族的人数来表示风格。", "体重": "语义：“体重”不能用于民族，句意不通。", "年龄": "语义：“年龄”不能用来说民族的风格，句意不通。"}, "sentence_index": 6, "correct_answer": "特色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的特色很轻。", "explanation": "这里应该用〈重量〉。特色指风格或色彩，不能用来说轻重。"}, {"text": "这家工厂的特色很大。", "explanation": "这里应该用〈规模〉。特色指风格或色彩，不能用来说大小。"}, {"text": "这辆车的特色很快。", "explanation": "这里应该用〈速度〉。特色不能用来形容快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古镇的建筑有一只独特的特色。", "corrected_sentence": "这座古镇的建筑有一种独特的特色。", "error_description": "错误：“一只”。应改为“一种”。“只”用于动物等，不能修饰“特色”；“特色”应用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家茶馆的民国特色的很明显。", "corrected_sentence": "这家茶馆的民国特色很明显。", "error_description": "错误：“特色的很明显”。应改为“特色很明显”。“很明显”是谓语，“特色”后不能多加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
