INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "夜晚天空中闪亮的天体。", "primary_collocate": null, "pronunciation": "xīng", "ipa": "ɕiŋ⁵⁵", "syllable_count": 1, "sentences": [{"text": "科学家在夜空中找到了一颗新的星。", "target_word": "星", "complexity_tier": "T3", "furigana": "kē xué jiā zài yè kōng zhōng zhǎo dào le yí kē xīn de xīng", "sentence_source": "generated"}, {"text": "夜里的星离我们非常远。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的星比月亮还大，可是看起来很小。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人常常看星，知道什么时候种地。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的夜空里有一颗很亮的星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，夜空中的每颗星都是一个天体。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星会发光，月亮自己不会发光。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用望远镜研究远处的星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的灯太亮，夜里很难看到星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水手在海上看星，就能知道方向。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗星", "label": "量词"}, {"form": "星星", "label": "重叠"}, {"form": "星空", "label": "复合"}], "register": "中性", "sense_fingerprint": "夜空中发光的天体（天文意义上的星）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "星", "is_correct": true, "explanation": "xīng（第一声），这里指天文意义上夜空中发光的天体。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，意思是形状、形式。"}, {"text": "幸", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是幸运、幸福。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng（第三声）与 xīng（第一声）声调不同，意思是醒来、清醒。"}, {"text": "新", "is_correct": false, "explanation": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是新旧的新。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 xīng 声母不同（j 与 x），意思是经过、经济。"}], "explanations": {"星": "xīng（第一声），这里指天文意义上夜空中发光的天体。", "形": "xíng（第二声）与 xīng（第一声）声调不同，意思是形状、形式。", "幸": "xìng（第四声）与 xīng（第一声）声调不同，意思是幸运、幸福。", "醒": "xǐng（第三声）与 xīng（第一声）声调不同，意思是醒来、清醒。", "新": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是新旧的新。", "经": "jīng 与 xīng 声母不同（j 与 x），意思是经过、经济。"}, "sentence_index": null, "correct_answer": "星"}, "level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "星：天文意义上夜空中发光的天体，符合“找到了一颗新的”。"}, {"text": "珍珠", "is_correct": false, "explanation": "语义：珍珠出自贝类，不会在夜空中被找到。"}, {"text": "种子", "is_correct": false, "explanation": "语义：种子是植物的繁殖体，与“夜空中”不相符。"}, {"text": "钻石", "is_correct": false, "explanation": "搭配：“夜空中找到”的新发现通常指天体，钻石不搭配这一语境。"}], "explanations": {"星": "星：天文意义上夜空中发光的天体，符合“找到了一颗新的”。", "珍珠": "语义：珍珠出自贝类，不会在夜空中被找到。", "种子": "语义：种子是植物的繁殖体，与“夜空中”不相符。", "钻石": "搭配：“夜空中找到”的新发现通常指天体，钻石不搭配这一语境。"}, "sentence_index": 0, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "望远镜里出现了一只星。", "explanation": "这里应该用〈颗〉。星用量词颗，“只”多用于动物等，不用于星。"}, {"text": "夜空中有一根新的星。", "explanation": "这里应该用〈颗〉。“根”用于细长的东西，星不用“根”。"}, {"text": "科学家找到了一张新的星。", "explanation": "这里应该用〈颗〉。“张”用于平面的东西，星不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89032, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "星", "is_correct": true, "explanation": "xīng（第一声），这里指天文意义上夜空中发光的天体。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng（第三声）与 xīng（第一声）声调不同，意思是醒来、清醒。"}, {"text": "姓", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是姓氏。"}, {"text": "行", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，意思是可以、行走。"}, {"text": "心", "is_correct": false, "explanation": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是心脏、心情。"}, {"text": "精", "is_correct": false, "explanation": "jīng 与 xīng 声母不同（j 与 x），意思是精神、精力。"}], "explanations": {"星": "xīng（第一声），这里指天文意义上夜空中发光的天体。", "醒": "xǐng（第三声）与 xīng（第一声）声调不同，意思是醒来、清醒。", "姓": "xìng（第四声）与 xīng（第一声）声调不同，意思是姓氏。", "行": "xíng（第二声）与 xīng（第一声）声调不同，意思是可以、行走。", "心": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是心脏、心情。", "精": "jīng 与 xīng 声母不同（j 与 x），意思是精神、精力。"}, "sentence_index": null, "correct_answer": "星"}, "level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "星：夜空中自己会发光的天体，与“月亮自己不会发光”形成对比。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头本身不会发光，与“会发光”矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子本身不会发光，与“会发光”矛盾。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“发光”说的是能发光的物体，不能用于“歌”。"}], "explanations": {"星": "星：夜空中自己会发光的天体，与“月亮自己不会发光”形成对比。", "石头": "语义：石头本身不会发光，与“会发光”矛盾。", "桌子": "语义：桌子本身不会发光，与“会发光”矛盾。", "歌": "搭配：“发光”说的是能发光的物体，不能用于“歌”。"}, "sentence_index": 6, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的星缺了一角。", "explanation": "这里应该用〈月亮〉。“缺了一角”说的是月亮的形状，星不会缺角。"}, {"text": "睡前他关了星。", "explanation": "这里应该用〈灯〉。“关”用于灯，星不能被关。"}, {"text": "夏天的星很毒，晒得人难受。", "explanation": "这里应该用〈太阳〉。“毒”和“晒”形容太阳，星不会晒人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜空中有一只星在发光。", "corrected_sentence": "夜空中有一颗星在发光。", "error_description": "量词错误：星的量词应为“颗”，不能用“只”（“只”多用于动物等）。应改为“一颗星”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天一黑，星就一颗一颗点起来了。", "corrected_sentence": "天一黑，星就一颗一颗亮起来了。", "error_description": "搭配错误：“点”用于灯、火，不能用于星，应为“亮起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
