INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "欣赏是看到好东西，心里喜欢，认真地看。", "primary_collocate": null, "pronunciation": "xīn shǎng", "ipa": "ɕin˥ ʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们站在湖边欣赏夕阳。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常去美术馆欣赏名画。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去公园欣赏樱花。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在窗前欣赏着外面的雪景。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们停下来欣赏这里的风景。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢欣赏孩子们的画。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们一起欣赏了一场音乐会。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的日出值得好好欣赏。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在院子里欣赏他的花。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们花了一个小时欣赏这些照片。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欣赏了", "label": "完成体"}, {"form": "欣赏过", "label": "经历体"}, {"form": "欣赏着", "label": "持续体"}, {"form": "欣赏欣赏", "label": "重叠"}], "register": "中性", "sense_fingerprint": "认真观看美好的风景或作品并感到愉快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏指观看美好的景色，与“站在湖边”和“夕阳”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，夕阳不能被吃。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不说“修理夕阳”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，与夕阳无关，句意不通。"}], "explanations": {"欣赏": "欣赏指观看美好的景色，与“站在湖边”和“夕阳”相符。", "吃": "语义：“吃”指进食，夕阳不能被吃。", "修理": "搭配：“修理”的对象是器物，不说“修理夕阳”。", "打扫": "语义：“打扫”指清除脏物，与夕阳无关，句意不通。"}, "sentence_index": 0, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们认真欣赏了这份账单。", "explanation": "这里应该用〈核对〉。欣赏指观赏美好的事物，账单要用核对。"}, {"text": "公司派人去欣赏市场。", "explanation": "这里应该用〈考察〉。欣赏指观赏美好的事物，调查市场要用考察。"}, {"text": "他们终于欣赏了矛盾。", "explanation": "这里应该用〈解决〉。欣赏指观赏美好的事物，矛盾要用解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏指观看美好的表演，与“一起”和“音乐会”相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，不能用于音乐会。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”的对象是破损的东西，不说“修补音乐会”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹调食物，不能用于音乐会。"}], "explanations": {"欣赏": "欣赏指观看美好的表演，与“一起”和“音乐会”相符。", "洗": "语义：“洗”指清洁，不能用于音乐会。", "修补": "搭配：“修补”的对象是破损的东西，不说“修补音乐会”。", "煮": "语义：“煮”指烹调食物，不能用于音乐会。"}, "sentence_index": 6, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们欣赏了这份合同。", "explanation": "这里应该用〈审阅〉。欣赏指观赏美好的事物，合同要用审阅。"}, {"text": "我们欣赏了这笔预算。", "explanation": "这里应该用〈核算〉。欣赏指观赏美好的事物，预算要用核算。"}, {"text": "专家欣赏了这组数据。", "explanation": "这里应该用〈分析〉。欣赏指观赏美好的事物，数据要用分析。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天晚上一起欣赏了月亮。", "corrected_sentence": "我们明天晚上一起欣赏月亮。", "error_description": "错误在“欣赏”后面的“了”。“明天晚上”是将来的时间，动作还没有发生，不能用“欣赏了”，应去掉“了”，说“我们明天晚上一起欣赏月亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在欣赏过这幅画。", "corrected_sentence": "妈妈正在欣赏这幅画。", "error_description": "错误在“欣赏”后面的“过”。“正在”表示动作正在进行，“过”表示曾经有过的经历，两者不能同用，应去掉“过”，说“妈妈正在欣赏这幅画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
