INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为人或事物好，因而喜欢、赞赏。", "primary_collocate": null, "pronunciation": "xīn shǎng", "ipa": "ɕin˥ ʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师很欣赏你的想法。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我特别欣赏他的勇气。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理欣赏她认真工作的态度。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我欣赏诚实的人。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很欣赏这位年轻的作家。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都欣赏她的好性格。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最欣赏朋友的地方是他很热心。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太欣赏这种做法。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长十分欣赏这个学生。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我非常欣赏这首歌的创作思路。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欣赏了", "label": "完成体"}, {"form": "欣赏过", "label": "经历体"}, {"form": "欣赏着", "label": "持续体"}, {"form": "欣赏欣赏", "label": "重叠"}], "register": "中性", "sense_fingerprint": "认为人或事物好，因而喜欢、赞赏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏表示认为你的想法好而喜欢，与“很”表达的赞许语气相符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”指撕破，不用来对想法。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指包裹或装饰，与“很”所表达的赞许态度不合，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与“很”表达的赞许态度冲突。"}], "explanations": {"欣赏": "欣赏表示认为你的想法好而喜欢，与“很”表达的赞许语气相符。", "撕": "搭配：“撕”指撕破，不用来对想法。", "包装": "语义：“包装”指包裹或装饰，与“很”所表达的赞许态度不合，句意不通。", "扔": "语义：“扔”指丢弃，与“很”表达的赞许态度冲突。"}, "sentence_index": 0, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很欣赏这场车祸。", "explanation": "这里应该用〈痛心〉。欣赏指认为好而喜欢，车祸是坏事，表达惋惜要用痛心。"}, {"text": "老师很欣赏他的懒惰。", "explanation": "这里应该用〈批评〉。欣赏指认为好而喜欢，懒惰是缺点，对它表示不满要用批评。"}, {"text": "他很欣赏那种不诚实的行为。", "explanation": "这里应该用〈反对〉。欣赏指认为好而喜欢，不诚实不能认为好，表示否定要用反对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏表示认为朋友的优点好而喜欢，与“热心”的赞许语气相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“热心”的赞许语气相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”不能用于人的优点，句意不通。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖掉，与“朋友的地方”不搭。"}], "explanations": {"欣赏": "欣赏表示认为朋友的优点好而喜欢，与“热心”的赞许语气相符。", "拒绝": "语义：“拒绝”表示不接受，与“热心”的赞许语气相反。", "修理": "搭配：“修理”不能用于人的优点，句意不通。", "出售": "语义：“出售”指卖掉，与“朋友的地方”不搭。"}, "sentence_index": 6, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很欣赏这次的欺骗。", "explanation": "这里应该用〈反感〉。欣赏指认为好而喜欢，欺骗是坏事，表示厌恶要用反感。"}, {"text": "我很欣赏这种粗暴的态度。", "explanation": "这里应该用〈不满〉。欣赏指认为好而喜欢，粗暴的态度是缺点，对它应表达不满。"}, {"text": "他欣赏那个欺负别人的孩子。", "explanation": "这里应该用〈谴责〉。欣赏指认为好而喜欢，欺负别人是坏行为，对它应表示谴责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长很欣赏了这位老师的教学。", "corrected_sentence": "校长很欣赏这位老师的教学。", "error_description": "错误在“欣赏”后面的“了”。“很”表示一种状态，不能与表示完成的“了”同用，应去掉“了”，说“校长很欣赏这位老师的教学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师慢慢欣赏着了他的努力。", "corrected_sentence": "老师慢慢欣赏着他的努力。", "error_description": "错误在“着”后面的“了”。“着”表示动作持续，“了”表示完成，两者不能同用，应去掉“了”，说“老师慢慢欣赏着他的努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。"}, {"text": "大", "is_correct": false, "explanation": "大说体积或范围，与“旧”没有反义关系。"}, {"text": "红", "is_correct": false, "explanation": "红是颜色，与“旧”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢说速度，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。", "大": "大说体积或范围，与“旧”没有反义关系。", "红": "红是颜色，与“旧”没有反义关系。", "慢": "慢说速度，与“旧”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。"}, {"text": "远", "is_correct": false, "explanation": "远说距离，与“旧”没有反义关系。"}, {"text": "红", "is_correct": false, "explanation": "红是颜色，与“旧”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻说重量，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。", "远": "远说距离，与“旧”没有反义关系。", "红": "红是颜色，与“旧”没有反义关系。", "轻": "轻说重量，与“旧”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "旧是用了很久,已经不新了。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "这双鞋太旧了,该换了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包很旧,但是我很喜欢。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶家的沙发又旧又小。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书看起来很旧。", "target_word": "旧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他骑着一辆旧自行车。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧衣服送给了邻居。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些椅子虽然旧,但是还能坐。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的旧手表还走得很准。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里的黑板有点旧。", "target_word": "旧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住在一个很旧的小房子里。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "舊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西用了很久,已经不新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指东西用了很久、已经不新。"}, {"text": "九", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。"}, {"text": "六", "is_correct": false, "explanation": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。"}, {"text": "秀", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。"}, {"text": "究", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指东西用了很久、已经不新。", "九": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。", "六": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。", "秀": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。", "究": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“太旧了，该换了”说鞋用久了、不新，需要换。"}, {"text": "新", "is_correct": false, "explanation": "语义：太新了就不必换，与“该换了”的理由矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "语义：太干净不构成该换的理由，与句意不合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：甜不能修饰鞋，“太甜了”不成话。"}], "explanations": {"旧": "正确：“太旧了，该换了”说鞋用久了、不新，需要换。", "新": "语义：太新了就不必换，与“该换了”的理由矛盾。", "干净": "语义：太干净不构成该换的理由，与句意不合。", "甜": "搭配：甜不能修饰鞋，“太甜了”不成话。"}, "sentence_index": 0, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看起来很旧，头发都白了。", "explanation": "这里应该用〈老〉。旧用于东西，指用久了、不新；说人年纪大要用〈老〉。"}, {"text": "他对旧事念念不忘。", "explanation": "此处“旧”是“过去的”义项，指旧事，不是“用了很久、已经不新”的意思。"}, {"text": "他的旧病复发了。", "explanation": "此处“旧”指原有的、早就有的病，是另一义项，不是“用了很久”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指东西用了很久、已经不新。"}, {"text": "久", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。"}, {"text": "酒", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。"}, {"text": "袖", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。"}, {"text": "纠", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指东西用了很久、已经不新。", "久": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。", "酒": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。", "袖": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。", "纠": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“虽然旧，但是还能坐”是让步句，说椅子用久了但仍可用。"}, {"text": "新", "is_correct": false, "explanation": "语义：新不是需要让步的缺点，“虽然新，但是还能坐”的让步关系不成立。"}, {"text": "精致", "is_correct": false, "explanation": "语义：精致指精巧细致，与“还能坐”之间没有让步关系，句子不通。"}, {"text": "蓝", "is_correct": false, "explanation": "体貌：蓝是颜色，不能用来说明椅子的新旧，也不构成让步。"}], "explanations": {"旧": "正确：“虽然旧，但是还能坐”是让步句，说椅子用久了但仍可用。", "新": "语义：新不是需要让步的缺点，“虽然新，但是还能坐”的让步关系不成立。", "精致": "语义：精致指精巧细致，与“还能坐”之间没有让步关系，句子不通。", "蓝": "体貌：蓝是颜色，不能用来说明椅子的新旧，也不构成让步。"}, "sentence_index": 6, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出生在旧社会，小时候很苦。", "explanation": "此处“旧”是“过去的、以前的时代”义项，指旧社会，不是“用了很久、过时”的意思。"}, {"text": "他常常回忆旧日的时光。", "explanation": "此处“旧”是“过去的”义项，指旧日，不是“用了很久、过时”的意思。"}, {"text": "这双袜子旧了一个洞。", "explanation": "这里应该用〈破〉。旧只说东西用久了、不新，不说有了窟窿；有洞要用〈破〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋穿旧过，该换了。", "corrected_sentence": "这双鞋穿旧了，该换了。", "error_description": "“穿旧”后应用“了”表示变化，用“过”表示经历，句意不通。正确写法是“这双鞋穿旧了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间老屋旧很，但很温暖。", "corrected_sentence": "这间老屋很旧，但很温暖。", "error_description": "程度副词“很”应放在“旧”之前作状语，写成“旧很”是语序错误。正确写法是“很旧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
