INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。"}, {"text": "远", "is_correct": false, "explanation": "远说距离，与“旧”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚说厚度，与“旧”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻说重量，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。", "远": "远说距离，与“旧”没有反义关系。", "厚": "厚说厚度，与“旧”没有反义关系。", "轻": "轻说重量，与“旧”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过时的;经过长久使用的;与「新」相对。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "这种旧手机现在没人用了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还穿着一件旧外套。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法太旧了,不适合现在。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧的桌子坏了,我们买了新的。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裤子已经很旧了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸开着一辆旧车去上班。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的观念很旧,总是不接受新东西。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子旧了,墙也黄了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把旧书卖给了收废品的人。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑太旧,开机要等很久。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "舊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与新相对,指过时的或用了很久的事物、观念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。"}, {"text": "九", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。"}, {"text": "六", "is_correct": false, "explanation": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。"}, {"text": "秀", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。"}, {"text": "究", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。", "九": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。", "六": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。", "秀": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。", "究": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“旧手机”指用久、过时的手机，与“现在没人用了”相符。"}, {"text": "热门", "is_correct": false, "explanation": "语义：热门指很受欢迎，与“现在没人用了”的情况矛盾。"}, {"text": "时髦", "is_correct": false, "explanation": "语义：时髦指很流行、跟得上潮流，与“现在没人用了”的情况相反。"}, {"text": "深", "is_correct": false, "explanation": "搭配：深不能修饰手机，“这种深手机”不成话。"}], "explanations": {"旧": "正确：“旧手机”指用久、过时的手机，与“现在没人用了”相符。", "热门": "语义：热门指很受欢迎，与“现在没人用了”的情况矛盾。", "时髦": "语义：时髦指很流行、跟得上潮流，与“现在没人用了”的情况相反。", "深": "搭配：深不能修饰手机，“这种深手机”不成话。"}, "sentence_index": 0, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爷爷已经很旧了，走路都不方便。", "explanation": "这里应该用〈老〉。旧多指东西用久、不新，说人年纪大要用〈老〉。"}, {"text": "他一直怀念旧友。", "explanation": "此处“旧”是“以前的、长久相交的”义项，指旧友，不是“用了很久、已经不新”的意思。"}, {"text": "他的旧病又复发了。", "explanation": "此处“旧”指原有的、以前就有的病，属于另一义项，不是“用了很久、已不新”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。"}, {"text": "久", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。"}, {"text": "酒", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。"}, {"text": "袖", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。"}, {"text": "纠", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。", "久": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。", "酒": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。", "袖": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。", "纠": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“观念很旧，总是不接受新东西”说观念过时，与句意一致。"}, {"text": "开放", "is_correct": false, "explanation": "语义：开放指思想不保守、乐于接受新事物，与“总是不接受新东西”矛盾。"}, {"text": "新", "is_correct": false, "explanation": "语义：观念很新与后面“总是不接受新东西”自相矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“观念”不能用“亮”来形容，“观念很亮”不成话。"}], "explanations": {"旧": "正确：“观念很旧，总是不接受新东西”说观念过时，与句意一致。", "开放": "语义：开放指思想不保守、乐于接受新事物，与“总是不接受新东西”矛盾。", "新": "语义：观念很新与后面“总是不接受新东西”自相矛盾。", "亮": "搭配：“观念”不能用“亮”来形容，“观念很亮”不成话。"}, "sentence_index": 6, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑开机太旧了，要等很久。", "explanation": "这里应该用〈慢〉。旧说东西用了很久、不新，不能用来形容开机的速度。"}, {"text": "他出生在旧社会，小时候很苦。", "explanation": "此处“旧”是“过去的、以前的时代”义项，指旧社会，不是“用了很久、过时”的意思。"}, {"text": "他们又回到了旧地。", "explanation": "此处“旧”是“以前去过的”义项，指旧地方，不是“东西用久、不新”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套我穿了很多年，已经旧了了。", "corrected_sentence": "这件外套我穿了很多年，已经旧了。", "error_description": "“旧”后只需一个“了”表示变化，此处多加了一个“了”，重复。正确写法是“已经旧了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼旧很了，电梯也常坏。", "corrected_sentence": "这栋楼很旧了，电梯也常坏。", "error_description": "程度副词“很”应放在“旧”之前作状语，写成“旧很了”语序错误。正确写法是“这栋楼很旧了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "明天", "is_correct": false, "explanation": "“明天”指将来的一天，与“此时”不构成反义。"}, {"text": "春天", "is_correct": false, "explanation": "“春天”是季节，与“此时”不构成反义。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜深的一段时间，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "明天": "“明天”指将来的一天，与“此时”不构成反义。", "春天": "“春天”是季节，与“此时”不构成反义。", "深夜": "“深夜”指夜深的一段时间，与“此时”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "“清晨”指一天中的早晨时段，与“此时”不构成反义。"}, {"text": "夏天", "is_correct": false, "explanation": "“夏天”是季节，与“此时”不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周末尾的假日，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "清晨": "“清晨”指一天中的早晨时段，与“此时”不构成反义。", "夏天": "“夏天”是季节，与“此时”不构成反义。", "周末": "“周末”指一周末尾的假日，与“此时”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "此时是说话时的这个时候。", "primary_collocate": null, "pronunciation": "cǐ shí", "ipa": "tsʰɨ˨˩˦ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "此时天已经黑了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时我正在回家的路上。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时他心里非常紧张。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时外面下起了大雨。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时大家都安静了下来。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时的我只想好好睡一觉。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时她还不知道这件事。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八点钟，此时街上人很少。", "target_word": "此时", "complexity_tier": "T3", "furigana": "cǐ shí", "sentence_source": "generated"}, {"text": "他等了很久，此时有点累了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都睡了，此时屋里很安静。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "此时此刻", "label": "复合"}], "register": "书面", "sense_fingerprint": "指说话或叙述时正在发生的这个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“天已经黑了”的时点相符。"}, {"text": "明天", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与指向将来的“明天”相冲突。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：“去年”指整整一年，不能用来指傍晚天黑的某个时刻。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不表示天色变暗的具体时刻。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“天已经黑了”的时点相符。", "明天": "体貌：“已经”表示动作已经完成，与指向将来的“明天”相冲突。", "去年": "搭配：“去年”指整整一年，不能用来指傍晚天黑的某个时刻。", "春天": "语义：“春天”是季节，不表示天色变暗的具体时刻。"}, "sentence_index": 0, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们把学校建在此时了。", "explanation": "这里应该用〈此地〉。“建在”需要处所，此时是时间，不能作地点。"}, {"text": "他在此时工作了三个小时。", "explanation": "这里应该用〈这段时间〉。“此时”指一个时间点，不能与表示持续时段的“工作了三个小时”搭配。"}, {"text": "会议开始前请大家准时到场，此时我们再讨论。", "explanation": "这里应该用〈届时〉。“届时”指将来的某个时候，此时指当前，与“会议开始前”的未来时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“还不知道”所描述的时间状态相符。"}, {"text": "结局", "is_correct": false, "explanation": "语义：“结局”指事情最终的结果，不能作时间状语表示“现在”。"}, {"text": "时期", "is_correct": false, "explanation": "搭配：“时期”需要修饰语才能作时间状语，不能单独放在“还不知道”前。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，与“她还不知道这件事”的状态不相容。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“还不知道”所描述的时间状态相符。", "结局": "语义：“结局”指事情最终的结果，不能作时间状语表示“现在”。", "时期": "搭配：“时期”需要修饰语才能作时间状语，不能单独放在“还不知道”前。", "结束": "语义：“结束”表示终止，与“她还不知道这件事”的状态不相容。"}, "sentence_index": 6, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们都睡了，我把玩具放在此时了。", "explanation": "这里应该用〈桌上〉这类处所词。“此时”是时间，不能作“放”的处所。"}, {"text": "孩子们都睡了，此时我们明天去公园。", "explanation": "这里应该用〈届时〉或〈明天〉这类将来时间词。“此时”指说话时的当下，不能与“明天去公园”的将来安排连用。"}, {"text": "孩子们都睡了，屋里此时安静了一整个学期。", "explanation": "这里应该用〈这段时间〉。“此时”是时间点，不能与“一整个学期”这种时段搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此时过街上已经没有人了。", "corrected_sentence": "此时街上已经没有人了。", "error_description": "错误：“此时”后面加了“过”。正确：“此时街上已经没有人了。”此时是时间名词，后面不接“过”，“过”只能跟在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此时了街上已经很安静。", "corrected_sentence": "此时街上已经很安静。", "error_description": "错误：“此时”后面直接加了“了”。正确：“此时街上已经很安静。”此时是时间名词，后面不接“了”，“了”应放在动词或形容词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "早晨", "is_correct": false, "explanation": "“早晨”指一天的一个时段，与“此时”不构成反义。"}, {"text": "明天", "is_correct": false, "explanation": "“明天”指将来的一天，与“此时”不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周末尾的假日，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "早晨": "“早晨”指一天的一个时段，与“此时”不构成反义。", "明天": "“明天”指将来的一天，与“此时”不构成反义。", "周末": "“周末”指一周末尾的假日，与“此时”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
