INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这个时候；现在。", "primary_collocate": null, "pronunciation": "cǐ shí", "ipa": "tsʰɨ˨˩˦ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "此时正是春天，花都开了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛到了最后，此时大家都站了起来。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时你应该好好休息。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时我才明白他的意思。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来了，此时山里很美。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进教室，此时老师正在讲课。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时的北京已经很冷了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟响了十二下，此时已经是半夜了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她接到电话，此时心里很高兴。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时我们已经到了机场。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "此时此刻", "label": "复合"}], "register": "书面", "sense_fingerprint": "这个时候，现在，承接前文所说的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“正是春天”的时间描述相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与“正是春天”的季节相矛盾，不能用在这里。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是另一个季节，与“正是春天”相冲突。"}, {"text": "午夜", "is_correct": false, "explanation": "搭配：“午夜”是一天中的某个时刻，不能和“正是春天”这种季节说法搭配。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“正是春天”的时间描述相符。", "冬天": "语义：“冬天”与“正是春天”的季节相矛盾，不能用在这里。", "夏天": "语义：“夏天”是另一个季节，与“正是春天”相冲突。", "午夜": "搭配：“午夜”是一天中的某个时刻，不能和“正是春天”这种季节说法搭配。"}, "sentence_index": 0, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把行李放在此时了。", "explanation": "这里应该用〈车上〉这类处所词。“此时”是时间，不能作“放”的处所。"}, {"text": "他在此时学了三年英语。", "explanation": "这里应该用〈这段时间〉。“此时”是时间点，不能与“学了三年”这种时段搭配。"}, {"text": "明天上午十点请大家准时到会议室，此时我们开始讨论。", "explanation": "这里应该用〈届时〉。“明天上午十点”指将来，此时指当前，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“北京已经很冷了”的时间语境相符。"}, {"text": "盛夏", "is_correct": false, "explanation": "语义：“盛夏”是一年中最热的季节，与“已经很冷了”相矛盾。"}, {"text": "三伏", "is_correct": false, "explanation": "语义：“三伏”指夏天最热的时段，与“很冷了”相矛盾。"}, {"text": "暑假", "is_correct": false, "explanation": "搭配：“暑假”是一段假期，不能与“很冷了”这种天气描述搭配。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“北京已经很冷了”的时间语境相符。", "盛夏": "语义：“盛夏”是一年中最热的季节，与“已经很冷了”相矛盾。", "三伏": "语义：“三伏”指夏天最热的时段，与“很冷了”相矛盾。", "暑假": "搭配：“暑假”是一段假期，不能与“很冷了”这种天气描述搭配。"}, "sentence_index": 6, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天就到机场，此时已经到了。", "explanation": "这里应该用〈届时〉。“此时”指当下，不能与“明天就到”的将来时间并列。"}, {"text": "我们在此时里等飞机。", "explanation": "这里应该用〈候机厅里〉。“此时”是时间，不能作处所，“此时里”不通。"}, {"text": "我们在此时走了三个小时才到机场。", "explanation": "这里应该用〈这段时间〉。“此时”是时间点，不能与“走了三个小时”这种时段搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此时过花都开了。", "corrected_sentence": "此时花都开了。", "error_description": "错误：“此时”后面加了“过”。正确：“此时花都开了。”此时是时间名词，后面不接“过”，“过”只能跟在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此时了天气很冷。", "corrected_sentence": "此时天气很冷。", "error_description": "错误：“此时”后面直接加了“了”。正确：“此时天气很冷。”此时是时间名词，后面不接“了”，“了”应放在动词或形容词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "正确：无名，指没有名声、不为人知，与“著名”相反。"}, {"text": "勇敢", "is_correct": false, "explanation": "非反义：勇敢指不怕危险、有胆量，与名声的有无无关。"}, {"text": "清澈", "is_correct": false, "explanation": "非反义：清澈指水或空气干净透明，与名声的有无无关。"}, {"text": "朴素", "is_correct": false, "explanation": "非反义：朴素指简单不华丽，与名声无关。"}], "correct_answer": "无名", "explanations": {"无名": "正确：无名，指没有名声、不为人知，与“著名”相反。", "勇敢": "非反义：勇敢指不怕危险、有胆量，与名声的有无无关。", "清澈": "非反义：清澈指水或空气干净透明，与名声的有无无关。", "朴素": "非反义：朴素指简单不华丽，与名声无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "正确：无名，指没有名声、不为人知，与“著名”相反。"}, {"text": "神秘", "is_correct": false, "explanation": "非反义：神秘指难以理解，与名声无关。"}, {"text": "简陋", "is_correct": false, "explanation": "非反义：简陋指粗糙简单，与名声无关。"}, {"text": "湿润", "is_correct": false, "explanation": "非反义：湿润指含有较多水分，与名声无关。"}], "correct_answer": "无名", "explanations": {"无名": "正确：无名，指没有名声、不为人知，与“著名”相反。", "神秘": "非反义：神秘指难以理解，与名声无关。", "简陋": "非反义：简陋指粗糙简单，与名声无关。", "湿润": "非反义：湿润指含有较多水分，与名声无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "著名是很多人都知道,很有名。", "primary_collocate": null, "pronunciation": "zhù míng", "ipa": "ʈʂu˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "长城是世界上很著名的地方。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在我们学校很著名。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的书很著名，我也看过。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做的蛋糕在这条街上很著名。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故宫是北京最著名的景点之一。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个著名的演员今天来我们城市了。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路因为小吃而著名，晚上人很多。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是著名的足球运动员，大家都认识他。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方以茶著名，游客都来买茶叶。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道那位著名的作家吗？", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容很多人都知道、很有名，可作定语或谓语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '022b152c-b6f1-4ed2-be3b-0dae6b156b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "著名", "is_correct": true, "explanation": "正确：著名，指很多人都知道、很有名。"}, {"text": "署名", "is_correct": false, "explanation": "署名（shǔmíng）与著名声母不同（sh 与 zh），意思是在文件上签写名字。"}, {"text": "住民", "is_correct": false, "explanation": "住民（zhùmín）韵尾 n 与 ng 不同，意思是居住的人，不是有名。"}, {"text": "书名", "is_correct": false, "explanation": "书名（shūmíng）与著名声母不同（sh 与 zh）且声调不同，意思是书的名称。"}, {"text": "著迷", "is_correct": false, "explanation": "著迷（zhùmí）少了鼻韵尾 ng，意思是十分喜爱、入迷。"}], "explanations": {"著名": "正确：著名，指很多人都知道、很有名。", "署名": "署名（shǔmíng）与著名声母不同（sh 与 zh），意思是在文件上签写名字。", "住民": "住民（zhùmín）韵尾 n 与 ng 不同，意思是居住的人，不是有名。", "书名": "书名（shūmíng）与著名声母不同（sh 与 zh）且声调不同，意思是书的名称。", "著迷": "著迷（zhùmí）少了鼻韵尾 ng，意思是十分喜爱、入迷。"}, "sentence_index": null, "correct_answer": "著名"}, "level_3": {"options": [{"text": "苦", "is_correct": false, "explanation": "语义：苦说味道，不能用来形容地方的名气。"}, {"text": "著名", "is_correct": true, "explanation": "正确：著名，表示有名声，修饰“地方”。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚说人的想法或做法，不用来形容地方。"}, {"text": "透明", "is_correct": false, "explanation": "语义：透明说物体的状态，不能用来形容地方。"}], "explanations": {"苦": "语义：苦说味道，不能用来形容地方的名气。", "著名": "正确：著名，表示有名声，修饰“地方”。", "幼稚": "搭配：幼稚说人的想法或做法，不用来形容地方。", "透明": "语义：透明说物体的状态，不能用来形容地方。"}, "sentence_index": 0, "correct_answer": "著名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的温度很著名，学生都觉得很冷。", "explanation": "这里应该用〈高〉或〈低〉。著名指名声，不能用来形容温度。"}, {"text": "这个人的个子很著名，走在人群里很显眼。", "explanation": "这里应该用〈高〉。著名指名声，不能用来形容身高。"}, {"text": "这套家具的颜色很著名，搭配起来很漂亮。", "explanation": "这里应该用〈好看〉。著名指名声，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "著名", "is_correct": true, "explanation": "正确：著名，指很多人都知道、很有名。"}, {"text": "指名", "is_correct": false, "explanation": "指名（zhǐmíng）韵母 u 与 i 不同，意思是点名或指定，不是有名。"}, {"text": "除名", "is_correct": false, "explanation": "除名（chúmíng）声母 zh 与 ch 不同且声调不同，意思是取消名籍。"}, {"text": "注定", "is_correct": false, "explanation": "注定（zhùdìng）后一音节声母 m 与 d 不同，意思是事先已经决定。"}, {"text": "驻京", "is_correct": false, "explanation": "驻京（zhùjīng）后一音节声母 m 与 j 不同，意思是在首都驻扎。"}], "explanations": {"著名": "正确：著名，指很多人都知道、很有名。", "指名": "指名（zhǐmíng）韵母 u 与 i 不同，意思是点名或指定，不是有名。", "除名": "除名（chúmíng）声母 zh 与 ch 不同且声调不同，意思是取消名籍。", "注定": "注定（zhùdìng）后一音节声母 m 与 d 不同，意思是事先已经决定。", "驻京": "驻京（zhùjīng）后一音节声母 m 与 j 不同，意思是在首都驻扎。"}, "sentence_index": null, "correct_answer": "著名"}, "level_3": {"options": [{"text": "烫", "is_correct": false, "explanation": "语义：烫说温度，与“因为小吃而”不搭配。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：矮说高低，不能说因为小吃而矮。"}, {"text": "著名", "is_correct": true, "explanation": "正确：著名，表示因小吃而有名声，与“因为……而”搭配。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：窄说宽度，不能说因为小吃而窄。"}], "explanations": {"烫": "语义：烫说温度，与“因为小吃而”不搭配。", "矮": "搭配：矮说高低，不能说因为小吃而矮。", "著名": "正确：著名，表示因小吃而有名声，与“因为……而”搭配。", "窄": "搭配：窄说宽度，不能说因为小吃而窄。"}, "sentence_index": 6, "correct_answer": "著名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的电脑速度很著名，打字很快。", "explanation": "这里应该用〈快〉。著名指名声，不能用来形容速度。"}, {"text": "这把椅子很著名，坐上去很硬。", "explanation": "这里应该用〈硬〉或〈舒服〉。著名指名声，不能用来形容椅子的舒适程度。"}, {"text": "这本书的价格很著名，买的人不多。", "explanation": "这里应该用〈贵〉。著名指名声，不能用来形容价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCL