INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位医生在我们城市比著名。", "corrected_sentence": "这位医生在我们城市很著名。", "error_description": "“比”后面要有比较对象，表示程度应用“很”，应说“很著名”，不能说“比著名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家饭店在城里的著名。", "corrected_sentence": "那家饭店在城里很著名。", "error_description": "“著名”作谓语前要用程度副词“很”，不能用“的”，否则句子不完整。错误：在城里的著名；正确：在城里很著名。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
