INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89049, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛看到事物或景象。", "primary_collocate": null, "pronunciation": "jiàn dào", "ipa": "tɕjɛn˥˩ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "晚上我在山上见到了很多星星。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门，就见到桌上有一封信。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑了，我什么也没见到。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次见到雪，高兴极了。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你见到我的黑色书包了吗？", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，我们在天上见到了一道彩虹。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到河边，他见到水里有几条鱼。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在这里，你能见到远处的海。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路上见到一只受伤的小狗。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见到火，马上大声喊人。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见到了", "label": "体标"}, {"form": "见到过", "label": "体标"}, {"form": "見到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "见到：用眼睛看到事物或景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 进门 (Zipf 3.6), 桌上 (Zipf 3.95), 一封信 (Zipf 3.75)']::text[], '022b152c-b6f1-4ed2-be3b-0dae6b156b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。见到指用眼睛看到事物或景象。"}, {"text": "交到", "is_correct": false, "explanation": "jiāo（第一声）与 jiàn（第四声）韵母不同（-iao 与 -ian），意思是交到（朋友）。"}, {"text": "叫到", "is_correct": false, "explanation": "jiào（第四声）与 jiàn 韵母不同（-iao 与 -ian），意思是叫到（名字）。"}, {"text": "降到", "is_correct": false, "explanation": "jiàng（第四声）与 jiàn 韵母不同（-iang 与 -ian），意思是降到（某个温度或水平）。"}, {"text": "讲到", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàn 的韵母和声调都不同，意思是讲到（某个话题）。"}], "explanations": {"见到": "正确。见到指用眼睛看到事物或景象。", "交到": "jiāo（第一声）与 jiàn（第四声）韵母不同（-iao 与 -ian），意思是交到（朋友）。", "叫到": "jiào（第四声）与 jiàn 韵母不同（-iao 与 -ian），意思是叫到（名字）。", "降到": "jiàng（第四声）与 jiàn 韵母不同（-iang 与 -ian），意思是降到（某个温度或水平）。", "讲到": "jiǎng（第三声）与 jiàn 的韵母和声调都不同，意思是讲到（某个话题）。"}, "sentence_index": null, "correct_answer": "见到"}, "level_3": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。句中说在山上用眼睛看到很多星星，“见到”表示看到。"}, {"text": "买到", "is_correct": false, "explanation": "搭配：“买到”的对象是商品，星星不能买。"}, {"text": "收到", "is_correct": false, "explanation": "语义：“收到”指接受信件、礼物等，与“在山上看到星星”的语境无关。"}, {"text": "吃光", "is_correct": false, "explanation": "搭配：“吃光”的对象是食物，星星不能吃。"}], "explanations": {"见到": "正确。句中说在山上用眼睛看到很多星星，“见到”表示看到。", "买到": "搭配：“买到”的对象是商品，星星不能买。", "收到": "语义：“收到”指接受信件、礼物等，与“在山上看到星星”的语境无关。", "吃光": "搭配：“吃光”的对象是食物，星星不能吃。"}, "sentence_index": 0, "correct_answer": "见到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在楼下见到了一阵音乐声。", "explanation": "这里应该用〈听到〉。见到指用眼睛看到，声音要用听到。"}, {"text": "厨房里飘着饭香，我见到了那股饭的香味。", "explanation": "这里应该用〈闻到〉。见到指用眼睛看到，气味要用闻到。"}, {"text": "一阵冷风吹来，我见到了身上的寒意。", "explanation": "这里应该用〈感到〉。见到指用眼睛看到，身体感受的寒冷要用感到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。见到指用眼睛看到事物或景象。"}, {"text": "减到", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是减到（某个数量）。"}, {"text": "变到", "is_correct": false, "explanation": "biàn 与 jiàn 声母不同（b 与 j），意思是变到（某种状态）。"}, {"text": "点到", "is_correct": false, "explanation": "diǎn（第三声）与 jiàn 声母与声调都不同，意思是点到（为止）。"}, {"text": "教到", "is_correct": false, "explanation": "jiāo（第一声）与 jiàn 韵母不同（-iao 与 -ian），意思是教到（某一课）。"}], "explanations": {"见到": "正确。见到指用眼睛看到事物或景象。", "减到": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是减到（某个数量）。", "变到": "biàn 与 jiàn 声母不同（b 与 j），意思是变到（某种状态）。", "点到": "diǎn（第三声）与 jiàn 声母与声调都不同，意思是点到（为止）。", "教到": "jiāo（第一声）与 jiàn 韵母不同（-iao 与 -ian），意思是教到（某一课）。"}, "sentence_index": null, "correct_answer": "见到"}, "level_3": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。句中在河边用眼睛看到水里的鱼。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：“闻到”用鼻子感知气味，句中说的是看到鱼，不是闻到。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”的对象是可以吃的东西，句中水里的鱼只是所见的情景。"}, {"text": "尝到", "is_correct": false, "explanation": "语义：“尝到”用舌头感知味道，与句中的视觉情景不符。"}], "explanations": {"见到": "正确。句中在河边用眼睛看到水里的鱼。", "闻到": "语义：“闻到”用鼻子感知气味，句中说的是看到鱼，不是闻到。", "吃掉": "语义：“吃掉”的对象是可以吃的东西，句中水里的鱼只是所见的情景。", "尝到": "语义：“尝到”用舌头感知味道，与句中的视觉情景不符。"}, "sentence_index": 6, "correct_answer": "见到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想了很久，才见到这个办法。", "explanation": "这里应该用〈想到〉。见到指用眼睛看到，想出办法要用想到。"}, {"text": "这时我才见到时间不早了。", "explanation": "这里应该用〈意识到〉。见到指用眼睛看到，对情况的认识要用意识到。"}, {"text": "这道汤很鲜，我见到了鲜味。", "explanation": "这里应该用〈尝到〉。见到指用眼睛看到，味道要用尝到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在院子里见到着一只小猫。", "corrected_sentence": "我昨天在院子里见到了一只小猫。", "error_description": "“见到”后面不能接“着”，应该用“了”。错误：见到着；正确：见到了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在河边不见到一只白鹭。", "corrected_sentence": "我在河边没见到一只白鹭。", "error_description": "表示已经发生或没有发生的事实时，否定要用“没”，不能用“不”。错误：不见到；正确：没见到。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
