INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89054, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "医治；治疗。", "primary_collocate": null, "pronunciation": "zhì", "ipa": "ʈʂɨ˥˩", "syllable_count": 1, "sentences": [{"text": "医生说这种病能治好。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿伤治了半年。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病很难治。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的咳嗽用中药治好了。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒要早点治，别拖成肺炎。", "target_word": "治", "complexity_tier": "T3", "furigana": "gǎn mào yào zǎo diǎn zhì, bié tuō chéng fèi yán.", "sentence_source": "generated"}, {"text": "医生正在给他治病。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病没法治。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头疼是医生治好的。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的牙病治了三次才好。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸得了重病，家里花钱给他治。", "target_word": "治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "治了", "label": "体标"}, {"form": "治过", "label": "体标"}, {"form": "治病", "label": "复合"}], "register": "中性", "sense_fingerprint": "医治疾病或伤痛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d475774-63da-4f28-b9ba-360faaf19fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "治", "is_correct": true, "explanation": "治（zhì）指医治疾病或伤痛，是本题答案。"}, {"text": "字", "is_correct": false, "explanation": "zì（第四声）与 zhì 声母不同（z/zh），意思是字。"}, {"text": "是", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh/zh），意思是是。"}, {"text": "这", "is_correct": false, "explanation": "zhè 与 zhì 韵母不同（e/i），意思是这。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是直。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是纸。"}], "explanations": {"治": "治（zhì）指医治疾病或伤痛，是本题答案。", "字": "zì（第四声）与 zhì 声母不同（z/zh），意思是字。", "是": "shì 与 zhì 声母不同（sh/zh），意思是是。", "这": "zhè 与 zhì 韵母不同（e/i），意思是这。", "直": "zhí（第二声）与 zhì（第四声）声调不同，意思是直。", "纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是纸。"}, "sentence_index": null, "correct_answer": "治"}, "level_3": {"options": [{"text": "治", "is_correct": true, "explanation": "正确：“治好”指通过医治使病痊愈，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，不能用来指医治疾病。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿好”多指衣物，不能用于疾病。"}, {"text": "摆", "is_correct": false, "explanation": "语义：“摆”指陈设摆放，与疾病的医治无关。"}], "explanations": {"治": "正确：“治好”指通过医治使病痊愈，符合句意。", "洗": "语义：“洗”指清洗，不能用来指医治疾病。", "穿": "搭配：“穿好”多指衣物，不能用于疾病。", "摆": "语义：“摆”指陈设摆放，与疾病的医治无关。"}, "sentence_index": 0, "correct_answer": "治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生治了一下身体，发现他很健康。", "explanation": "这里应该用〈检查〉。治指医治病症，身体健康时只能说检查，不能说治。"}, {"text": "消防员治了被困的人，把他们带出了火场。", "explanation": "这里应该用〈救〉。治指医治病伤，不指把人从危险中救出。"}, {"text": "工人治好了坏掉的水管。", "explanation": "这里应该用〈修〉。治多用于人或动物的病伤，器物坏了要说修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89054, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "治", "is_correct": true, "explanation": "治（zhì）指医治疾病或伤痛，是本题答案。"}, {"text": "自", "is_correct": false, "explanation": "zì（第四声）与 zhì 声母不同（z/zh），意思是自己。"}, {"text": "试", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh/zh），意思是试验。"}, {"text": "知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是知道。"}, {"text": "值", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是价值。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是手指。"}], "explanations": {"治": "治（zhì）指医治疾病或伤痛，是本题答案。", "自": "zì（第四声）与 zhì 声母不同（z/zh），意思是自己。", "试": "shì 与 zhì 声母不同（sh/zh），意思是试验。", "知": "zhī（第一声）与 zhì（第四声）声调不同，意思是知道。", "值": "zhí（第二声）与 zhì（第四声）声调不同，意思是价值。", "指": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是手指。"}, "sentence_index": null, "correct_answer": "治"}, "level_3": {"options": [{"text": "治", "is_correct": true, "explanation": "正确：“没法治”指无法医治，符合句意。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象是物件或包装，不能说拆病。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛弃丢掉，与疾病的医治无关。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”指把物品折叠整理，不能用于疾病。"}], "explanations": {"治": "正确：“没法治”指无法医治，符合句意。", "拆": "搭配：“拆”的对象是物件或包装，不能说拆病。", "扔": "语义：“扔”指抛弃丢掉，与疾病的医治无关。", "叠": "搭配：“叠”指把物品折叠整理，不能用于疾病。"}, "sentence_index": 6, "correct_answer": "治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈治干净了厨房的地板。", "explanation": "这里应该用〈擦〉。治指医治病伤，不指清洁地面。"}, {"text": "厨师治好了汤的味道。", "explanation": "这里应该用〈调〉。治用于人或动物的病伤，调味道要用调。"}, {"text": "他治了这份合同，明天就签字。", "explanation": "这里应该用〈办理〉。治表示办理义时只用于治丧等少数搭配，不能用于合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EX