INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消灭是让坏东西一点也不剩，没有了。", "primary_collocate": null, "pronunciation": "xiāo miè", "ipa": "ɕiɑʊ˥ miɛ˥˩", "syllable_count": 2, "sentences": [{"text": "大家都想消灭贫穷。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要消灭战争。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好办法能消灭家里的臭味。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器消灭了空气中的脏东西。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想消灭自己的坏习惯。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要消灭作弊的现象。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水可以消灭衣服上的细菌。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里消灭了这种病。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有努力，才能消灭无知。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗手液能消灭手上的细菌。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消灭了", "label": "体标"}, {"form": "消灭过", "label": "体标"}, {"form": "消滅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "消灭：让坏东西、坏现象彻底没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消灭", "is_correct": true, "explanation": "消灭：使贫穷不存在，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：贫穷不值得“欣赏”，句意荒谬。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”一般接生活、快乐等，不能接“贫穷”。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有贫穷”不合常理，句意不通。"}], "explanations": {"消灭": "消灭：使贫穷不存在，符合句意。", "欣赏": "语义：贫穷不值得“欣赏”，句意荒谬。", "享受": "搭配：“享受”一般接生活、快乐等，不能接“贫穷”。", "拥有": "语义：“拥有贫穷”不合常理，句意不通。"}, "sentence_index": 0, "correct_answer": "消灭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要消灭好心情。", "explanation": "这里应该用〈保持〉。消灭只用于要除掉的坏东西，“好心情”是好的，应该用保持。"}, {"text": "警察要消灭社会秩序。", "explanation": "这里应该用〈维持〉。秩序是要保护的好东西，应该用维持，消灭只用于坏东西。"}, {"text": "老师消灭了这个学生。", "explanation": "这里应该用〈培养〉。消灭的对象是要除掉的坏东西，学生是人，应该用培养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消灭", "is_correct": true, "explanation": "消灭：使细菌不存在，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只能接衣物，不能接“细菌”，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：细菌不能被“修理”，句意不通。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：热水不会“喜欢”细菌，主语与动词不搭，句意荒谬。"}], "explanations": {"消灭": "消灭：使细菌不存在，符合句意。", "穿": "搭配：“穿”只能接衣物，不能接“细菌”，句意不通。", "修理": "语义：细菌不能被“修理”，句意不通。", "喜欢": "语义：热水不会“喜欢”细菌，主语与动词不搭，句意荒谬。"}, "sentence_index": 6, "correct_answer": "消灭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天到了，雪慢慢消灭了。", "explanation": "这里应该用〈消失〉。雪自己不见了，没有人或东西去除掉它，不能说消灭。"}, {"text": "春天到了，冰慢慢消灭了。", "explanation": "这里应该用〈融化〉。冰遇热变成水，不是被除掉，应该用融化。"}, {"text": "太阳出来后，雾气消灭了。", "explanation": "这里应该用〈消散〉。雾气自然散开，没有施事去除掉它，应该用消散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要努力消灭了这种疾病。", "corrected_sentence": "我们要努力消灭这种疾病。", "error_description": "错误：“要”表示将来，句子里不能用“了”。正确：“要努力消灭这种疾病”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把地上的污渍彻底消灭了过。", "corrected_sentence": "妈妈把地上的污渍彻底消灭了。", "error_description": "错误：“了”和“过”不能同时用在动词后面，应去掉“过”。正确：“彻底消灭了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
