INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使不存在；除掉。", "primary_collocate": null, "pronunciation": "xiāo miè", "ipa": "ɕiɑʊ˥ miɛ˥˩", "syllable_count": 2, "sentences": [{"text": "医生想消灭病人身上的细菌。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用药消灭田里的害虫。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要消灭房间里的蚊子。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能消灭老鼠。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察消灭了这个犯罪团伙。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光可以消灭很多细菌。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想消灭桌上所有的蚂蚁。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们消灭了山上的敌人。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，要消灭家里的苍蝇。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用火消灭了树上的虫子。", "target_word": "消灭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消灭了", "label": "体标"}, {"form": "消灭过", "label": "体标"}, {"form": "消滅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "消灭：把害虫、敌人等除掉，使不存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消灭", "is_correct": true, "explanation": "消灭：使细菌不存在，符合句意。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：医生不会想“照顾”细菌，句意不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：细菌不值得“欣赏”，句意荒谬。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只能接衣物，不能接“细菌”。"}], "explanations": {"消灭": "消灭：使细菌不存在，符合句意。", "照顾": "语义：医生不会想“照顾”细菌，句意不通。", "欣赏": "语义：细菌不值得“欣赏”，句意荒谬。", "穿": "搭配：“穿”只能接衣物，不能接“细菌”。"}, "sentence_index": 0, "correct_answer": "消灭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停后，彩虹慢慢消灭了。", "explanation": "这里应该用〈消失〉。消灭需要有人或东西去除掉某物，彩虹是自己消失的，不能说消灭。"}, {"text": "我们在车站消灭了两个小时。", "explanation": "这里应该用〈消磨〉。消灭的对象是要被除掉的东西，时间不能被消灭，等候的时间要用消磨。"}, {"text": "学校消灭了这次考试。", "explanation": "这里应该用〈取消〉。考试不是要被除掉的坏东西，已经安排好的考试应该用取消。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消灭", "is_correct": true, "explanation": "消灭：使蚂蚁不存在，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：蚂蚁不能被“修理”，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只能接歌曲，不能接“蚂蚁”。"}, {"text": "缝", "is_correct": false, "explanation": "语义：蚂蚁不是可以“缝”的东西，句意荒谬。"}], "explanations": {"消灭": "消灭：使蚂蚁不存在，符合句意。", "修理": "语义：蚂蚁不能被“修理”，句意不通。", "唱": "搭配：“唱”只能接歌曲，不能接“蚂蚁”。", "缝": "语义：蚂蚁不是可以“缝”的东西，句意荒谬。"}, "sentence_index": 6, "correct_answer": "消灭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司消灭了三分之一的成本。", "explanation": "这里应该用〈削减〉。消灭是使事物整个不存在，成本只能减少一部分，应该用削减。"}, {"text": "这台老电脑很快就消灭了很多电。", "explanation": "这里应该用〈消耗〉。消灭是使东西不存在，电是被用掉的，耗电要用消耗。"}, {"text": "他一个上午就消灭了全部精力。", "explanation": "这里应该用〈耗尽〉。精力是慢慢用完的，不是被消灭的东西，应该用耗尽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决心消灭了这种传染病。", "corrected_sentence": "政府决心消灭这种传染病。", "error_description": "错误：“消灭”后面多加了“了”。“决心”后面是打算做的事，还没有发生，不能用“了”，应为“决心消灭这种传染病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把厨房里的蟑螂消灭干净了过。", "corrected_sentence": "工人们把厨房里的蟑螂消灭干净了。", "error_description": "错误：“了”和“过”不能同时用在动词后面，应去掉“过”。正确：“消灭干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
