INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89061, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通知是把事情告诉别人,让大家知道。", "primary_collocate": null, "pronunciation": "tōng zhī", "ipa": "tʰʊŋ˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "妈妈通知全家人周末去奶奶家。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长通知同学们明天带伞。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司通知乘客飞机晚点了。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经通知过他了，他说会来。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区通知居民明天停水。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板通知员工下周放假三天。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个好消息通知朋友们。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没通知我们要考试。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们通知我面试改在周五。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了通知小王明天不用来。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通知了", "label": "体标"}, {"form": "通知过", "label": "体标"}, {"form": "通知书", "label": "复合"}], "register": "中性", "sense_fingerprint": "通知:把事情告诉别人让大家知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89061, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通知", "is_correct": true, "explanation": "通知：把事情告诉别人，让大家知道，是本次听辨的目标词。"}, {"text": "同志", "is_correct": false, "explanation": "tóngzhì（第二声）与 tōngzhī（第一声）声调不同，意思是志同道合的人。"}, {"text": "同时", "is_correct": false, "explanation": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是在同一时间。"}, {"text": "统治", "is_correct": false, "explanation": "tǒngzhì 与 tōngzhī 两个音节的声调都不同，意思是支配、管理。"}, {"text": "同事", "is_correct": false, "explanation": "shì 与 zhī 声母不同（sh 与 zh），意思是一起工作的人。"}, {"text": "通识", "is_correct": false, "explanation": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是普遍的知识。"}], "explanations": {"通知": "通知：把事情告诉别人，让大家知道，是本次听辨的目标词。", "同志": "tóngzhì（第二声）与 tōngzhī（第一声）声调不同，意思是志同道合的人。", "同时": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是在同一时间。", "统治": "tǒngzhì 与 tōngzhī 两个音节的声调都不同，意思是支配、管理。", "同事": "shì 与 zhī 声母不同（sh 与 zh），意思是一起工作的人。", "通识": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是普遍的知识。"}, "sentence_index": null, "correct_answer": "通知"}, "level_3": {"options": [{"text": "通知", "is_correct": true, "explanation": "通知：把事情告诉大家，与“周末去奶奶家”的安排相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽，与去奶奶家的安排不相容。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是庆贺，不能用来告知一项安排。"}, {"text": "询问", "is_correct": false, "explanation": "搭配：“询问”要带问题或询问的内容，不能直接接这样的安排陈述。"}], "explanations": {"通知": "通知：把事情告诉大家，与“周末去奶奶家”的安排相符。", "嘲笑": "语义：“嘲笑”是讥讽，与去奶奶家的安排不相容。", "祝贺": "语义：“祝贺”是庆贺，不能用来告知一项安排。", "询问": "搭配：“询问”要带问题或询问的内容，不能直接接这样的安排陈述。"}, "sentence_index": 0, "correct_answer": "通知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师通知了一个故事。", "explanation": "这里应该用〈讲〉。讲故事是叙述内容，“通知”用于告知事情，不能接“故事”作宾语。"}, {"text": "他对我通知了感谢。", "explanation": "这里应该用〈表达〉。表达感谢要用“表达”，“通知”不能接“感谢”作宾语。"}, {"text": "她通知了一首歌。", "explanation": "这里应该用〈唱〉。唱歌是表演，“通知”不能接“歌”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89061, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通知", "is_correct": true, "explanation": "通知：把事情告诉大家，与“好消息”的告知语境相符。"}, {"text": "分享", "is_correct": false, "explanation": "配价：“分享”的接受者要用“给”引出，不能直接接“朋友们”。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是话题，不能与“朋友们”这样的人直接搭配。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞人，“好消息”不能被表扬。"}], "explanations": {"通知": "通知：把事情告诉大家，与“好消息”的告知语境相符。", "分享": "配价：“分享”的接受者要用“给”引出，不能直接接“朋友们”。", "讨论": "搭配：“讨论”的对象是话题，不能与“朋友们”这样的人直接搭配。", "表扬": "语义：“表扬”是称赞人，“好消息”不能被表扬。"}, "sentence_index": 6, "correct_answer": "通知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师通知了他的努力。", "explanation": "这里应该用〈夸奖〉。称赞努力要用“夸奖”，“通知”不能接“努力”作宾语。"}, {"text": "他通知了一场。", "explanation": "这里应该用〈哭〉。哭是情绪的表现，“通知”不能用来描述哭这件事。"}, {"text": "他通知了一幅画。", "explanation": "这里应该用〈画〉。画画是创作，“通知”不能接“画”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没通知了他这件事。", "corrected_sentence": "我还没通知他这件事。", "error_description": "错误在于“了”。“没”否定已经发生的动作，动词后不能再加“了”，应说“没通知他”，不能说“没通知了他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这份资料通知了同事们。", "corrected_sentence": "请把这份资料通知同事们。", "error_description": "错误在于“了”。“请”表示要求对方去做的事，还没有发生，动词后不能用“了”，应说“请把这份资料通知同事们”，不能说“通知了同事们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
