INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89064, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于连接和管理计算机网络的硬件，如路由器、交换机。", "primary_collocate": null, "pronunciation": "wǎng luò shè bèi", "ipa": "u̯ɑŋ˨˩˦ lu̯ɔ˥˩ ʂɤ˥˩ pei̯˥˩", "syllable_count": 4, "sentences": [{"text": "路由器和交换机都是网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机房里的网络设备要定期检查。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门生产网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在管理公司的网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络设备出了问题，整栋楼都断网了。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据中心里有成百上千台网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚学会设置网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学的网络设备每年都要更新。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种网络设备可以连接很多台计算机。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太旧的网络设备容易出问题。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}], "register": "中性", "sense_fingerprint": "连接和管理计算机网络的硬件，如路由器、交换机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水果", "is_correct": false, "explanation": "语义：路由器和交换机是网络硬件，不是水果，句子不通。"}, {"text": "网络设备", "is_correct": true, "explanation": "正确：路由器和交换机都属于连接和管理网络的硬件，即“网络设备”。"}, {"text": "动物", "is_correct": false, "explanation": "语义：路由器和交换机不是动物，与句意不符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：路由器和交换机不是家具，句子不通。"}], "explanations": {"水果": "语义：路由器和交换机是网络硬件，不是水果，句子不通。", "网络设备": "正确：路由器和交换机都属于连接和管理网络的硬件，即“网络设备”。", "动物": "语义：路由器和交换机不是动物，与句意不符。", "家具": "语义：路由器和交换机不是家具，句子不通。"}, "sentence_index": 0, "correct_answer": "网络设备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师正在管理公司的一辆网络设备。", "explanation": "这里应该用〈台〉。“辆”用于车辆，“网络设备”是机器，要用量词“台”。"}, {"text": "公司新买了一把网络设备。", "explanation": "这里应该用〈台〉。“把”用于带柄的东西或椅子，“网络设备”是机器，要用量词“台”。"}, {"text": "工程师在机房里装了一条网络设备。", "explanation": "这里应该用〈台〉。“条”用于细长的东西，“网络设备”是机器，要用量词“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "搭配：“设置”多用于参数、功能，不能搭配“心情”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不能被设置，句子不通。"}, {"text": "网络设备", "is_correct": true, "explanation": "正确：“设置”可以用于网络设备，符合“他刚学会设置”的语境。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能被设置，与句意不符。"}], "explanations": {"心情": "搭配：“设置”多用于参数、功能，不能搭配“心情”。", "天空": "语义：天空是自然景物，不能被设置，句子不通。", "网络设备": "正确：“设置”可以用于网络设备，符合“他刚学会设置”的语境。", "月亮": "语义：月亮是天体，不能被设置，与句意不符。"}, "sentence_index": 6, "correct_answer": "网络设备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在浏览器里输入了网络设备。", "explanation": "这里应该用〈网址〉。“输入”用于网址、文字，网络设备是硬件，不能输入到浏览器里。"}, {"text": "他每天在家里唱网络设备。", "explanation": "这里应该用〈歌曲〉。“唱”用于歌曲、戏曲，网络设备是硬件，不能唱。"}, {"text": "他在网络设备里结识了很多朋友。", "explanation": "这里的“网络”指社交平台或人际关系网，“网络设备”只指连接网络的硬件，不能用来结交朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机房里新装了一位网络设备。", "corrected_sentence": "机房里新装了一台网络设备。", "error_description": "量词错误：“网络设备”是机器，应用量词“台”。“位”只用于人，用在这里不对，正确说法是“一台网络设备”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师昨晚终于调好了一网络设备。", "corrected_sentence": "工程师昨晚终于调好了一台网络设备。", "error_description": "量词缺失：“网络设备”是可数的机器，数词“一”后要加量词“台”，不能说“一网络设备”，应说“一台网络设备”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陌生", "is_correct": true, "explanation": "陌生与“熟悉”互为反义，指对人或事物不了解。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃指态度庄重，与“熟悉”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序，与“熟悉”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖指温度适宜或让人感到亲切，与“熟悉”没有反义关系。"}], "correct_answer": "陌生", "explanations": {"陌生": "陌生与“熟悉”互为反义，指对人或事物不了解。", "严肃": "严肃指态度庄重，与“熟悉”没有反义关系。", "整齐": "整齐指排列有序，与“熟悉”没有反义关系。", "温暖": "温暖指温度适宜或让人感到亲切，与“熟悉”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
