INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "清楚地了解；知道得很详细。", "primary_collocate": null, "pronunciation": "shú xī", "ipa": "ʂu˧˥ ɕi˥", "syllable_count": 2, "sentences": [{"text": "他很熟悉公司的工作流程。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工要先熟悉业务。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生熟悉这种药的用法。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师熟悉中国历史。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，请大家熟悉一下资料。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我熟悉这个软件的所有功能。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师熟悉相关的法律。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她熟悉每道菜的做法。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先熟悉规则，再参加比赛。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对棋谱很熟悉。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟悉了", "label": "体标"}, {"form": "熟悉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对事物、业务了解得清楚详细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d475774-63da-4f28-b9ba-360faaf19fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熟悉", "is_correct": true, "explanation": "正确：“很熟悉公司的工作流程”表示了解得清楚，符合句意。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”是行为动词，不能受“很”修饰。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”指同意核准，与了解程度无关。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”是行为动作，不能受“很”修饰。"}], "explanations": {"熟悉": "正确：“很熟悉公司的工作流程”表示了解得清楚，符合句意。", "拒绝": "搭配：“拒绝”是行为动词，不能受“很”修饰。", "批准": "语义：“批准”指同意核准，与了解程度无关。", "讨论": "搭配：“讨论”是行为动作，不能受“很”修饰。"}, "sentence_index": 0, "correct_answer": "熟悉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他熟悉红色。", "explanation": "这里应该用〈喜欢〉。熟悉表示了解得清楚，不表示喜爱。"}, {"text": "他熟悉了这种快乐，每天都在笑。", "explanation": "这里应该用〈感到〉。熟悉的对象是人、地方或事务，不指一种情绪。"}, {"text": "他熟悉了好成绩。", "explanation": "这里应该用〈取得〉。熟悉的对象是人、地方或事务，不能与“成绩”这类结果搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟悉", "is_correct": true, "explanation": "正确：“律师熟悉相关的法律”表示了解得清楚，符合句意。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”的对象是动物，不能用于法律。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶，不说修剪法律。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒播种子，与法律无关。"}], "explanations": {"熟悉": "正确：“律师熟悉相关的法律”表示了解得清楚，符合句意。", "饲养": "语义：“饲养”的对象是动物，不能用于法律。", "修剪": "搭配：“修剪”的对象是枝叶，不说修剪法律。", "播种": "语义：“播种”指撒播种子，与法律无关。"}, "sentence_index": 6, "correct_answer": "熟悉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他熟悉了这场大雪，马上关上了门。", "explanation": "这里应该用〈看到〉。熟悉的对象是人、地方或事务，不指看到自然现象。"}, {"text": "他熟悉了这次地震，只好躲在桌子下面。", "explanation": "这里应该用〈遭遇〉。熟悉的对象是人、地方或事务，不指遭遇突发的地震。"}, {"text": "他熟悉了花瓶，很后悔。", "explanation": "这里应该用〈打碎〉。熟悉指对人、地方或事务了解清楚，不指损坏某物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不把熟悉这份工作。", "corrected_sentence": "他不熟悉这份工作。", "error_description": "“把”字句误用：“熟悉”单用不能直接进入“把”字句，需带补充成分（如“熟悉一下”）才能构成“把”字句，应说“他不熟悉这份工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这套软件熟悉地很快。", "corrected_sentence": "他对这套软件熟悉得很快。", "error_description": "结构助词误用：“熟悉”后引出补语应用“得”，“地”只用于状语，应说“熟悉得很快”，不能说“熟悉地很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
