INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过人是比一般人还要强。", "primary_collocate": null, "pronunciation": "guò rén", "ipa": "kuo˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他的记忆力过人，什么都记得住。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生胆识过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就聪明过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师的耐心过人，从不发火。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气过人，一个人搬起了大桌子。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的本领过人，大家都很佩服。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的音乐天分过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中表现出过人的勇气。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼力过人，一眼就看出了问题。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的精力过人，天天工作到很晚。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过人之处", "label": "复合"}], "register": "中性", "sense_fingerprint": "能力、品质比一般人还要强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人读 guò rén，意思是超过一般人。"}, {"text": "国人", "is_correct": false, "explanation": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。"}, {"text": "果仁", "is_correct": false, "explanation": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。"}, {"text": "阔人", "is_correct": false, "explanation": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。"}, {"text": "过门", "is_correct": false, "explanation": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。"}, {"text": "故人", "is_correct": false, "explanation": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}], "explanations": {"过人": "正确。过人读 guò rén，意思是超过一般人。", "国人": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。", "果仁": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。", "阔人": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。", "过门": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。", "故人": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}, "sentence_index": null, "correct_answer": "过人"}, "level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与后半句“什么都记得住”相符。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”表示能力弱，与“什么都记得住”正相反。"}, {"text": "健忘", "is_correct": false, "explanation": "语义：“健忘”指容易忘事，与“什么都记得住”矛盾。"}, {"text": "平凡", "is_correct": false, "explanation": "搭配：“平凡”说人或事普通，一般不用来形容记忆力的强弱。"}], "explanations": {"过人": "正确。过人表示超过一般人，与后半句“什么都记得住”相符。", "差": "语义：“差”表示能力弱，与“什么都记得住”正相反。", "健忘": "语义：“健忘”指容易忘事，与“什么都记得住”矛盾。", "平凡": "搭配：“平凡”说人或事普通，一般不用来形容记忆力的强弱。"}, "sentence_index": 0, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的缺点过人，大家都知道。", "explanation": "这里应该用〈突出〉。过人只形容能力、品质等正面的优点，不能用来说缺点。"}, {"text": "这个方案的设计很过人，评委都很满意。", "explanation": "这里应该用〈出色〉。过人形容人的能力、品质，不能用来形容方案的设计这类成果。"}, {"text": "她的长相过人，走到哪儿都很引人注目。", "explanation": "这里应该用〈出众〉。过人形容能力、品质，不能用来形容长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与“音乐天分”的褒义语境相符。"}, {"text": "虚弱", "is_correct": false, "explanation": "语义：“虚弱”形容身体状态，与“音乐天分”无关，也不能说天分的高低。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”指内容单调乏味，不能用来形容天分。"}, {"text": "呆滞", "is_correct": false, "explanation": "体貌：“呆滞”多形容眼神、表情，不用来形容天分。"}], "explanations": {"过人": "正确。过人表示超过一般人，与“音乐天分”的褒义语境相符。", "虚弱": "语义：“虚弱”形容身体状态，与“音乐天分”无关，也不能说天分的高低。", "枯燥": "语义：“枯燥”指内容单调乏味，不能用来形容天分。", "呆滞": "体貌：“呆滞”多形容眼神、表情，不用来形容天分。"}, "sentence_index": 6, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次胜利的意义过人。", "explanation": "这里应该用〈非凡〉。过人只形容人的能力、品质，不能用来说事情的意义。"}, {"text": "这座大楼的外观过人，一眼就能看见。", "explanation": "这里应该用〈醒目〉。过人形容人的能力或品质，不能用来形容建筑的外观。"}, {"text": "这项改革的效果过人，大家都看到了。", "explanation": "这里应该用〈显著〉。过人不能用来形容改革的效果这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有过人地体力，能扛起一百斤的米袋。", "corrected_sentence": "他有过人的体力，能扛起一百斤的米袋。", "error_description": "错误：“过人”修饰名词“体力”时要用“的”，不能用“地”（“地”用于修饰动词或形容词作状语）。应改为“过人的体力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他身上有不少过人的之处，大家都很佩服。", "corrected_sentence": "他身上有不少过人之处，大家都很佩服。", "error_description": "错误：“过人之处”是固定的复合词，“之”已表示“……的地方”，后面不能再加“的”。应改为“过人之处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
