INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超过一般人的。", "primary_collocate": null, "pronunciation": "guò rén", "ipa": "kuo˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他有过人的本事。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩有过人的才华。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的胆量过人，敢一个人走夜路。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队靠着过人的速度赢了比赛。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有过人之处，大家都愿意听他的。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板有过人的眼光，选对了地方。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员的体力过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记性过人，看一遍就会了。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功的人往往有过人的毅力。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么过人之处吗？", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过人之处", "label": "复合"}], "register": "中性", "sense_fingerprint": "修饰才能、品质，指超过一般人的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人读 guò rén，意思是超过一般人的。"}, {"text": "国人", "is_correct": false, "explanation": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。"}, {"text": "果仁", "is_correct": false, "explanation": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。"}, {"text": "阔人", "is_correct": false, "explanation": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。"}, {"text": "过门", "is_correct": false, "explanation": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。"}, {"text": "故人", "is_correct": false, "explanation": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}], "explanations": {"过人": "正确。过人读 guò rén，意思是超过一般人的。", "国人": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。", "果仁": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。", "阔人": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。", "过门": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。", "故人": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}, "sentence_index": null, "correct_answer": "过人"}, "level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与“本事”搭配，意思是本领超群。"}, {"text": "生疏", "is_correct": false, "explanation": "搭配：“生疏”说不熟练，与“本事”的强弱搭配不通。"}, {"text": "狭隘", "is_correct": false, "explanation": "语义：“狭隘”形容心胸或见识，不能用来修饰“本事”。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”形容做事的方式不灵活，不能用来说本领的高低。"}], "explanations": {"过人": "正确。过人表示超过一般人，与“本事”搭配，意思是本领超群。", "生疏": "搭配：“生疏”说不熟练，与“本事”的强弱搭配不通。", "狭隘": "语义：“狭隘”形容心胸或见识，不能用来修饰“本事”。", "呆板": "语义：“呆板”形容做事的方式不灵活，不能用来说本领的高低。"}, "sentence_index": 0, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题过人，需要马上解决。", "explanation": "这里应该用〈突出〉。过人形容人的能力或品质超过一般人，不能用来说问题。"}, {"text": "这部纪录片的画面很过人，获得了不少好评。", "explanation": "这里应该用〈精彩〉。过人形容人的能力、品质，不能用来形容画面这类事物。"}, {"text": "她的长相过人，一看就知道是明星。", "explanation": "这里应该用〈出众〉。过人形容能力、品质，不能用来形容长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与“运动员”的强项语境相符。"}, {"text": "虚弱", "is_correct": false, "explanation": "语义：“虚弱”说身体弱，与“运动员”的身份矛盾。"}, {"text": "柔弱", "is_correct": false, "explanation": "体貌：“柔弱”多形容人的身形或气质，不用来说体力。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易被损坏，与“运动员”的体力要求矛盾。"}], "explanations": {"过人": "正确。过人表示超过一般人，与“运动员”的强项语境相符。", "虚弱": "语义：“虚弱”说身体弱，与“运动员”的身份矛盾。", "柔弱": "体貌：“柔弱”多形容人的身形或气质，不用来说体力。", "脆弱": "语义：“脆弱”指容易被损坏，与“运动员”的体力要求矛盾。"}, "sentence_index": 6, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的历史过人。", "explanation": "这里应该用〈非凡〉。过人只形容人的能力、品质，不能用来形容历史。"}, {"text": "这家店的招牌过人，老远就能看见。", "explanation": "这里应该用〈醒目〉。过人不能用来形容招牌这类物品。"}, {"text": "这种药的疗效过人，三天就好了。", "explanation": "这里应该用〈显著〉。过人形容人的能力、品质，不能用来形容药的疗效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小伙子有过人得体能，连续跑了三小时。", "corrected_sentence": "这个小伙子有过人的体能，连续跑了三小时。", "error_description": "错误：“过人”修饰名词“体能”时，中间要用结构助词“的”。“得”是补语标记，不能用来修饰名词。应改为“过人的体能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有过人地听力，隔着两个房间都能听见门响。", "corrected_sentence": "她有过人的听力，隔着两个房间都能听见门响。", "error_description": "错误：“过人”修饰名词“听力”，要用“的”，不能用“地”（“地”多用于修饰动词）。应改为“过人的听力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后段是一件事或一段路的后面那一部分。", "primary_collocate": null, "pronunciation": "hòu duàn", "ipa": "xoʊ̯˥˩ tu̯an˥˩", "syllable_count": 2, "sentences": [{"text": "这条山路的后段比较难走。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的后段，他跑得越来越慢。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的后段有点儿没意思。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到路的后段，天已经黑了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的后段，我们住在海边。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的后段写得比前段好。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议的后段，大家都累了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马拉松后段，不少人都跑不动了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条路的前段很宽，后段很窄。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这节课的后段，老师让我们自己练习。", "target_word": "后段", "complexity_tier": "T3", "furigana": "zhè jié kè de hòu duàn, lǎo shī ràng wǒ men zì jǐ liàn xí.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一件事或一段路靠后的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是路段，不能说“比较难走”，句子说不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指山路靠后的一段，与“比较难走”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与山路的路况无关，“颜色比较难走”不通。"}, {"text": "后尘", "is_correct": false, "explanation": "语域：“后尘”是文言词，指车马过后扬起的尘土，描述路况不用。"}], "explanations": {"价格": "语义：“价格”不是路段，不能说“比较难走”，句子说不通。", "后段": "“后段”指山路靠后的一段，与“比较难走”相符。", "颜色": "语义：“颜色”与山路的路况无关，“颜色比较难走”不通。", "后尘": "语域：“后尘”是文言词，指车马过后扬起的尘土，描述路况不用。"}, "sentence_index": 0, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的后段坏了。", "explanation": "这里应该用〈后面〉。〈后段〉指一段路或过程靠后的部分，不指物体的后面。"}, {"text": "他的后段很疼。", "explanation": "这里应该用〈后背〉。〈后段〉不指身体部位。"}, {"text": "那条路上有一把后段特别陡。", "explanation": "这里的量词用错了。〈把〉用于有柄的东西，不能用来计量路段；路段应该用〈截〉，如〈一截路〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是会议的一部分，“会议的天气”说不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指会议靠后的一段时间，与“大家都累了”相符。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”不表示会议的一段，“会议的座位”说不通。"}, {"text": "末梢", "is_correct": false, "explanation": "语域：“末梢”是术语，指神经或枝条的末端，用在描述会议时不合语域。"}], "explanations": {"天气": "语义：“天气”不是会议的一部分，“会议的天气”说不通。", "后段": "“后段”指会议靠后的一段时间，与“大家都累了”相符。", "座位": "语义：“座位”不表示会议的一段，“会议的座位”说不通。", "末梢": "语域：“末梢”是术语，指神经或枝条的末端，用在描述会议时不合语域。"}, "sentence_index": 6, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要为后段着想，多留些资源。", "explanation": "这里应该用〈后辈〉。〈后段〉不指人，“为……着想”的对象应是人。"}, {"text": "他是我们的后段，总是默默支持我们。", "explanation": "这里应该用〈后盾〉。〈后段〉不指人，不能指给予支持的人。"}, {"text": "我们在后段种了很多花。", "explanation": "这里应该用〈后院〉。〈后段〉指路或过程的部分，不指一块场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们爬到了山路的后段们。", "corrected_sentence": "他们爬到了山路的后段。", "error_description": "错误：在“后段”后加了复数词尾“们”。“们”只能加在指人的名词后，“后段”指路段，应直接说“山路的后段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "选手们都落着后段。", "corrected_sentence": "选手们都落在后段。", "error_description": "错误：“落”后面用了“着”，“落着后段”不通。正确：说“落在后段”，“落”后要用介词“在”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一过程或路程中靠后的部分。", "primary_collocate": null, "pronunciation": "hòu duàn", "ipa": "xoʊ̯˥˩ tu̯an˥˩", "syllable_count": 2, "sentences": [{"text": "比赛进入后段，他的速度慢了下来。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的后段水很浅。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事的后段让我很感动。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目到了后段，大家都很忙。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公路的后段正在修路。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会的后段，歌迷一起唱歌。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的后段，我才发现时间不够了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车走到后段，旅客们都睡着了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子的后段声音越来越大。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次长跑的后段，我一直跟着他。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过程或路程中靠后的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开始", "is_correct": false, "explanation": "语义：“开始”指起点，不是比赛靠后的阶段，“进入开始”也不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指比赛靠后的阶段，与“进入”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是比赛的阶段，“进入颜色”说不通。"}, {"text": "后尘", "is_correct": false, "explanation": "语域：“后尘”是文言词，不用于描述比赛阶段，不合语域。"}], "explanations": {"开始": "语义：“开始”指起点，不是比赛靠后的阶段，“进入开始”也不通。", "后段": "“后段”指比赛靠后的阶段，与“进入”搭配自然。", "颜色": "语义：“颜色”不是比赛的阶段，“进入颜色”说不通。", "后尘": "语域：“后尘”是文言词，不用于描述比赛阶段，不合语域。"}, "sentence_index": 0, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在太阳下站久了，后段很疼。", "explanation": "这里应该用〈后脑勺〉。〈后段〉不指身体部位，也不指后脑勺。"}, {"text": "他是我的后段，比我小两岁。", "explanation": "这里应该用〈后代〉。〈后段〉指过程或路程的一部分，不指人。"}, {"text": "我们在路边看到了一只后段。", "explanation": "这里的量词用错了。〈只〉用于动物，〈后段〉不是动物，不能用〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是考试的一段，句子说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”与考试无关，“考试的饮料”说不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指考试靠后的时段，与“才发现时间不够”的语境相符。"}, {"text": "后序", "is_correct": false, "explanation": "语域：“后序”是书籍末尾的序文，不用于描述考试的时段，不合语域。"}], "explanations": {"价格": "语义：“价格”不是考试的一段，句子说不通。", "饮料": "语义：“饮料”与考试无关，“考试的饮料”说不通。", "后段": "“后段”指考试靠后的时段，与“才发现时间不够”的语境相符。", "后序": "语域：“后序”是书籍末尾的序文，不用于描述考试的时段，不合语域。"}, "sentence_index": 6, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在为后段操心，把钱都留给孩子。", "explanation": "这里应该用〈后人〉。〈后段〉不指人，不能作“为……操心”的对象。"}, {"text": "他从后段溜进了会场。", "explanation": "这里应该用〈后门〉。〈后段〉不指门或出入口，不能用于“从……溜进”。"}, {"text": "后段的战士一直在支援前线。", "explanation": "这里应该用〈后方〉。〈后段〉指过程或路程靠后的部分，不指地区，战士不在“后段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个项目快在后段了，大家得加快速度。", "corrected_sentence": "这个项目快到后段了，大家得加快速度。", "error_description": "错误：“到”误写成“在”，“快在后段了”不通。正确：说“快到后段了”，“到”后接表示阶段的“后段”，表示事情进展到了这一阶段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直落着队伍的后段。", "corrected_sentence": "他一直落在队伍的后段。", "error_description": "错误：“落”后面用了“着”，“落着队伍的后段”不通。正确：说“落在队伍的后段”，“落”后接处所要用介词“在”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
