INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一等是质量或水平最高、最好的。", "primary_collocate": null, "pronunciation": "yī děng", "ipa": "i˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家宾馆的房间是一等的，住起来很舒服。", "target_word": "一等", "complexity_tier": "T3", "furigana": "zhè jiā bīnguǎn de fángjiān shì yī děng de, zhù qǐlái hěn shūfu", "sentence_source": "generated"}, {"text": "这家店的茶是一等的，价格也高。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一等的米，做出来的饭很香。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台冰箱的材料是一等的，用了十几年还很好。", "target_word": "一等", "complexity_tier": "T3", "furigana": "zhè tái bīngxiāng de cáiliào shì yī děng de, yòng le shí jǐ nián hái hěn hǎo", "sentence_source": "generated"}, {"text": "老张的手艺是一等的，没有人比他好。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的篮球水平是一等的。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果都是一等的，一个坏的也没有。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的服务是一等的，病人都说好。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师做的鱼是一等的，客人吃了还想来。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布是一等的，摸起来很软。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一等奖", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容质量、水平排在第一级、最好，常说“是一等的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '022b152c-b6f1-4ed2-be3b-0dae6b156b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "语义：透明说物体的状态，不能用来形容房间的等级。"}, {"text": "一等", "is_correct": true, "explanation": "正确：一等，表示最好的等级，修饰“房间”。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：沉重多用来说负担或心情，不用来形容房间的质量。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸说味道，不能用来形容房间。"}], "explanations": {"透明": "语义：透明说物体的状态，不能用来形容房间的等级。", "一等": "正确：一等，表示最好的等级，修饰“房间”。", "沉重": "搭配：沉重多用来说负担或心情，不用来形容房间的质量。", "咸": "语义：咸说味道，不能用来形容房间。"}, "sentence_index": 0, "correct_answer": "一等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班的一等生。", "explanation": "这里应该用〈优等〉。“优等生”是固定说法，“一等”不能直接修饰“生”。"}, {"text": "这是一等大事，大家都很重视。", "explanation": "这里应该用〈头等〉。“头等大事”是固定说法，“一等”不能这样修饰“大事”。"}, {"text": "这家饭店的服务很一等，客人都很满意。", "explanation": "这里应该用〈一流〉。“一等”表示等级，不能用“很”修饰程度，应说“一流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烫", "is_correct": false, "explanation": "语义：烫说温度，不能用来形容苹果的质量等级。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：窄说宽度，不用来形容苹果。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：安静说人或环境的状态，不用来形容苹果。"}, {"text": "一等", "is_correct": true, "explanation": "正确：一等，表示质量最好的等级。"}], "explanations": {"烫": "语义：烫说温度，不能用来形容苹果的质量等级。", "窄": "搭配：窄说宽度，不用来形容苹果。", "安静": "搭配：安静说人或环境的状态，不用来形容苹果。", "一等": "正确：一等，表示质量最好的等级。"}, "sentence_index": 6, "correct_answer": "一等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣最一等，穿起来很舒服。", "explanation": "这里应该用〈上等〉。“一等”表示等级，不能和“最”一起表示程度，应说“最上等”。"}, {"text": "这件毛衣的袖子很一等，穿起来很暖和。", "explanation": "这里应该用〈精致〉。一等表示质量或名次的等级，不能用来形容袖子的样式。"}, {"text": "这件毛衣比那件更一等，穿起来很暖和。", "explanation": "这里应该用〈更好〉。“一等”是等级词，不能用“更”表示比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的牛肉是很一等的，很新鲜。", "corrected_sentence": "这家超市的牛肉是一等的，很新鲜。", "error_description": "“很”不能修饰“一等”这类等级词，应去掉“很”。错误：是很一等的；正确：是一等的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些茶叶都是一等地，喝起来很香。", "corrected_sentence": "这些茶叶都是一等的，喝起来很香。", "error_description": "“一等”作形容词放在“是”后面要用“的”，不能用“地”；“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
