INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89076, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比赛或评定中排在第一的名次等级。", "primary_collocate": null, "pronunciation": "yī děng", "ipa": "i˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次书法比赛，他拿到了一等。", "target_word": "一等", "complexity_tier": "T3", "furigana": "zhè cì shūfǎ bǐsài, tā nádào le yī děng", "sentence_source": "generated"}, {"text": "比赛分三等，她的画拿了一等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果分一等和二等，一等的更大。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的作文可以排在一等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厂的产品拿过一等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加中文演讲比赛，拿了一等。", "target_word": "一等", "complexity_tier": "T3", "furigana": "tā cānjiā Zhōngwén yǎnjiǎng bǐsài, ná le yī děng", "sentence_source": "generated"}, {"text": "全班只有三个人拿到一等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些茶叶分成一等、二等和三等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱歌比赛分三个等级，他唱得最好，拿了一等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跳舞跳得很好，比赛里拿了一等。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一等奖", "label": "复合"}], "register": "中性", "sense_fingerprint": "指分等级时的第一级，如考试、比赛、产品评定中的最高等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '022b152c-b6f1-4ed2-be3b-0dae6b156b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是身体症状，不是比赛中能拿到的东西。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：拿到的是名次或奖项，不说拿到水平。"}, {"text": "一等", "is_correct": true, "explanation": "正确：一等，表示比赛中的名次等级，可以拿到。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不能作为比赛的成绩。"}], "explanations": {"咳嗽": "语义：咳嗽是身体症状，不是比赛中能拿到的东西。", "水平": "搭配：拿到的是名次或奖项，不说拿到水平。", "一等": "正确：一等，表示比赛中的名次等级，可以拿到。", "花园": "语义：花园是地方，不能作为比赛的成绩。"}, "sentence_index": 0, "correct_answer": "一等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次作文比赛，她拿了最一等。", "explanation": "这里应该用〈第一〉。“一等”是等级词，不能用“最”修饰。"}, {"text": "这次演讲比赛，他一等了第一名。", "explanation": "这里应该用〈拿到〉。“一等”是名次词，不能作动词表示获得名次。"}, {"text": "这次歌唱比赛，她的成绩很一等。", "explanation": "这里应该用〈优秀〉。“一等”表示名次等级，不能用“很”修饰成绩的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以获得的成绩或名次。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：拿到的是奖项或名次，不说拿到感冒。"}, {"text": "一等", "is_correct": true, "explanation": "正确：一等，比赛中的名次等级，可以拿到。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能作为比赛的等级。"}], "explanations": {"窗户": "语义：窗户不是可以获得的成绩或名次。", "感冒": "搭配：拿到的是奖项或名次，不说拿到感冒。", "一等": "正确：一等，比赛中的名次等级，可以拿到。", "桌子": "语义：桌子不能作为比赛的等级。"}, "sentence_index": 6, "correct_answer": "一等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跳舞跳得很好，比赛里一等了奖。", "explanation": "这里应该用〈拿到〉。“一等”是名次词，不能表示获得奖项，应说“拿到”。"}, {"text": "她跳舞跳得很好，比赛里拿了一等的第一。", "explanation": "这里应该用〈第一〉或〈一等〉二选一。两者都表示名次，不能一起用。"}, {"text": "她跳舞跳得很好，比赛里拿了最一等。", "explanation": "这里应该用〈第一名〉。“一等”是等级词，不能用“最”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次歌唱比赛，她拿了很一等。", "corrected_sentence": "这次歌唱比赛，她拿了一等。", "error_description": "“很”是程度副词，不能修饰表示名次的“一等”，应去掉“很”。错误：拿了很一等；正确：拿了一等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次跳舞比赛，他拿了到一等。", "corrected_sentence": "这次跳舞比赛，他拿到了一等。", "error_description": "“拿到”是动补结构，“了”应放在“拿到”后面，应说“拿到了一等”，不能说“拿了到一等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
