INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89082, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示不能自主;禁不住。", "primary_collocate": null, "pronunciation": "bù yóu", "ipa": "pu˥˩ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "听着熟悉的老歌,他不由跟着唱了起来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到考试成绩,小李不由叹了一口气。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着窗外的大雨,不由担心起明天的比赛。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的表演太精彩了,大家不由鼓起掌来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到老家,他不由想念起去世的爷爷。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的风吹过来,我不由缩了缩脖子。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说朋友要搬家,我心里不由难过起来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见桌上的蛋糕,不由笑着说:“真漂亮!”", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路过小时候的学校,她不由放慢了脚步。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着这么多人在等他,他不由紧张起来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不由得", "label": "复合"}, {"form": "不由自主", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词:表示不能自主,禁不住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 风吹 (Zipf 3.3), 缩 (Zipf 3.96), 缩 (Zipf 3.96)']::text[], '34e4f915-c7ee-4ce3-bf47-a2dc5330ff4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不由", "is_correct": true, "explanation": "不由表示不能自主，与听到熟悉的老歌后忍不住跟着唱的情形相符。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何，与听熟悉老歌时自然跟唱的情形不符。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”修饰勉强去做的动作，不能用来描写听歌时不由自主地跟唱。"}, {"text": "勉强", "is_correct": false, "explanation": "语义：“勉强”表示不情愿地去做，与熟悉老歌带来的自然反应相矛盾。"}], "explanations": {"不由": "不由表示不能自主，与听到熟悉的老歌后忍不住跟着唱的情形相符。", "只好": "语义：“只好”表示无可奈何，与听熟悉老歌时自然跟唱的情形不符。", "硬": "搭配：“硬”修饰勉强去做的动作，不能用来描写听歌时不由自主地跟唱。", "勉强": "语义：“勉强”表示不情愿地去做，与熟悉老歌带来的自然反应相矛盾。"}, "sentence_index": 0, "correct_answer": "不由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛不由下大雨取消了。", "explanation": "这里应该用〈由于〉。不由表示不能自主，不能用来说明取消比赛的原因。"}, {"text": "我不由写了一封信给他，说明了我的计划。", "explanation": "不由表示不能自主，写信说明计划是有意识的行为，不能用“不由”来描写。"}, {"text": "我的手机不由响了起来。", "explanation": "不由只能用于人的心理或动作，手机没有意志，不能用“不由”描述它的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不由", "is_correct": true, "explanation": "不由表示不能自主，与听说朋友要搬家后心里忍不住难过的情形相符。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，心里的难过不能被有意制造，与语境矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做某事，不能用来描写心里慢慢产生的难过。"}, {"text": "一直", "is_correct": false, "explanation": "体貌：“一直”表示持续不断，与“起来”表示开始出现的意思不相容。"}], "explanations": {"不由": "不由表示不能自主，与听说朋友要搬家后心里忍不住难过的情形相符。", "故意": "语义：“故意”表示有意为之，心里的难过不能被有意制造，与语境矛盾。", "赶紧": "语义：“赶紧”表示急忙去做某事，不能用来描写心里慢慢产生的难过。", "一直": "体貌：“一直”表示持续不断，与“起来”表示开始出现的意思不相容。"}, "sentence_index": 6, "correct_answer": "不由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天下雨了，我们不由取消了比赛。", "explanation": "这里应该用〈只好〉。不由表示不能自主，不能用来表示迫于形势、没有选择的无奈决定。"}, {"text": "他不由赢得了比赛冠军。", "explanation": "不由表示不能自主，赢得冠军是努力争取的结果，不能用“不由”来说明。"}, {"text": "我妹妹不由找到了一份工作。", "explanation": "不由表示忍不住的反应，找工作是有意识的努力，不能用“不由”描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de3772e-9283-4a8f-8c34-ca9146ad51e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
