INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89095, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "云是天上白白的一团一团的东西。", "primary_collocate": null, "pronunciation": "yún", "ipa": "yn˧˥", "syllable_count": 1, "sentences": [{"text": "蓝天上有一朵云。", "target_word": "云", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明喜欢看天上的云。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云一团一团的，像白色的棉花。", "target_word": "云", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天没有云，天很蓝。", "target_word": "云", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们躺在草地上看云。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云是白色的，雨天的云是黑色的。", "target_word": "云", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，云就动了。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拍了几张云的照片。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那片云很大，也很白。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的云比城市里的多。", "target_word": "云", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "白云", "label": "复合"}, {"form": "乌云", "label": "复合"}, {"form": "云朵", "label": "复合"}, {"form": "雲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天上白色一团一团的云", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1081a25-9b81-4cdc-b757-e82976d3359f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89095, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "云", "is_correct": true, "explanation": "云（yún）：天上白白的一团一团的东西。"}, {"text": "运", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是运动、运气。"}, {"text": "允", "is_correct": false, "explanation": "yǔn（第三声）与 yún（第二声）声调不同，意思是允许。"}, {"text": "晕", "is_correct": false, "explanation": "yūn（第一声）与 yún（第二声）声调不同，意思是头晕、眩晕。"}, {"text": "孕", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是怀孕。"}], "explanations": {"云": "云（yún）：天上白白的一团一团的东西。", "运": "yùn（第四声）与 yún（第二声）声调不同，意思是运动、运气。", "允": "yǔn（第三声）与 yún（第二声）声调不同，意思是允许。", "晕": "yūn（第一声）与 yún（第二声）声调不同，意思是头晕、眩晕。", "孕": "yùn（第四声）与 yún（第二声）声调不同，意思是怀孕。"}, "sentence_index": null, "correct_answer": "云"}, "level_3": {"options": [{"text": "云", "is_correct": true, "explanation": "云：天上白色的一团一团的东西，可以用量词“朵”计量。"}, {"text": "花", "is_correct": false, "explanation": "语义：花长在地面上，不会出现在蓝天上。"}, {"text": "冰花", "is_correct": false, "explanation": "体貌：冰花是结在玻璃上的固体纹样，形体不能在天空中飘浮。"}, {"text": "玫瑰", "is_correct": false, "explanation": "语义：玫瑰是地上的植物，不会长在蓝天上。"}], "explanations": {"云": "云：天上白色的一团一团的东西，可以用量词“朵”计量。", "花": "语义：花长在地面上，不会出现在蓝天上。", "冰花": "体貌：冰花是结在玻璃上的固体纹样，形体不能在天空中飘浮。", "玫瑰": "语义：玫瑰是地上的植物，不会长在蓝天上。"}, "sentence_index": 0, "correct_answer": "云"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上有一颗云，又大又白。", "explanation": "这里应该用〈朵〉或〈团〉。“颗”用于星星、珠子这类小而圆的东西，云不用“颗”。"}, {"text": "窗外下起了大云，路上都湿了。", "explanation": "这里应该用〈雨〉。下雨不能说“下云”，云不会落下来，落下来的是雨。"}, {"text": "厨房的烟囱里冒出很多云。", "explanation": "这里应该用〈烟〉。烟囱里冒出的是燃烧产生的烟，云指天上的水汽凝结物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89095, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "云", "is_correct": true, "explanation": "云（yún）：天上白白的一团一团的东西。"}, {"text": "韵", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是韵律、押韵。"}, {"text": "圆", "is_correct": false, "explanation": "yuán 与 yún 韵母不同，声调相同，意思是圆形。"}, {"text": "元", "is_correct": false, "explanation": "yuán 与 yún 韵母不同，声调相同，意思是货币单位“元”。"}, {"text": "熨", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是用熨斗把衣服烫平。"}], "explanations": {"云": "云（yún）：天上白白的一团一团的东西。", "韵": "yùn（第四声）与 yún（第二声）声调不同，意思是韵律、押韵。", "圆": "yuán 与 yún 韵母不同，声调相同，意思是圆形。", "元": "yuán 与 yún 韵母不同，声调相同，意思是货币单位“元”。", "熨": "yùn（第四声）与 yún（第二声）声调不同，意思是用熨斗把衣服烫平。"}, "sentence_index": null, "correct_answer": "云"}, "level_3": {"options": [{"text": "云", "is_correct": true, "explanation": "云：风一吹就会移动的白色云团，与“风一吹……动了”相符。"}, {"text": "山", "is_correct": false, "explanation": "语义：山是固定的大地形，风吹不会动。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头形体坚硬固定，风一吹不会移动。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是固定的建筑，风吹不会移动。"}], "explanations": {"云": "云：风一吹就会移动的白色云团，与“风一吹……动了”相符。", "山": "语义：山是固定的大地形，风吹不会动。", "石头": "体貌：石头形体坚硬固定，风一吹不会移动。", "房子": "语义：房子是固定的建筑，风吹不会移动。"}, "sentence_index": 6, "correct_answer": "云"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上挂着一根云，细细的。", "explanation": "这里应该用〈朵〉或〈团〉。“根”用于细长的东西，云不用“根”。"}, {"text": "桌子上落了一层云。", "explanation": "这里应该用〈灰〉。云在天上，不会落在桌子上，落在桌上的是灰。"}, {"text": "茶杯上方飘着云。", "explanation": "这里应该用〈热气〉。茶杯上方升起的是热气，云是天上的水汽凝结物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处飘来一个云。", "corrected_sentence": "远处飘来一团云。", "error_description": "量词错误：“云”在这里应与量词“团”搭配，说“一团云”，不说“一个云”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖面上空飘着一座云。", "corrected_sentence": "湖面上空飘着一团云。", "error_description": "量词错误：“座”用于山、房屋等大型固定的东西，云不用“座”。应说“一团云”，不说“一座云”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
