INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89099, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "立是直直地站着，或把东西直直地放好。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "他笔直地立在门口，一动也不动。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地里立着一棵很高的树。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把伞立在墙边。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们立在国旗下面。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把梯子立在墙上，慢慢爬了上去。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上立着一座白色的塔。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人立在河边，看着远处的船。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门前立着一对石狮子。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书立在桌子上，好让大家都看见。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路口立着一块牌子，上面写着地名。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "立着", "label": "体标"}, {"form": "立正", "label": "复合"}], "register": "书面", "sense_fingerprint": "直直地站着或把东西竖直放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1a0300-a4d2-44ca-8527-0106e0d41547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89099, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立", "is_correct": true, "explanation": "立：直直地站着，或把东西直直地放好，正是本词的意思。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，礼指礼节，不是站立。"}, {"text": "理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，理指道理或整理，不是站立。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，里指里面或距离单位，不是站立。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，离指离开或距离，不是站立。"}, {"text": "逆", "is_correct": false, "explanation": "nì 与 lì 声母不同（n 对 l），逆指相反或违背，不是站立。"}], "explanations": {"立": "立：直直地站着，或把东西直直地放好，正是本词的意思。", "礼": "lǐ（第三声）与 lì（第四声）声调不同，礼指礼节，不是站立。", "理": "lǐ（第三声）与 lì（第四声）声调不同，理指道理或整理，不是站立。", "里": "lǐ（第三声）与 lì（第四声）声调不同，里指里面或距离单位，不是站立。", "离": "lí（第二声）与 lì（第四声）声调不同，离指离开或距离，不是站立。", "逆": "nì 与 lì 声母不同（n 对 l），逆指相反或违背，不是站立。"}, "sentence_index": null, "correct_answer": "立"}, "level_3": {"options": [{"text": "立", "is_correct": true, "explanation": "正确：“他笔直地立在门口”指他直直地站在门口。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑表示移动，与“一动也不动”矛盾。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳表示身体跃起，与“一动也不动”矛盾。"}, {"text": "游", "is_correct": false, "explanation": "搭配：游需要水，“游在门口”不符合常用搭配。"}], "explanations": {"立": "正确：“他笔直地立在门口”指他直直地站在门口。", "跑": "语义：跑表示移动，与“一动也不动”矛盾。", "跳": "语义：跳表示身体跃起，与“一动也不动”矛盾。", "游": "搭配：游需要水，“游在门口”不符合常用搭配。"}, "sentence_index": 0, "correct_answer": "立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把饭菜立在桌上，招呼我们吃饭。", "explanation": "这里应该用〈放〉。立指直直地站着或竖着放，一般摆放饭菜要用放，不能用立。"}, {"text": "他吃完饭就立在床上睡觉。", "explanation": "这里应该用〈躺〉。立表示站着或竖放，睡觉要躺，不能用立。"}, {"text": "他立在地上给长辈磕头。", "explanation": "这里应该用〈跪〉。立表示站着，磕头要跪，不能用立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89099, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "立", "is_correct": true, "explanation": "立：直直地站着，或把东西直直地放好，正是本词的意思。"}, {"text": "李", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，李指李子或姓氏，不是站立。"}, {"text": "梨", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，梨是水果，不是站立。"}, {"text": "腻", "is_correct": false, "explanation": "nì 与 lì 声母不同（n 对 l），腻指油脂多或黏，不是站立。"}], "explanations": {"立": "立：直直地站着，或把东西直直地放好，正是本词的意思。", "李": "lǐ（第三声）与 lì（第四声）声调不同，李指李子或姓氏，不是站立。", "梨": "lí（第二声）与 lì（第四声）声调不同，梨是水果，不是站立。", "腻": "nì 与 lì 声母不同（n 对 l），腻指油脂多或黏，不是站立。"}, "sentence_index": null, "correct_answer": "立"}, "level_3": {"options": [{"text": "立", "is_correct": true, "explanation": "正确：“老人立在河边”指老人直直地站在河边。"}, {"text": "飞", "is_correct": false, "explanation": "语义：飞指在空中移动，老人站在河边不能说“飞”。"}, {"text": "钻", "is_correct": false, "explanation": "语义：钻指往洞或缝隙里进，与“在河边看船”不符。"}, {"text": "放", "is_correct": false, "explanation": "搭配：放需要带宾语，“老人放在河边”缺少宾语，不成立。"}], "explanations": {"立": "正确：“老人立在河边”指老人直直地站在河边。", "飞": "语义：飞指在空中移动，老人站在河边不能说“飞”。", "钻": "语义：钻指往洞或缝隙里进，与“在河边看船”不符。", "放": "搭配：放需要带宾语，“老人放在河边”缺少宾语，不成立。"}, "sentence_index": 6, "correct_answer": "立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把帽子立在头上，笑个不停。", "explanation": "这里应该用〈戴〉。立表示站着或竖放，帽子应戴在头上，不能用立。"}, {"text": "他立着走进教室，把书包放在桌上。", "explanation": "这里应去掉“立着”。立指静止地站立，不能用来描述“走进”这类移动动作。"}, {"text": "他立着坐在椅子上看书。", "explanation": "这里的“立”指站立，与“坐在椅子上”矛盾；表示坐得笔直要说〈端坐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木板立了在墙边，准备刷漆。", "corrected_sentence": "他把木板立在墙边，准备刷漆。", "error_description": "“立”表示放置后的状态，接处所时不加体标“了”。应去掉“了”，写作“他把木板立在墙边，准备刷漆。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
