INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89100, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "站；使物体竖直地放着。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "孩子立在妈妈身边，不说话。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旗杆立在院子中间。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边立着一排高高的柳树。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把木桩一根根立在地上。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师立在黑板前，看着同学们。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把镜子立在桌上，开始化妆。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上立着一个小小的牌子。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家立在路边，等着车队过来。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把瓶子立在桌上，别让水流出来。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口立着一块大石头。", "target_word": "立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "立着", "label": "体标"}, {"form": "立正", "label": "复合"}], "register": "书面", "sense_fingerprint": "站立；使物体竖直放着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1a0300-a4d2-44ca-8527-0106e0d41547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89100, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立", "is_correct": true, "explanation": "立：站立，或使物体竖直地放着，正是本词的意思。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，礼指礼节，不是站立。"}, {"text": "理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，理指道理或整理，不是站立。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，里指里面或距离单位，不是站立。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，离指离开或距离，不是站立。"}, {"text": "逆", "is_correct": false, "explanation": "nì 与 lì 声母不同（n 对 l），逆指相反或违背，不是站立。"}], "explanations": {"立": "立：站立，或使物体竖直地放着，正是本词的意思。", "礼": "lǐ（第三声）与 lì（第四声）声调不同，礼指礼节，不是站立。", "理": "lǐ（第三声）与 lì（第四声）声调不同，理指道理或整理，不是站立。", "里": "lǐ（第三声）与 lì（第四声）声调不同，里指里面或距离单位，不是站立。", "离": "lí（第二声）与 lì（第四声）声调不同，离指离开或距离，不是站立。", "逆": "nì 与 lì 声母不同（n 对 l），逆指相反或违背，不是站立。"}, "sentence_index": null, "correct_answer": "立"}, "level_3": {"options": [{"text": "立", "is_correct": true, "explanation": "正确：“孩子立在妈妈身边，不说话”指孩子站在妈妈身边。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱需要带歌曲等宾语，“唱在妈妈身边”不成立。"}, {"text": "喊", "is_correct": false, "explanation": "语义：喊是发出声音，与“不说话”直接矛盾。"}, {"text": "飞", "is_correct": false, "explanation": "语义：飞指在空中移动，孩子不能“飞在”妈妈身边。"}], "explanations": {"立": "正确：“孩子立在妈妈身边，不说话”指孩子站在妈妈身边。", "唱": "搭配：唱需要带歌曲等宾语，“唱在妈妈身边”不成立。", "喊": "语义：喊是发出声音，与“不说话”直接矛盾。", "飞": "语义：飞指在空中移动，孩子不能“飞在”妈妈身边。"}, "sentence_index": 0, "correct_answer": "立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一辆汽车立在路边，司机下车买东西。", "explanation": "这里应该用〈停〉。立表示站着或竖放，车辆停靠要用停，不能用立。"}, {"text": "妈妈立在沙发上打毛衣。", "explanation": "这里应该用〈坐〉。立表示站着或竖放，坐在沙发上打毛衣不能用立。"}, {"text": "雨水立在地上，慢慢流走。", "explanation": "这里应该用〈积〉。立表示站着或竖放，液体停留在地面要用积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89100, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "立", "is_correct": true, "explanation": "立：站立，或使物体竖直地放着，正是本词的意思。"}, {"text": "李", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，李指李子或姓氏，不是站立。"}, {"text": "梨", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，梨是水果，不是站立。"}, {"text": "腻", "is_correct": false, "explanation": "nì 与 lì 声母不同（n 对 l），腻指油脂多或黏，不是站立。"}], "explanations": {"立": "立：站立，或使物体竖直地放着，正是本词的意思。", "李": "lǐ（第三声）与 lì（第四声）声调不同，李指李子或姓氏，不是站立。", "梨": "lí（第二声）与 lì（第四声）声调不同，梨是水果，不是站立。", "腻": "nì 与 lì 声母不同（n 对 l），腻指油脂多或黏，不是站立。"}, "sentence_index": null, "correct_answer": "立"}, "level_3": {"options": [{"text": "立", "is_correct": true, "explanation": "正确：“草地上立着一个小小的牌子”指牌子竖立在草地上。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是动物或人的动作，牌子不能被“咬着”。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳指身体跃起，牌子不会跳，与句意不符。"}, {"text": "游", "is_correct": false, "explanation": "搭配：游需要水，“草地上游着”不符合常用搭配。"}], "explanations": {"立": "正确：“草地上立着一个小小的牌子”指牌子竖立在草地上。", "咬": "语义：咬是动物或人的动作，牌子不能被“咬着”。", "跳": "语义：跳指身体跃起，牌子不会跳，与句意不符。", "游": "搭配：游需要水，“草地上游着”不符合常用搭配。"}, "sentence_index": 6, "correct_answer": "立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把眼镜立在鼻子上，看书很清楚。", "explanation": "这里应该用〈架〉。立表示站着或竖放，眼镜应架在鼻梁上。"}, {"text": "孩子们立着在操场上跑来跑去。", "explanation": "这里应去掉“立着”。立指静止地站立，不能与“跑来跑去”这类移动动作搭配。"}, {"text": "这只猫立在沙发上睡觉。", "explanation": "睡觉的姿势是躺或卧，不能用立，这里不符合本词的词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子在妈妈身边着立，不说话。", "corrected_sentence": "孩子在妈妈身边立着，不说话。", "error_description": "体标“着”必须放在“立”之后，表示持续状态，应写作“立着”，“着立”的语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
