INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89107, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平等", "is_correct": true, "explanation": "正确答案：平等与“等级”相对，指人与人之间没有高低层级之分。"}, {"text": "距离", "is_correct": false, "explanation": "“距离”是名词，但与“等级”没有反义关系，意思无关。"}, {"text": "颜色", "is_correct": false, "explanation": "“颜色”与“等级”无关，不是它的反义词。"}, {"text": "房子", "is_correct": false, "explanation": "“房子”与“等级”无关，不是它的反义词。"}], "correct_answer": "平等", "explanations": {"平等": "正确答案：平等与“等级”相对，指人与人之间没有高低层级之分。", "距离": "“距离”是名词，但与“等级”没有反义关系，意思无关。", "颜色": "“颜色”与“等级”无关，不是它的反义词。", "房子": "“房子”与“等级”无关，不是它的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
