INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按质量、程度等分成的级别。", "primary_collocate": null, "pronunciation": "děng jí", "ipa": "tɤŋ²¹⁴ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "这种茶叶分成三个等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的等级越高，价格也越高。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店按服务分等级，等级高的更贵。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩分五个等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业分成了A、B、C三个等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的质量等级很高。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的汉语水平是什么等级？", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院是全市最高等级的医院。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉有好几个等级，价格差别很大。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天空气质量的等级是良好。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个等级", "label": "量词"}, {"form": "等级制度", "label": "复合"}, {"form": "等級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按质量、水平、程度划分的级别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级（děng jí），指按质量、程度等分成的级别。"}, {"text": "登记", "is_correct": false, "explanation": "dēng 与 děng 声调不同，jì 与 jí 声调也不同，意思是登记（把情况记录在册）。"}, {"text": "蹬极", "is_correct": false, "explanation": "第一音节 dēng 与 děng 声调不同，第二音节 jí 相同，意思是蹬极（一种高空跳跃运动）。"}, {"text": "等积", "is_correct": false, "explanation": "第二音节 jī 与 jí 只有声调不同，意思是等积（面积相等）。"}], "explanations": {"等级": "正确答案：等级（děng jí），指按质量、程度等分成的级别。", "登记": "dēng 与 děng 声调不同，jì 与 jí 声调也不同，意思是登记（把情况记录在册）。", "蹬极": "第一音节 dēng 与 děng 声调不同，第二音节 jí 相同，意思是蹬极（一种高空跳跃运动）。", "等积": "第二音节 jī 与 jí 只有声调不同，意思是等积（面积相等）。"}, "sentence_index": null, "correct_answer": "等级"}, "level_3": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级指按质量分成的级别，与“分成三个……”相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，不能把茶叶分成小猫。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，与茶叶的分类不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“分成……年龄”搭配不当，茶叶没有年龄。"}], "explanations": {"等级": "正确答案：等级指按质量分成的级别，与“分成三个……”相符。", "小猫": "语义：“小猫”是动物，不能把茶叶分成小猫。", "名字": "语义：“名字”是称呼，与茶叶的分类不符。", "年龄": "搭配：“分成……年龄”搭配不当，茶叶没有年龄。"}, "sentence_index": 0, "correct_answer": "等级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家酒店有一条很高的等级。", "explanation": "这里应该用〈个〉。“等级”是抽象的级别，用于细长物件的量词不能修饰它。"}, {"text": "这件衣服的等级很便宜，我买了它。", "explanation": "这里应该用〈价格〉。“等级”指质量的分级，不能用“便宜”来说价钱。"}, {"text": "这个孩子的等级比去年增加了五公斤。", "explanation": "这里应该用〈体重〉。“等级”指质量或程度的级别，不能用公斤来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级（děng jí），指按质量、程度等分成的级别。"}, {"text": "省级", "is_correct": false, "explanation": "shěng 与 děng 声母不同（sh 与 d），声调相同，意思是省级（省一级的）。"}, {"text": "党籍", "is_correct": false, "explanation": "dǎng 与 děng 元音不同（a 与 e），声调相同，意思是党籍（党员的身份）。"}, {"text": "能级", "is_correct": false, "explanation": "néng 与 děng 声母不同（n 与 d），声调也不同，意思是能级（能量的层级）。"}], "explanations": {"等级": "正确答案：等级（děng jí），指按质量、程度等分成的级别。", "省级": "shěng 与 děng 声母不同（sh 与 d），声调相同，意思是省级（省一级的）。", "党籍": "dǎng 与 děng 元音不同（a 与 e），声调相同，意思是党籍（党员的身份）。", "能级": "néng 与 děng 声母不同（n 与 d），声调也不同，意思是能级（能量的层级）。"}, "sentence_index": null, "correct_answer": "等级"}, "level_3": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级指按质量、水平划分的级别，可以问“是什么等级”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与汉语水平无关，不能问“是什么颜色”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：汉语水平不是有味道的东西，不能问“是什么味道”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是人的身体指标，与“汉语水平”搭配不通。"}], "explanations": {"等级": "正确答案：等级指按质量、水平划分的级别，可以问“是什么等级”。", "颜色": "语义：“颜色”与汉语水平无关，不能问“是什么颜色”。", "味道": "语义：汉语水平不是有味道的东西，不能问“是什么味道”。", "体重": "搭配：“体重”是人的身体指标，与“汉语水平”搭配不通。"}, "sentence_index": 6, "correct_answer": "等级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的等级是一米八，比我高很多。", "explanation": "这里应该用〈身高〉。“等级”指级别，不能用来说身高。"}, {"text": "这种牛肉有一头等级很高。", "explanation": "这里应该用〈个〉。“等级”是抽象的级别，不能用指动物的量词来计量。"}, {"text": "她在小学读二等级，成绩很好。", "explanation": "这里应该用〈年级〉。“等级”指质量或程度的分级，不能用来说学校的年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批茶叶分成两级等级。", "corrected_sentence": "这批茶叶分成两个等级。", "error_description": "“级”与“等级”重复，量词应用“个”，应说“两个等级”，不能说“两级等级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器的等级一级。", "corrected_sentence": "这台机器的等级是一级。", "error_description": "句子缺少动词“是”，应说“这台机器的等级是一级”，不能说“这台机器的等级一级”。错误在“是”的缺失。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
