INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89111, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女子是长大了的女人。", "primary_collocate": null, "pronunciation": "nǚ zǐ", "ipa": "ny˨˩˦ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她已经是女子了，不再是小孩。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁以后，女孩就变成女子了。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女子比她妈妈还高。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个女子每天骑车去上班。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里来了两位女子。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是个很会照顾人的女子。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一位中年女子在河边散步。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女子也可以开车，也可以当老板。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女子把行李放在了车里。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站见过这位女子。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女子学校", "label": "复合"}, {"form": "女子足球", "label": "复合"}], "register": "书面", "sense_fingerprint": "长大了的女人，相对于女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1081a25-9b81-4cdc-b757-e82976d3359f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女子", "is_correct": true, "explanation": "女子：长大了的女人，与“已经是……不再是小孩”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿正是小孩，与“不再是小孩”相矛盾。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：人不会变成老鼠，与“她已经是……”不符。"}, {"text": "树", "is_correct": false, "explanation": "体貌：树不是人，外形不可能是“女子”。"}], "explanations": {"女子": "女子：长大了的女人，与“已经是……不再是小孩”相符。", "婴儿": "语义：婴儿正是小孩，与“不再是小孩”相矛盾。", "老鼠": "语义：人不会变成老鼠，与“她已经是……”不符。", "树": "体貌：树不是人，外形不可能是“女子”。"}, "sentence_index": 0, "correct_answer": "女子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个女子才七岁，正在上小学。", "explanation": "这里应该用〈女孩〉。女子指长大的女人，七岁的孩子应说女孩。"}, {"text": "这位女子还在吃奶，很可爱。", "explanation": "这里应该用〈女婴〉。女子指长大的女人，还在吃奶的孩子应说女婴。"}, {"text": "各位女子，欢迎光临本店。", "explanation": "这里应该用〈女士〉。称呼一群人时用“各位女士”，“女子”不作敬称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女子", "is_correct": true, "explanation": "女子：成年女性，与“中年”相符，可以在河边散步。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不会是“中年”，与句中“中年”相矛盾。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使不是中年人，与句中“中年”相矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不可能是中年人，与句中“中年”相矛盾。"}], "explanations": {"女子": "女子：成年女性，与“中年”相符，可以在河边散步。", "孩子": "语义：孩子不会是“中年”，与句中“中年”相矛盾。", "天使": "语义：天使不是中年人，与句中“中年”相矛盾。", "婴儿": "语义：婴儿不可能是中年人，与句中“中年”相矛盾。"}, "sentence_index": 6, "correct_answer": "女子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口站着一条女子。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，指人的“女子”不用“条”。"}, {"text": "这只老虎是女子，力气很大。", "explanation": "这里应该用〈雌性〉。“女子”指成年女人，不能用来指动物，说雌性动物要用〈雌性〉。"}, {"text": "我女子是一名护士。", "explanation": "这里应该用〈妈妈〉。女子指成年女性，不能用来指自己的母亲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只很成熟的女子走进了办公室。", "corrected_sentence": "那位很成熟的女子走进了办公室。", "error_description": "量词错误：指人的“女子”应用量词“位”或“个”，不用“只”（“只”用于动物）。应说“那位很成熟的女子走进了办公室”，不说“那只很成熟的女子走进了办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个女子们走进了书店。", "corrected_sentence": "两个女子走进了书店。", "error_description": "“们”误用：“们”不能加在数量短语之后，应说“两个女子”，不说“两个女子们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
