INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年女性。", "primary_collocate": null, "pronunciation": "nǚ zǐ", "ipa": "ny˨˩˦ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位女子在车站等车。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个女子今年二十五岁了。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一位年轻女子走进了商店。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一名很有礼貌的女子。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里坐着一位女子在看书。", "target_word": "女子", "complexity_tier": "T3", "furigana": "nǚ zǐ", "sentence_source": "generated"}, {"text": "公园里有个女子在唱歌。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个女子手里拿着一把伞。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问了这位女子几个问题。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个穿红衣服的女子坐在窗边。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女子在医院工作。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女子学校", "label": "复合"}, {"form": "女子足球", "label": "复合"}], "register": "书面", "sense_fingerprint": "成年女性；指人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1081a25-9b81-4cdc-b757-e82976d3359f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女子", "is_correct": true, "explanation": "女子：成年女性，指“那位”女人，符合在车站等车的情境。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有腿，不会在车站等车。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是固定的艺术品，不会在车站等车。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使不需要在车站等车，与日常情境相矛盾。"}], "explanations": {"女子": "女子：成年女性，指“那位”女人，符合在车站等车的情境。", "石头": "体貌：石头没有腿，不会在车站等车。", "雕像": "语义：雕像是固定的艺术品，不会在车站等车。", "天使": "语义：天使不需要在车站等车，与日常情境相矛盾。"}, "sentence_index": 0, "correct_answer": "女子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹才五岁，是个可爱的女子。", "explanation": "这里应该用〈女孩〉。女子指成年女性，五岁的孩子应说女孩。"}, {"text": "门口站着一只女子。", "explanation": "这里应该用〈位〉或〈个〉。“只”用于动物或成对的东西，指人不用“只”。"}, {"text": "各位女子，欢迎光临本店。", "explanation": "这里应该用〈女士〉。称呼一群人时用“各位女士”，“女子”不作敬称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女子", "is_correct": true, "explanation": "女子：成年女性，与“手里拿着一把伞”的人物相符。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有手，形体上不能拿着伞。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是固定的建筑，不会手里拿伞。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有手，不能拿着伞。"}], "explanations": {"女子": "女子：成年女性，与“手里拿着一把伞”的人物相符。", "石头": "体貌：石头没有手，形体上不能拿着伞。", "房子": "语义：房子是固定的建筑，不会手里拿伞。", "桌子": "语义：桌子没有手，不能拿着伞。"}, "sentence_index": 6, "correct_answer": "女子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位女子才三个月大，很可爱。", "explanation": "这里应该用〈女婴〉。女子指长大的女人，三个月大的孩子应说女婴。"}, {"text": "这是我的女子，她今年十岁。", "explanation": "这里应该用〈女儿〉。女子不能用来指自己的女儿。"}, {"text": "我的女子很温柔。", "explanation": "这里应该用〈女朋友〉。女子指成年女性，不用来指自己的恋人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只女子走进了办公室。", "corrected_sentence": "那位女子走进了办公室。", "error_description": "量词错误：指人的“女子”应用量词“位”或“个”，不用“只”（“只”用于动物）。应说“那位女子”，不说“那只女子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位年轻的女子的坐在窗边。", "corrected_sentence": "一位年轻的女子坐在窗边。", "error_description": "多余的“的”：“年轻的女子”后不应再加“的”，应说“一位年轻的女子坐在窗边”，不说“一位年轻的女子的坐在窗边”（“女子的”成了名词性短语，句子没有谓语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
