INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "数学中表示两个量相等的符号\"=\"。", "primary_collocate": null, "pronunciation": "děng hào", "ipa": "təŋ˨˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "数学书里常常用等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一加一，后面写等号，再写二。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边加右边，中间用等号连起来。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学会了写等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑上怎么打出等号？", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等号的意思是两个数相等。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个式子少了等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上写了数字和等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等号和加号都是数学符号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在两个数中间放上等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "等號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "等号：数学中表示两个量相等的符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等号", "is_correct": true, "explanation": "等号：数学书里常用的符号，句子通顺。"}, {"text": "手机", "is_correct": false, "explanation": "语义：数学书里不会用“手机”这种东西，句意不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：数学书里不会用“足球”，句意不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：数学书里不会用“咖啡”，句意不通。"}], "explanations": {"等号": "等号：数学书里常用的符号，句子通顺。", "手机": "语义：数学书里不会用“手机”这种东西，句意不通。", "足球": "语义：数学书里不会用“足球”，句意不通。", "咖啡": "语义：数学书里不会用“咖啡”，句意不通。"}, "sentence_index": 0, "correct_answer": "等号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "七比四大，中间应该写等号连接两边。", "explanation": "这里应该用〈大于号〉。七比四大，要用大于号“>”，等号“=”表示两边相等。"}, {"text": "二和三相加，中间应该写等号。", "explanation": "这里应该用〈加号〉。两数相加，中间要写加号“+”，写等号就表示两边相等了。"}, {"text": "三比五小，中间应该写等号。", "explanation": "这里应该用〈小于号〉。三比五小，要用小于号“<”，等号表示相等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等号", "is_correct": true, "explanation": "等号：式子中缺少的符号，补上后式子才通顺。"}, {"text": "句子", "is_correct": false, "explanation": "语义：数学式子里不会少了“句子”这种语言单位，句意不通。"}, {"text": "星星", "is_correct": false, "explanation": "语义：数学式子里不会少“星星”，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“少”与“脚步”不搭配，不能说“少了脚步”。"}], "explanations": {"等号": "等号：式子中缺少的符号，补上后式子才通顺。", "句子": "语义：数学式子里不会少了“句子”这种语言单位，句意不通。", "星星": "语义：数学式子里不会少“星星”，句意不通。", "脚步": "搭配：“少”与“脚步”不搭配，不能说“少了脚步”。"}, "sentence_index": 6, "correct_answer": "等号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请在两个数中间放上一只等号。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一个，等号是符号，不能用“只”。"}, {"text": "请在两个数中间放上一把等号。", "explanation": "这里应该用〈个〉。“把”多用于有柄或能握住的东西，等号不能用“把”。"}, {"text": "请在两个数中间放上一块等号。", "explanation": "这里应该用〈个〉。“块”多用于块状的东西，等号是符号，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在本子上画了一条等号。", "corrected_sentence": "他在本子上画了一个等号。", "error_description": "错误：量词“条”用错。等号是符号，应该用量词“个”，“条”多用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在两个数中间写了一只等号。", "corrected_sentence": "他在两个数中间写了一个等号。", "error_description": "错误：量词“只”用错。等号是符号，应该用量词“个”，“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
