INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89121, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "兴奋是心里特别高兴，静不下来。", "primary_collocate": null, "pronunciation": "xīng fèn", "ipa": "ɕiŋ˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "要去海边玩，孩子们兴奋极了。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗见到主人，兴奋得又跳又叫。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到礼物，她兴奋得跳了起来。", "target_word": "兴奋", "complexity_tier": "T3", "furigana": "shōu dào lǐ wù，tā xīng fèn de tiào le qǐ lái。", "sentence_source": "generated"}, {"text": "他太兴奋了，坐不住。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我兴奋得睡不着觉。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家兴奋地等着电影开始。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她兴奋的样子很可爱。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束了，同学们都很兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他兴奋得脸都红了。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说要放假，全班都兴奋起来。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兴奋地", "label": "状语形式"}, {"form": "興奮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "兴奋：心里特别高兴，静不下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴奋", "is_correct": true, "explanation": "正确。“兴奋极了”表示期待中的高兴和激动，与“要去海边玩”相符。"}, {"text": "失望", "is_correct": false, "explanation": "语义：要去海边玩是令人期待的事，“失望”与句中的期待相反。"}, {"text": "疲倦", "is_correct": false, "explanation": "语义：刚要出发玩耍，“疲倦”与句中的期待不合。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容地方或气氛，不能用来形容孩子们。"}], "explanations": {"兴奋": "正确。“兴奋极了”表示期待中的高兴和激动，与“要去海边玩”相符。", "失望": "语义：要去海边玩是令人期待的事，“失望”与句中的期待相反。", "疲倦": "语义：刚要出发玩耍，“疲倦”与句中的期待不合。", "冷清": "搭配：“冷清”形容地方或气氛，不能用来形容孩子们。"}, "sentence_index": 0, "correct_answer": "兴奋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教练的话能让全队兴奋士气。", "explanation": "这里应该用〈振奋〉。“振奋士气”是固定说法，“兴奋”不能带“士气”作宾语。"}, {"text": "葬礼上，他的心里很兴奋。", "explanation": "这里应该用〈悲伤〉。“悲伤”指难过，“兴奋”指高兴，葬礼上不能用“兴奋”。"}, {"text": "妈妈听说孩子生病，心里很兴奋。", "explanation": "这里应该用〈担心〉。“担心”指忧虑，“兴奋”指高兴，不能用于孩子生病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兴奋", "is_correct": true, "explanation": "正确。“兴奋的样子”描写神情，“兴奋”作定语修饰“样子”，与句意相符。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能用来形容“样子”。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”多形容空间，不能用来形容“样子”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容“样子”。"}], "explanations": {"兴奋": "正确。“兴奋的样子”描写神情，“兴奋”作定语修饰“样子”，与句意相符。", "沙哑": "搭配：“沙哑”形容嗓音，不能用来形容“样子”。", "狭窄": "搭配：“狭窄”多形容空间，不能用来形容“样子”。", "清脆": "搭配：“清脆”形容声音，不能用来形容“样子”。"}, "sentence_index": 6, "correct_answer": "兴奋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的一番演说，让大家兴奋斗志。", "explanation": "这里应该用〈振奋〉。“振奋斗志”是固定说法，“兴奋”不能带“斗志”作宾语。"}, {"text": "老师宣布考试成绩不及格，全班都很兴奋。", "explanation": "这里应该用〈沮丧〉。“沮丧”指失望，“兴奋”指高兴，不能用于考试不及格的场合。"}, {"text": "面对不公平的判决，他显得很兴奋。", "explanation": "这里应该用〈愤慨〉。“愤慨”指愤怒不平，“兴奋”指高兴，不能用于不公的判决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一看到妹妹，就兴奋跑过去了。", "corrected_sentence": "他一看到妹妹，就兴奋地跑过去了。", "error_description": "双音节形容词“兴奋”作状语，后面要加“地”，应说“兴奋地跑过去”；“兴奋跑过去”漏掉了“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一听，也兴奋出来了。", "corrected_sentence": "妈妈一听，也兴奋起来了。", "error_description": "“兴奋”后的结果补语应为“起来”，表示状态开始出现；“出来”不能与“兴奋”搭配，应说“兴奋起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
