INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89122, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，精神振奋，情绪激动。", "primary_collocate": null, "pronunciation": "xīng fèn", "ipa": "ɕiŋ˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "听到好消息，他非常兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们兴奋地跑出了教室。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，大家都很兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她兴奋得一晚上没睡好。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到偶像，小李特别兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天去旅行，我有点兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音听起来很兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天他们的心情格外兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球进了，现场的人都很兴奋。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟兴奋地告诉我他得了第一名。", "target_word": "兴奋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兴奋地", "label": "状语形式"}, {"form": "興奮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "兴奋：精神振奋，情绪激动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴奋", "is_correct": true, "explanation": "正确。“兴奋”指精神振奋、情绪激动，与“听到好消息”的反应相符。"}, {"text": "失望", "is_correct": false, "explanation": "语义：听到好消息，人应当高兴，“失望”与好消息的情绪相反。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”指对外界漠不关心，听到好消息后“非常冷漠”与句意相反。"}, {"text": "惶恐", "is_correct": false, "explanation": "语义：“惶恐”指害怕不安，与听到好消息后的兴奋不符。"}], "explanations": {"兴奋": "正确。“兴奋”指精神振奋、情绪激动，与“听到好消息”的反应相符。", "失望": "语义：听到好消息，人应当高兴，“失望”与好消息的情绪相反。", "冷漠": "语义：“冷漠”指对外界漠不关心，听到好消息后“非常冷漠”与句意相反。", "惶恐": "语义：“惶恐”指害怕不安，与听到好消息后的兴奋不符。"}, "sentence_index": 0, "correct_answer": "兴奋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个兴奋人心的时刻。", "explanation": "这里应该用〈振奋〉。“振奋人心”是固定搭配，指使人精神鼓舞；“兴奋”指自己心里激动，不能修饰“人心”。"}, {"text": "葬礼上，大家的心情都很兴奋。", "explanation": "这里应该用〈悲伤〉。“悲伤”指心里难过，“兴奋”指情绪高涨，葬礼的场合不能用“兴奋”。"}, {"text": "妈妈听说孩子生病，心里很兴奋。", "explanation": "这里应该用〈担心〉。“担心”指忧虑不安，“兴奋”指高兴激动，不能用于孩子生病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兴奋", "is_correct": true, "explanation": "正确。“兴奋”可以形容声音里流露出的情绪，与句意相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材外形，不能用来形容声音。"}, {"text": "低矮", "is_correct": false, "explanation": "体貌：“低矮”形容高度，不能用来形容声音。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”多形容空间，不能与“声音”搭配。"}], "explanations": {"兴奋": "正确。“兴奋”可以形容声音里流露出的情绪，与句意相符。", "高大": "体貌：“高大”形容人或物的身材外形，不能用来形容声音。", "低矮": "体貌：“低矮”形容高度，不能用来形容声音。", "狭窄": "搭配：“狭窄”多形容空间，不能与“声音”搭配。"}, "sentence_index": 6, "correct_answer": "兴奋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他深呼吸一下，兴奋精神，继续工作。", "explanation": "这里应该用〈振奋〉。“振奋精神”是固定说法，“兴奋”不能带“精神”作宾语。"}, {"text": "听到噩耗，他的心情格外兴奋。", "explanation": "这里应该用〈沉痛〉。“沉痛”指悲伤，“兴奋”指高兴激动，不能用于听到噩耗的场合。"}, {"text": "面对突发的危机，他显得很兴奋。", "explanation": "这里应该用〈紧张〉。“紧张”指心情急迫不安，“兴奋”指高兴激动，不能用于危急的场合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一听到消息，就兴奋跑回了家。", "corrected_sentence": "他一听到消息，就兴奋地跑回了家。", "error_description": "双音节形容词“兴奋”作状语，后面要加“地”，应说“兴奋地跑回了家”；“兴奋跑回了家”漏掉了“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一听，都兴奋出来了。", "corrected_sentence": "大家一听，都兴奋起来了。", "error_description": "“兴奋”后的结果补语应为“起来”，表示状态开始出现；“出来”不能与“兴奋”搭配，应说“兴奋起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
