INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89123, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几天是不多的一些日子。", "primary_collocate": null, "pronunciation": "jǐ tiān", "ipa": "tɕi˨˩˦ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这几天天气很冷。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只休息了几天就上班了。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过几天我就回来。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这几天我一直很忙。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只在北京住了几天。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈病了几天,现在好多了。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再等几天,新书就到了。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前几天我见到了老同学。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走了才几天,我就想他了。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天的作业不多。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾天", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指不多的一些日子,如“这几天”“过几天”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89123, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不多的一些日子，是本次听辨的目标词。"}, {"text": "几年", "is_correct": false, "explanation": "nián（第二声）与 tiān（第一声）声母不同（n 与 t），意思是几年，指较长的年数。"}, {"text": "几千", "is_correct": false, "explanation": "qiān 与 tiān 声母不同（q 与 t），意思是几千，是数量词组。"}, {"text": "几点", "is_correct": false, "explanation": "diǎn（第三声）与 tiān（第一声）声母不同（d 与 t）且声调不同，意思是几点钟。"}], "explanations": {"几天": "几天：不多的一些日子，是本次听辨的目标词。", "几年": "nián（第二声）与 tiān（第一声）声母不同（n 与 t），意思是几年，指较长的年数。", "几千": "qiān 与 tiān 声母不同（q 与 t），意思是几千，是数量词组。", "几点": "diǎn（第三声）与 tiān（第一声）声母不同（d 与 t）且声调不同，意思是几点钟。"}, "sentence_index": null, "correct_answer": "几天"}, "level_3": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不多的几日，与“这”和“很冷”的语境相符。"}, {"text": "盛夏", "is_correct": false, "explanation": "语义：盛夏是一年中最炎热的时候，与“很冷”直接冲突。"}, {"text": "三伏天", "is_correct": false, "explanation": "语义：三伏天是夏季最炎热的时段，与“很冷”直接冲突。"}, {"text": "每天", "is_correct": false, "explanation": "搭配：“每天”指每一日，不能与指示词“这”搭配。"}], "explanations": {"几天": "几天：不多的几日，与“这”和“很冷”的语境相符。", "盛夏": "语义：盛夏是一年中最炎热的时候，与“很冷”直接冲突。", "三伏天": "语义：三伏天是夏季最炎热的时段，与“很冷”直接冲突。", "每天": "搭配：“每天”指每一日，不能与指示词“这”搭配。"}, "sentence_index": 0, "correct_answer": "几天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我只在电梯里等了几天。", "explanation": "这里应该用〈几分钟〉。等电梯只需几分钟，“几天”指较长的日子，不能用于这样的短时段。"}, {"text": "他一下午就看了几天的书。", "explanation": "这里应该用〈几个小时〉。一下午之内的时长要用小时计，“几天”不能与“一下午”搭配。"}, {"text": "红灯还要亮几天。", "explanation": "这里应该用〈几秒〉。红绿灯的时长以秒计，“几天”不能用于这样的短时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不多的几日，与“就到了”的近期语气相符。"}, {"text": "几本", "is_correct": false, "explanation": "搭配：“几本”是书的数量，不能用来表示等待的时长。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“一辈子”过于漫长，与“新书就到了”冲突。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“再等时间”不成立，“时间”不能直接作“等”的时段宾语。"}], "explanations": {"几天": "几天：不多的几日，与“就到了”的近期语气相符。", "几本": "搭配：“几本”是书的数量，不能用来表示等待的时长。", "一辈子": "语义：“一辈子”过于漫长，与“新书就到了”冲突。", "时间": "搭配：“再等时间”不成立，“时间”不能直接作“等”的时段宾语。"}, "sentence_index": 6, "correct_answer": "几天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场球赛只踢了几天，很快就结束了。", "explanation": "这里应该用〈几个钟头〉。一场球赛只持续几个钟头，“几天”不能描述比赛的时长。"}, {"text": "他一天吃了几天饭。", "explanation": "这里应该用〈几次〉。一天之内的次数用“几次”，“几天”指若干日子，与“一天”冲突。"}, {"text": "这道题我只用了几天，很快就做完了。", "explanation": "这里应该用〈一刻钟〉。“只用了”和“很快就做完”描述的是短时间，“几天”与此冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我再等几天个就走。", "corrected_sentence": "我再等几天就走。", "error_description": "“几天”后多加了量词“个”。“几天”是固定的时间词组，后面不能直接加“个”，删去即为“再等几天就走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我前几天的见到了老同学。", "corrected_sentence": "我前几天见到了老同学。", "error_description": "错误在于“的”。时间状语“前几天”直接修饰动词，中间不能加“的”，应说“前几天见到了老同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
