INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几天是天数尚不确定、需要询问或说不准的时长。", "primary_collocate": null, "pronunciation": "jǐ tiān", "ipa": "tɕi˨˩˦ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "我不知道还要等几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说不准要出差几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你打算在这里住几天?", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生没说要住院几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上可能要走几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没人知道这场雨会下几天。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你请了几天假?", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要在上海玩几天,还没想好。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好,飞机可能要晚几天。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事要做几天,我现在还不清楚。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾天", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天数不确定或需要询问,如“住几天”“等几天”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不确定的天数，是本次听辨的目标词。"}, {"text": "几年", "is_correct": false, "explanation": "nián（第二声）与 tiān（第一声）声母不同（n 与 t），意思是几年。"}, {"text": "几千", "is_correct": false, "explanation": "qiān 与 tiān 声母不同（q 与 t），意思是几千。"}, {"text": "几点", "is_correct": false, "explanation": "diǎn（第三声）与 tiān（第一声）声母不同（d 与 t）且声调不同，意思是几点钟。"}], "explanations": {"几天": "几天：不确定的天数，是本次听辨的目标词。", "几年": "nián（第二声）与 tiān（第一声）声母不同（n 与 t），意思是几年。", "几千": "qiān 与 tiān 声母不同（q 与 t），意思是几千。", "几点": "diǎn（第三声）与 tiān（第一声）声母不同（d 与 t）且声调不同，意思是几点钟。"}, "sentence_index": null, "correct_answer": "几天"}, "level_3": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不确定的天数，与“不知道”的语气相符。"}, {"text": "三天", "is_correct": false, "explanation": "语义：“三天”是确定的数，与“不知道”的语气冲突。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：“还要等今天”不成立，“今天”指当天，不能作“等”的时段。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“还要等时间”不成立，“时间”不能直接作“等”的时段。"}], "explanations": {"几天": "几天：不确定的天数，与“不知道”的语气相符。", "三天": "语义：“三天”是确定的数，与“不知道”的语气冲突。", "今天": "搭配：“还要等今天”不成立，“今天”指当天，不能作“等”的时段。", "时间": "搭配：“还要等时间”不成立，“时间”不能直接作“等”的时段。"}, "sentence_index": 0, "correct_answer": "几天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议定好了几天，不能再改。", "explanation": "这里应该用〈两天〉。时长已经定好时要用具体的天数，不能用“几天”表示不确定的天数。"}, {"text": "船票写明几天后出发。", "explanation": "这里应该用〈五天〉。写明的出发时间是确定的，不能用“几天”表示不确定的天数。"}, {"text": "展位已经订好了几天。", "explanation": "这里应该用〈一周〉。已经订好的期限是确定的，不能用“几天”来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不多的几日，指请假的天数。"}, {"text": "几秒", "is_correct": false, "explanation": "语义：请假不以秒计，“几秒”与此冲突。"}, {"text": "几世纪", "is_correct": false, "explanation": "语义：“几世纪”太过漫长，不能作请假的时长。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“请了时间假”不成立，“时间”不能直接作请假的数量。"}], "explanations": {"几天": "几天：不多的几日，指请假的天数。", "几秒": "语义：请假不以秒计，“几秒”与此冲突。", "几世纪": "语义：“几世纪”太过漫长，不能作请假的时长。", "时间": "搭配：“请了时间假”不成立，“时间”不能直接作请假的数量。"}, "sentence_index": 6, "correct_answer": "几天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小孩几天就睡着了。", "explanation": "这里应该用〈一刻钟〉。入睡只需一刻钟，“几天”表示若干日子，与“就”的快速语气冲突。"}, {"text": "这道汤要煮几天，我先去买菜。", "explanation": "这里应该用〈三十分钟〉。煮一道汤的时长以分钟计，“几天”不能用于这样的烹饪时长。"}, {"text": "他跑完一百米只用了几天。", "explanation": "这里应该用〈几秒〉。跑完一百米只需几秒，“几天”指若干日子，用在这样的短时段里不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还不确定要在那里住几天个。", "corrected_sentence": "我还不确定要在那里住几天。", "error_description": "“几天”后多加了量词“个”。“几天”作时量补语时是固定说法，后面不能直接加“个”，正确是“住几天”；写成“住几天个”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们要在上海玩了几天？", "corrected_sentence": "你们要在上海玩几天？", "error_description": "错误在于“了”。“了”表示动作已经完成，与表示将来的“要”相矛盾；应说“你们要在上海玩几天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "反义：“关闭”与“打开”相对，指把开着的东西合上，与“把箱子打开”相对。"}, {"text": "搬运", "is_correct": false, "explanation": "无反义关系：“搬运”指把东西从一处移到另一处，与“打开”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”指修补坏了的东西，与把箱子弄开没有相对关系。"}, {"text": "擦洗", "is_correct": false, "explanation": "无反义关系：“擦洗”指清洁物体表面，与“打开”不构成反义。"}], "correct_answer": "关闭", "explanations": {"关闭": "反义：“关闭”与“打开”相对，指把开着的东西合上，与“把箱子打开”相对。", "搬运": "无反义关系：“搬运”指把东西从一处移到另一处，与“打开”不构成反义。", "修理": "无反义关系：“修理”指修补坏了的东西，与把箱子弄开没有相对关系。", "擦洗": "无反义关系：“擦洗”指清洁物体表面，与“打开”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "锁上", "is_correct": true, "explanation": "反义：“锁上”与“打开”相对，表示把锁扣住，与“把锁打开”相对。"}, {"text": "收集", "is_correct": false, "explanation": "无反义关系：“收集”指把分散的东西聚在一起，与开锁没有相对关系。"}, {"text": "修补", "is_correct": false, "explanation": "无反义关系：“修补”指把坏了的东西补好，与“打开”不构成反义。"}, {"text": "洗涤", "is_correct": false, "explanation": "无反义关系：“洗涤”指用水清除污物，与“打开”不构成反义。"}], "correct_answer": "锁上", "explanations": {"锁上": "反义：“锁上”与“打开”相对，表示把锁扣住，与“把锁打开”相对。", "收集": "无反义关系：“收集”指把分散的东西聚在一起，与开锁没有相对关系。", "修补": "无反义关系：“修补”指把坏了的东西补好，与“打开”不构成反义。", "洗涤": "无反义关系：“洗涤”指用水清除污物，与“打开”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打开是把关着的东西弄开。", "primary_collocate": null, "pronunciation": "dǎ kāi", "ipa": "ta˨˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "我把门打开了，风吹进来了。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用钥匙打开了门。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想打开这个瓶子，可是太紧了。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把箱子打开，让我看看里面。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开冰箱，拿了一瓶水。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子打开礼物，高兴地笑了。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把包打开，拿出一本书。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有钥匙吗？我想打开那个柜子。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力打开了那个盖子。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把锁打开，我们进了家。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打开了", "label": "体标"}, {"form": "打开过", "label": "体标"}, {"form": "打開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打开：把关着、锁着的东西弄开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打开", "is_correct": true, "explanation": "正确：“打开”表示把关着的门弄开，与后句“风吹进来了”相符。"}, {"text": "锁上", "is_correct": false, "explanation": "语义：“锁上”表示门被锁住，与后句“风吹进来了”矛盾。"}, {"text": "合上", "is_correct": false, "explanation": "语义：“合上”表示门关闭，与后句“风吹进来了”矛盾。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”表示门闭合，与后句“风吹进来了”矛盾。"}], "explanations": {"打开": "正确：“打开”表示把关着的门弄开，与后句“风吹进来了”相符。", "锁上": "语义：“锁上”表示门被锁住，与后句“风吹进来了”矛盾。", "合上": "语义：“合上”表示门关闭，与后句“风吹进来了”矛盾。", "关": "语义：“关”表示门闭合，与后句“风吹进来了”矛盾。"}, "sentence_index": 0, "correct_answer": "打开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生终于打开了那位病人。", "explanation": "这里应该用〈抢救〉。打开多指把可以开合的东西弄开，不能用于人；对病人要用抢救。"}, {"text": "妈妈把那个误会打开了。", "explanation": "这里应该用〈消除〉。误会要消除，打开不能用于误会。"}, {"text": "他终于打开了那道难题。", "explanation": "这里应该用〈解决〉。难题要解决，不能打开；打开只用于可以开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打开", "is_correct": true, "explanation": "正确：把包弄开，才能从里面拿出书，与后句“拿出一本书”相符。"}, {"text": "关上", "is_correct": false, "explanation": "语义：包合着就拿不出书，“关上”与后句“拿出一本书”矛盾。"}, {"text": "吃了", "is_correct": false, "explanation": "搭配：“吃”不能接“包”作宾语，搭配不当。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：包已经扔掉，就不能再从里面拿出书，与后句矛盾。"}], "explanations": {"打开": "正确：把包弄开，才能从里面拿出书，与后句“拿出一本书”相符。", "关上": "语义：包合着就拿不出书，“关上”与后句“拿出一本书”矛盾。", "吃了": "搭配：“吃”不能接“包”作宾语，搭配不当。", "扔掉": "语义：包已经扔掉，就不能再从里面拿出书，与后句矛盾。"}, "sentence_index": 6, "correct_answer": "打开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "侦探终于打开了那个谜底。", "explanation": "这里应该用〈揭开〉。谜底、真相要揭开，打开多用于可以开合的东西。"}, {"text": "我打开了那把钥匙。", "explanation": "这里不能用〈打开〉作用于钥匙本身。钥匙是开锁的工具，应说“用钥匙打开门”，不能说打开钥匙。"}, {"text": "我打开了那个座位。", "explanation": "这里应该用〈坐〉。座位不是可以开合的东西，打开只用于门、盒子等，应说“我坐在那个座位上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门打开了着，风吹进来了。", "corrected_sentence": "门打开着，风吹进来了。", "error_description": "体标错误：“打开”后的“着”已表示状态，两者不能同时用，应说“门打开着”，不能说“门打开了着”。错误在“了”，正确形式为“打开着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王把包打开开，拿出一本书。", "corrected_sentence": "小王把包打开，拿出一本书。", "error_description": "补语错误：“打开”的补语“开”已包含在动补结构中，不能再重复加“开”。错误在多出的“开”，应说“小王把包打开，拿出一本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关上", "is_correct": true, "explanation": "关上：与打开互为反义，指使盒子、门等敞开的东西闭合。"}, {"text": "拿起", "is_correct": false, "explanation": "拿起：表示用手取，与打开没有反义关系。"}, {"text": "挂上", "is_correct": false, "explanation": "挂上：表示挂在某处，与打开没有反义关系。"}, {"text": "穿上", "is_correct": false, "explanation": "穿上：表示把衣物套在身上，与打开没有反义关系。"}], "correct_answer": "关上", "explanations": {"关上": "关上：与打开互为反义，指使盒子、门等敞开的东西闭合。", "拿起": "拿起：表示用手取，与打开没有反义关系。", "挂上": "挂上：表示挂在某处，与打开没有反义关系。", "穿上": "穿上：表示把衣物套在身上，与打开没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合上", "is_correct": true, "explanation": "合上：与打开互为反义，指使本子等书页闭合。"}, {"text": "放下", "is_correct": false, "explanation": "放下：表示把东西放到某处，与打开没有反义关系。"}, {"text": "举起", "is_correct": false, "explanation": "举起：表示向上抬，与打开没有反义关系。"}, {"text": "脱下", "is_correct": false, "explanation": "脱下：表示把衣物从身上取下，与打开没有反义关系。"}], "correct_answer": "合上", "explanations": {"合上": "合上：与打开互为反义，指使本子等书页闭合。", "放下": "放下：表示把东西放到某处，与打开没有反义关系。", "举起": "举起：表示向上抬，与打开没有反义关系。", "脱下": "脱下：表示把衣物从身上取下，与打开没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使关闭的东西展开或敞开。", "primary_collocate": null, "pronunciation": "dǎ kāi", "ipa": "ta˨˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "请把窗户打开，屋里太热了。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开书，开始看第三页。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的盖子很紧，你能帮我打开吗？", "target_word": "打开", "complexity_tier": "T3", "furigana": "zhè ge xiāng zi de gài zi hěn jǐn, nǐ néng bāng wǒ dǎ kāi ma?", "sentence_source": "generated"}, {"text": "妈妈打开盒子，里面有一个蛋糕。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开门，看见一只小猫。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开了伞，走进雨里。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们打开书，翻到第十页。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开地图，找到了去公园的路。", "target_word": "打开", "complexity_tier": "T3", "furigana": "tā dǎ kāi dì tú, zhǎo dào le qù gōng yuán de lù.", "sentence_source": "generated"}, {"text": "太冷了，别打开窗户。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开本子，写下了今天的日期。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打开了", "label": "体标"}, {"form": "打开过", "label": "体标"}, {"form": "打開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打开：使关闭的东西（门窗、书、盒子等）展开或敞开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打开", "is_correct": true, "explanation": "打开：使窗户展开或敞开，屋里太热，所以要开窗。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去灰尘，与“屋里太热”这个要求不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，与“屋里太热”没有关系，句意不通。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：挂多用于窗帘、画等，不说“挂窗户”。"}], "explanations": {"打开": "打开：使窗户展开或敞开，屋里太热，所以要开窗。", "擦": "语义：擦是抹去灰尘，与“屋里太热”这个要求不符。", "修": "语义：修是修理，与“屋里太热”没有关系，句意不通。", "挂": "搭配：挂多用于窗帘、画等，不说“挂窗户”。"}, "sentence_index": 0, "correct_answer": "打开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打开了谜底。", "explanation": "这里应该用〈揭开〉。谜底、真相要用“揭开”，打开只用于门、盒子等具体的东西。"}, {"text": "他打开了一个人。", "explanation": "这里应该用〈找〉。“打开”只用于能展开或敞开的东西，不能用于人，找人要说“找”。"}, {"text": "他打开了那场比赛。", "explanation": "这里应该用〈开始〉。比赛要用“开始”，打开表示使东西展开或敞开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打开", "is_correct": true, "explanation": "打开：使书展开，翻到第十页才能看到内容。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕书会弄坏书页，与“翻到第十页”的要求不符。"}, {"text": "掀", "is_correct": false, "explanation": "搭配：掀多用于盖子、被子，不说“掀书”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉书就无法翻到第十页，与句意矛盾。"}], "explanations": {"打开": "打开：使书展开，翻到第十页才能看到内容。", "撕": "语义：撕书会弄坏书页，与“翻到第十页”的要求不符。", "掀": "搭配：掀多用于盖子、被子，不说“掀书”。", "扔": "语义：扔掉书就无法翻到第十页，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "打开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打开了一家公司。", "explanation": "这里应该用〈开办〉。公司、学校要用“开办”，打开只用于门、盒子等能敞开的东西。"}, {"text": "他打开了一场病。", "explanation": "这里应该用〈治好〉。病要用“治好”，打开不能用于疾病。"}, {"text": "他打开了一场会议。", "explanation": "这里应该用〈召开〉。会议要用“召开”，打开不用于会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把窗户打开了，好吗？", "corrected_sentence": "请把窗户打开，好吗？", "error_description": "体标错误：祈使句“请……”表示请求对方做某事，句末不用“了”。“了”应删去，应说“请把窗户打开，好吗？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王把包打开了了，拿出了一本书。", "corrected_sentence": "小王把包打开了，拿出了一本书。", "error_description": "体标重复：“打开”后只用一个“了”表示完成，多出的“了”要删去。应说“小王把包打开了，拿出了一本书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
