INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "日日是每一天,天天。", "primary_collocate": null, "pronunciation": "rì rì", "ipa": "ɻ̩˥˩ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他日日喝茶，已经成了习惯。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟日日玩游戏，作业都忘了写。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店日日有人排队买面包。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶日日念叨着孙子。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我日日坐地铁上班，很方便。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫日日睡在窗台上晒太阳。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她日日给花浇水，这个习惯坚持了好几年，花开得很好。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他日日加班，身体越来越累。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，爷爷日日烧水泡脚。", "target_word": "日日", "complexity_tier": "T3", "furigana": "dōng tiān dào le, yé ye rì rì shāo shuǐ pào jiǎo.", "sentence_source": "generated"}, {"text": "孩子们日日盼着过年。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日日夜夜", "label": "复合"}], "register": "书面", "sense_fingerprint": "日日:每一天,天天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 小猫 (Zipf 3.7), 窗 (Zipf 3.98), 晒太阳 (Zipf 3.4)']::text[], '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日日", "is_correct": true, "explanation": "日日（rì rì）：每一天、天天，正确答案。"}, {"text": "日历", "is_correct": false, "explanation": "日历（rì lì）：第二个音节 lì 与 rì 声母不同（l 与 r），意思是日历，不是“每一天”。"}, {"text": "日式", "is_correct": false, "explanation": "日式（rì shì）：第二个音节 shì 与 rì 声母不同（sh 与 r），意思是日本式的。"}, {"text": "日志", "is_correct": false, "explanation": "日志（rì zhì）：第二个音节 zhì 与 rì 声母不同（zh 与 r），意思是日志、记录。"}, {"text": "日记", "is_correct": false, "explanation": "日记（rì jì）：第二个音节 jì 与 rì 声母不同（j 与 r），意思是日记本。"}], "explanations": {"日日": "日日（rì rì）：每一天、天天，正确答案。", "日历": "日历（rì lì）：第二个音节 lì 与 rì 声母不同（l 与 r），意思是日历，不是“每一天”。", "日式": "日式（rì shì）：第二个音节 shì 与 rì 声母不同（sh 与 r），意思是日本式的。", "日志": "日志（rì zhì）：第二个音节 zhì 与 rì 声母不同（zh 与 r），意思是日志、记录。", "日记": "日记（rì jì）：第二个音节 jì 与 rì 声母不同（j 与 r），意思是日记本。"}, "sentence_index": null, "correct_answer": "日日"}, "level_3": {"options": [{"text": "日日", "is_correct": true, "explanation": "日日：每一天都喝茶，与“已经成了习惯”的说法相合。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生的事，与“已经成了习惯”的长期状态相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“已经成了习惯”的说法相矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指出乎意料的一次性事件，与“已经成了习惯”的长期状态相矛盾。"}], "explanations": {"日日": "日日：每一天都喝茶，与“已经成了习惯”的说法相合。", "刚刚": "语义：“刚刚”表示刚发生的事，与“已经成了习惯”的长期状态相矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“已经成了习惯”的说法相矛盾。", "突然": "语义：“突然”指出乎意料的一次性事件，与“已经成了习惯”的长期状态相矛盾。"}, "sentence_index": 0, "correct_answer": "日日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他日日参加了一次运动会。", "explanation": "这里不能用〈日日〉：运动会每年或每届只举办一次，“日日”指每天重复，应改用〈每年〉。"}, {"text": "公司日日召开年会。", "explanation": "这里不能用〈日日〉：年会每年只开一次，应改用〈每年〉。"}, {"text": "他日日当选班长。", "explanation": "这里不能用〈日日〉：当选班长是一次性的事件，应改用〈终于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日日", "is_correct": true, "explanation": "日日：每天都给花浇水，表示每天的照料习惯，与“花开得很好”相合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰“给花浇水”这样的动作。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即将发生的近期动作，与“坚持了好几年”的长期习惯不合。"}, {"text": "从来", "is_correct": false, "explanation": "用法：“从来”通常与否定词连用（如“从来不”），且与“坚持了好几年”的持续习惯相矛盾。"}], "explanations": {"日日": "日日：每天都给花浇水，表示每天的照料习惯，与“花开得很好”相合。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰“给花浇水”这样的动作。", "马上": "语义：“马上”指即将发生的近期动作，与“坚持了好几年”的长期习惯不合。", "从来": "用法：“从来”通常与否定词连用（如“从来不”），且与“坚持了好几年”的持续习惯相矛盾。"}, "sentence_index": 6, "correct_answer": "日日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她日日出国留学。", "explanation": "这里不能用〈日日〉：出国留学是一次性的事，“日日”指每天重复，应改用〈终于〉。"}, {"text": "中秋节日日到来。", "explanation": "这里不能用〈日日〉：中秋节每年只有一次，应改用〈每年〉。"}, {"text": "他日日考上大学。", "explanation": "这里不能用〈日日〉：考上大学只发生一次，“日日”指每天重复，应改用〈终于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很日日打扫房间，家里干净多了。", "corrected_sentence": "妈妈日日打扫房间，家里干净多了。", "error_description": "错误在于“很”。“日日”本身已表示每天，是频率副词，不能再被程度副词“很”修饰，应说“日日打扫房间”，不能说“很日日打扫房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他日日了练琴，手艺越来越好。", "corrected_sentence": "他日日练琴，手艺越来越好。", "error_description": "“了”不能放在“日日”和动词“练”之间。这里说的是每天的习惯，应直接说“日日练琴”，不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
