INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在几样事物中突出这一个，比别的都更加突出。", "primary_collocate": null, "pronunciation": "zuì shì", "ipa": "tsweɪ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "春天的花园里，最是桃花开得好看。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多礼物，最是妈妈送的那本书让我难忘。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都很热情，最是小王对我好。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的小城很安静，最是下雨的时候让人想家。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人坐在一起吃饭，最是这个时候让人开心。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了很多画，最是那张山水画让我喜欢。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的话不多，最是那句“慢慢来”我记得清楚。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的天空很蓝，最是傍晚的云好看。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱过很多歌，最是那首老歌让人感动。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江边风景很多，最是夜里的灯光美。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，放在形容词或小句前，表示在几样东西里这一个比别的都更加突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 夜里 (Zipf 3.96), 小城 (Zipf 3.69), 想家 (Zipf 3.1)']::text[], '022b152c-b6f1-4ed2-be3b-0dae6b156b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最是", "is_correct": true, "explanation": "正确。句中在春天的花园里突出桃花开得最好看。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示与预期相反，句中没有这种对比。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前文没有需要转折的内容。"}, {"text": "越", "is_correct": false, "explanation": "搭配：“越”要成对使用（越……越……），不能单独修饰“桃花开得好看”。"}], "explanations": {"最是": "正确。句中在春天的花园里突出桃花开得最好看。", "偏": "语义：“偏”表示与预期相反，句中没有这种对比。", "却": "语义：“却”表示转折，前文没有需要转折的内容。", "越": "搭配：“越”要成对使用（越……越……），不能单独修饰“桃花开得好看”。"}, "sentence_index": 0, "correct_answer": "最是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最是随便看看，没有买东西。", "explanation": "这里应该用〈只是〉。最是要在几样事物中突出一个，这里只是轻描淡写地叙述，没有比较的对象。"}, {"text": "我昨天在家看书，最是看了一个下午。", "explanation": "这里应该用〈只〉。最是要在几样事物中突出程度最高的一个，单纯说明看了多久时要用只。"}, {"text": "我们周末最是一起去公园散步。", "explanation": "这里应该用〈经常〉。最是要在几样事物中突出程度最高的一个，表示惯常做某事时要用经常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最是", "is_correct": true, "explanation": "正确。句中突出老人的话不多，而那句“慢慢来”让人印象最深。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或动词，不能直接修饰‘那句‘慢慢来’’这样的名词短语。"}, {"text": "居然", "is_correct": false, "explanation": "语义：“居然”表示出乎意料，句中没有意外的情况。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“记得清楚”的强调不符。"}], "explanations": {"最是": "正确。句中突出老人的话不多，而那句“慢慢来”让人印象最深。", "十分": "搭配：“十分”修饰形容词或动词，不能直接修饰‘那句‘慢慢来’’这样的名词短语。", "居然": "语义：“居然”表示出乎意料，句中没有意外的情况。", "偶尔": "语义：“偶尔”表示不常发生，与“记得清楚”的强调不符。"}, "sentence_index": 6, "correct_answer": "最是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这最是我要找的人。", "explanation": "这里应该用〈就是〉。最是要在几样事物中突出一个，这里只是肯定，没有比较的对象。"}, {"text": "我最是很爱吃鱼。", "explanation": "这里应该用〈非常〉。最是表示在几样事物中突出一个，与“很”并用语义重复；单纯表示程度高时用非常。"}, {"text": "他跑得很快，最是跑了一圈就累了。", "explanation": "这里应该用〈只〉。最是表示在几样事物中突出一个，描述数量少时要用只。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上海的夜景很美，很最是外滩的灯光让人难忘。", "corrected_sentence": "上海的夜景很美，最是外滩的灯光让人难忘。", "error_description": "错误：“最是”前面不能再加程度副词“很”，两者重复。正确：“最是外滩的灯光让人难忘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个山村的景色很美，最是的清晨的雾让人难忘。", "corrected_sentence": "这个山村的景色很美，最是清晨的雾让人难忘。", "error_description": "错误：“最是”后多加了“的”，“是”与“的”连用，“最是的清晨的雾”不成句。正确：“最是清晨的雾”，“最是”后直接接名词性短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a27a61-4f04-444b-87fb-71432422475b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
