INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "法院是人们打官司、由法官判断是非对错的地方。", "primary_collocate": null, "pronunciation": "fǎ yuàn", "ipa": "fa˨˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "法院就在警察局旁边，走路很近。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天要去法院参加审判，所以请了假。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院门口站着很多等消息的人。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所法院很大，有十几间审判室。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友坐地铁到法院去旁听。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次审判在法院的第三审判庭进行。", "target_word": "法院", "complexity_tier": "T3", "furigana": "fǎ yuàn", "sentence_source": "generated"}, {"text": "法官每天在法院里听两边说话。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子问：“法官在法院里做什么？”", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，法院是判断对错的地方。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵了很久，最后一起去法院。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一所法院", "label": "量词"}, {"form": "基层法院", "label": "复合"}, {"form": "中级法院", "label": "复合"}], "register": "中性", "sense_fingerprint": "法院：判断对错的地方，指人们去的那个场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件、判断是非的场所。"}, {"text": "发源", "is_correct": false, "explanation": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。"}, {"text": "复员", "is_correct": false, "explanation": "复员 fù yuán 与 fǎ yuàn 两个音节的声调都不同，意思是军人退伍后回到原来的工作或生活。"}, {"text": "发愿", "is_correct": false, "explanation": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。"}, {"text": "画院", "is_correct": false, "explanation": "画院 huà yuàn 声母 h 与 f 不同，声调也不同（huà 第四声），意思是培养画家、研究绘画的机构。"}, {"text": "附院", "is_correct": false, "explanation": "附院 fù yuàn 第一个音节韵母不同（u 与 a），声调也不同（fù 第四声），是附属医院的简称。"}], "explanations": {"法院": "法院：审理案件、判断是非的场所。", "发源": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。", "复员": "复员 fù yuán 与 fǎ yuàn 两个音节的声调都不同，意思是军人退伍后回到原来的工作或生活。", "发愿": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。", "画院": "画院 huà yuàn 声母 h 与 f 不同，声调也不同（huà 第四声），意思是培养画家、研究绘画的机构。", "附院": "附院 fù yuàn 第一个音节韵母不同（u 与 a），声调也不同（fù 第四声），是附属医院的简称。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件的场所，符合“就在警察局旁边，走路很近”。"}, {"text": "法律", "is_correct": false, "explanation": "语义：法律是抽象的规则，不是可以“就在…旁边、走路很近”的地方。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：手机是物品，“走路很近”说的是可以走过去的场所，不能说“手机走路很近”。"}, {"text": "警察局", "is_correct": false, "explanation": "语义：句中已用警察局作参照，“警察局就在警察局旁边”指代不通。"}], "explanations": {"法院": "法院：审理案件的场所，符合“就在警察局旁边，走路很近”。", "法律": "语义：法律是抽象的规则，不是可以“就在…旁边、走路很近”的地方。", "手机": "搭配：手机是物品，“走路很近”说的是可以走过去的场所，不能说“手机走路很近”。", "警察局": "语义：句中已用警察局作参照，“警察局就在警察局旁边”指代不通。"}, "sentence_index": 0, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在法院上陈述了事实。", "explanation": "这里应该用〈法庭〉。“在法庭上”指案件审理的场所，“法院”是机构或建筑，不说“在法院上”。"}, {"text": "他生病了，就去法院看病。", "explanation": "这里应该用〈医院〉。看病是医院的职能；法院是审判案件的地方，不能用来看病，所以这句话不成立。"}, {"text": "我每次路过这台法院都会看一眼。", "explanation": "这里应该用〈所〉。“台”用于机器、演出等，法院是建筑和机构，量词说“一所法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件、判断是非的场所。"}, {"text": "马院", "is_correct": false, "explanation": "马院 mǎ yuàn 声母 m 与 f 不同，声调相同（第三声），是“马克思主义学院”的简称。"}, {"text": "合院", "is_correct": false, "explanation": "合院 hé yuàn 声母 h 与 f 不同，声调也不同（hé 第二声），意思是四周房屋围成的院落。"}, {"text": "府院", "is_correct": false, "explanation": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。"}, {"text": "房院", "is_correct": false, "explanation": "房院 fáng yuàn 第一个音节韵母多一个 ng，声调也不同（fáng 第二声），意思是房屋和院子。"}], "explanations": {"法院": "法院：审理案件、判断是非的场所。", "马院": "马院 mǎ yuàn 声母 m 与 f 不同，声调相同（第三声），是“马克思主义学院”的简称。", "合院": "合院 hé yuàn 声母 h 与 f 不同，声调也不同（hé 第二声），意思是四周房屋围成的院落。", "府院": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。", "房院": "房院 fáng yuàn 第一个音节韵母多一个 ng，声调也不同（fáng 第二声），意思是房屋和院子。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件、听取双方陈述的场所，符合句意。"}, {"text": "医院", "is_correct": false, "explanation": "语义：法官不在医院工作，“在医院里听两边说话”与句中的法官身份不合。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“听两边说话”需要争议双方在场的场所，厨房不搭配。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是审理纠纷的场所，“法官在学校里听两边说话”不合常理。"}], "explanations": {"法院": "法院：审理案件、听取双方陈述的场所，符合句意。", "医院": "语义：法官不在医院工作，“在医院里听两边说话”与句中的法官身份不合。", "厨房": "搭配：“听两边说话”需要争议双方在场的场所，厨房不搭配。", "学校": "语义：学校不是审理纠纷的场所，“法官在学校里听两边说话”不合常理。"}, "sentence_index": 6, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们吵了很久，最后一起去法院报了案。", "explanation": "这里应该用〈警察局〉。报案是向警察局报告违法事件，法院负责审判，不说“去法院报案”。"}, {"text": "他们吵了很久，最后一起去法院举报对方。", "explanation": "这里应该用〈检察院〉。举报是向检察院或公安机关检举违法行为，法院负责审判，不说“去法院举报”。"}, {"text": "他们吵了很久，最后一起去了一辆法院。", "explanation": "这里应该用〈所〉。“辆”只用于车辆，法院是机构和建筑，量词说“一所法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天下班都路过一个法院的门口。", "corrected_sentence": "我每天下班都路过一所法院的门口。", "error_description": "错误：“法院”是机构和建筑，量词应用“所”，不能用“个”。正确：应说“一所法院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去着法院两次，都是为了旁听。", "corrected_sentence": "我去过法院两次，都是为了旁听。", "error_description": "错误：表示曾经有过经历，应用“过”，“着”表示持续状态，不能用在“去”后面。正确：应说“去过法院两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
