INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家的审判机关,依法审理案件。", "primary_collocate": null, "pronunciation": "fǎ yuàn", "ipa": "fa˨˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "法院依法审理了这个案件。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院作出了公正的判决。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这起案子由当地法院负责审理。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不同意判决，向上一级法院提出了申诉。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院是国家的审判机关。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把公司告上了法院。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院要求他在三天内交出证据。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院的法官必须按照法律来判案。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件案子，法院下个月才会判决。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院认为证据不够，宣布他无罪。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一所法院", "label": "量词"}, {"form": "基层法院", "label": "复合"}, {"form": "中级法院", "label": "复合"}], "register": "中性", "sense_fingerprint": "法院：国家的审判机关，依法审理案件、作出判决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，依法审理案件。"}, {"text": "发源", "is_correct": false, "explanation": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。"}, {"text": "复员", "is_correct": false, "explanation": "复员 fù yuán 与 fǎ yuàn 两个音节的声调都不同，意思是军人退伍后回到原来的工作或生活。"}, {"text": "发愿", "is_correct": false, "explanation": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。"}, {"text": "画院", "is_correct": false, "explanation": "画院 huà yuàn 声母 h 与 f 不同，声调也不同（huà 第四声），意思是培养画家、研究绘画的机构。"}], "explanations": {"法院": "法院：国家的审判机关，依法审理案件。", "发源": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。", "复员": "复员 fù yuán 与 fǎ yuàn 两个音节的声调都不同，意思是军人退伍后回到原来的工作或生活。", "发愿": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。", "画院": "画院 huà yuàn 声母 h 与 f 不同，声调也不同（huà 第四声），意思是培养画家、研究绘画的机构。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，符合“依法审理了这个案件”。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是企业，不是审判机关，不能“依法审理案件”。"}, {"text": "律师", "is_correct": false, "explanation": "搭配：“审理案件”的主语应是审判机关；律师只代理案件，不能说“律师依法审理”。"}, {"text": "检察院", "is_correct": false, "explanation": "语义：检察院负责提起公诉，不负责审理案件，与“依法审理”不合。"}], "explanations": {"法院": "法院：国家的审判机关，符合“依法审理了这个案件”。", "公司": "语义：公司是企业，不是审判机关，不能“依法审理案件”。", "律师": "搭配：“审理案件”的主语应是审判机关；律师只代理案件，不能说“律师依法审理”。", "检察院": "语义：检察院负责提起公诉，不负责审理案件，与“依法审理”不合。"}, "sentence_index": 0, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起案子由法院提起公诉，指控他抢劫。", "explanation": "这里应该用〈检察院〉。提起公诉是检察院的职责，法院负责审判，不能说“由法院提起公诉”。"}, {"text": "法院上周就开始侦查这起抢劫案。", "explanation": "这里应该用〈警察局〉。侦查是公安机关的工作，法院负责审理，不能说“法院侦查”。"}, {"text": "他在一位法院工作了十年。", "explanation": "这里应该用〈所〉。“位”用于人，法院是机构，量词说“一所法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，依法审理案件。"}, {"text": "马院", "is_correct": false, "explanation": "马院 mǎ yuàn 声母 m 与 f 不同，声调相同（第三声），是“马克思主义学院”的简称。"}, {"text": "合院", "is_correct": false, "explanation": "合院 hé yuàn 声母 h 与 f 不同，声调也不同（hé 第二声），意思是四周房屋围成的院落。"}, {"text": "府院", "is_correct": false, "explanation": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。"}, {"text": "房院", "is_correct": false, "explanation": "房院 fáng yuàn 第一个音节韵母多一个 ng，声调也不同（fáng 第二声），意思是房屋和院子。"}], "explanations": {"法院": "法院：国家的审判机关，依法审理案件。", "马院": "马院 mǎ yuàn 声母 m 与 f 不同，声调相同（第三声），是“马克思主义学院”的简称。", "合院": "合院 hé yuàn 声母 h 与 f 不同，声调也不同（hé 第二声），意思是四周房屋围成的院落。", "府院": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。", "房院": "房院 fáng yuàn 第一个音节韵母多一个 ng，声调也不同（fáng 第二声），意思是房屋和院子。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，可以“要求他在三天内交出证据”。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是违法的人，没有权力要求别人交出证据。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“要求…交出证据”需要调查或审判的权限，厨师没有这种搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地点，不能作“要求”的主语。"}], "explanations": {"法院": "法院：国家的审判机关，可以“要求他在三天内交出证据”。", "小偷": "语义：小偷是违法的人，没有权力要求别人交出证据。", "厨师": "搭配：“要求…交出证据”需要调查或审判的权限，厨师没有这种搭配。", "花园": "语义：花园是地点，不能作“要求”的主语。"}, "sentence_index": 6, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场纠纷在法院上进行了辩论。", "explanation": "这里应该用〈法庭〉。“在法庭上”指开庭的场所，“法院”指机构，不说“在法院上”。"}, {"text": "这辆法院昨天宣布，他被判了三年。", "explanation": "这里应该用〈所〉。“辆”只用于车辆，法院是机构，量词说“一所法院”。"}, {"text": "法院接受了他的委托，准备打官司。", "explanation": "这里应该用〈律师事务所〉。接受委托、代理诉讼是律师事务所的业务，法院不接受委托。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这起案件，一个法院已经受理了。", "corrected_sentence": "这起案件，法院已经受理了。", "error_description": "错误：“法院”是机构名词，不能用量词“个”，应用“所”（如“一所法院”）。这里“法院”泛指受理案件的机关，不计数，去掉“一个”即可：“法院已经受理了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这起案子已法院审结。", "corrected_sentence": "这起案子已由法院审结。", "error_description": "介词漏用：“法院”作审结的施事，前面需要介词“由”，应说“已由法院审结”；去掉“由”成“已法院审结”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
