INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89155, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "据悉是说，听别人讲或看到消息，知道了某件事。", "primary_collocate": null, "pronunciation": "jù xī", "ipa": "tɕy˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "据悉，他下个月要搬到北京去。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，王经理昨天已经离开公司了。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，那家饭馆换了新老板。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，小张准备明年结婚。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，这位老人一个人住了十年。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，他们俩早就认识了。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，那条街下周要修路。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，他的孩子考上了大学。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，李教授会来我们学校讲课。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，这个小村子以前没有电。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "听说或看到消息后得知某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "据悉", "is_correct": true, "explanation": "正确。据悉表示听来或看到的消息，与“他下个月要搬到北京去”的转述语境相符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求动作者本人去做，不能放在句首修饰“下个月要搬到北京去”这类安排。"}, {"text": "向来", "is_correct": false, "explanation": "语义：“向来”表示一贯如此，与“下个月要搬”这一次性的安排矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示偶然发生，与“下个月要搬到北京去”的明确计划不符。"}], "explanations": {"据悉": "正确。据悉表示听来或看到的消息，与“他下个月要搬到北京去”的转述语境相符。", "亲自": "搭配：“亲自”要求动作者本人去做，不能放在句首修饰“下个月要搬到北京去”这类安排。", "向来": "语义：“向来”表示一贯如此，与“下个月要搬”这一次性的安排矛盾。", "偶尔": "语义：“偶尔”表示偶然发生，与“下个月要搬到北京去”的明确计划不符。"}, "sentence_index": 0, "correct_answer": "据悉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我据悉看见他骑车摔倒了。", "explanation": "这里应该用〈亲眼〉。据悉表示听来或看到的消息，不能用来说自己亲眼看到的事。"}, {"text": "我据悉听到老板说要加薪。", "explanation": "这里应该用〈亲耳〉。据悉表示转述的消息，不能用来说自己亲耳听到的话。"}, {"text": "这件事我据悉经历过。", "explanation": "这里应该用〈亲身〉。据悉不能用来说自己亲身经历的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "据悉", "is_correct": true, "explanation": "正确。据悉表示听来的消息，与“那条街下周要修路”的转述语境相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指事情突然发生，与“下周要修路”的预定安排矛盾。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”指当时当地发生的事，不能用于将来的安排。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“下周”的时间不符。"}], "explanations": {"据悉": "正确。据悉表示听来的消息，与“那条街下周要修路”的转述语境相符。", "忽然": "语义：“忽然”指事情突然发生，与“下周要修路”的预定安排矛盾。", "当场": "搭配：“当场”指当时当地发生的事，不能用于将来的安排。", "立刻": "语义：“立刻”表示马上，与“下周”的时间不符。"}, "sentence_index": 6, "correct_answer": "据悉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我据悉问过他这件事。", "explanation": "这里应该用〈当面〉。据悉表示听来或看到的消息，不能用来说自己当面问过的事。"}, {"text": "我据悉做了一顿晚饭。", "explanation": "这里应该用〈亲手〉。据悉不能用来说自己亲手做的事。"}, {"text": "我据悉去医院看了他。", "explanation": "这里应该用〈亲自〉。据悉表示转述的消息，不能用来说自己亲自去做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "据悉说，他们俩下个月订婚。", "corrected_sentence": "据悉，他们俩下个月订婚。", "error_description": "错误：“据悉”是副词，后面不能再加“说”。“据说”与“据悉”是两个不同的词，不要混用。应改为“据悉，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "据悉的，这个小村子明年就能通上电。", "corrected_sentence": "据悉，这个小村子明年就能通上电。", "error_description": "错误：“据悉”是副词，不能加“的”修饰名词。应去掉“的”，写作“据悉，……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
