INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89156, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "根据得到的消息知道，多用于新闻报道。", "primary_collocate": null, "pronunciation": "jù xī", "ipa": "tɕy˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "据悉，新地铁线下个月开通。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，这家公司明年要招一百名新人。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，今天的比赛推迟到明天。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，这座桥已经修了三年。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，那位作家正在写新书。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，警方已经找到了那辆车。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，本市今年的天气比去年热。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，这部电影会在国庆节上映。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，学校计划建一座新图书馆。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据悉，两国的领导人下周见面。", "target_word": "据悉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "新闻报道中引出消息来源的用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "据悉", "is_correct": true, "explanation": "正确。据悉表示消息来源，与“新地铁线”的新闻语境相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指事情忽然发生，与“下个月开通”的计划矛盾。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”指当时当地发生的事，不能用于下个月的安排。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上，与“下个月开通”的时间不符。"}], "explanations": {"据悉": "正确。据悉表示消息来源，与“新地铁线”的新闻语境相符。", "突然": "语义：“突然”指事情忽然发生，与“下个月开通”的计划矛盾。", "当场": "搭配：“当场”指当时当地发生的事，不能用于下个月的安排。", "立即": "语义：“立即”表示马上，与“下个月开通”的时间不符。"}, "sentence_index": 0, "correct_answer": "据悉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我据悉看见他摔了一跤。", "explanation": "这里应该用〈亲眼〉。据悉表示从别人或媒体得知的消息，不能用来说自己亲眼看到的事。"}, {"text": "我据悉去了那家医院。", "explanation": "这里应该用〈亲自〉。据悉表示转述的消息，不能用来说自己亲自做的事。"}, {"text": "我据悉听到他说要搬走。", "explanation": "这里应该用〈亲耳〉。据悉表示从别人或媒体得知的消息，不能用来说自己亲耳听到的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
