INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情为什么这样或那样做的根据。", "primary_collocate": null, "pronunciation": "lǐ yóu", "ipa": "li˨˩˦ jou˧˥", "syllable_count": 2, "sentences": [{"text": "你有什么理由不去上课？", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的理由很清楚。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们说出自己的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个理由不够好，我不同意。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有理由，他不会这样做。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个很好的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了我们三个理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的理由是天气太冷。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我拒绝的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到相信他的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "做事或下判断所依据的根据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室不是不去上课的原因，“有什么教室不去上课”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有什么”后接的是可以说明原因的词，“天气”不能这样接，“有什么天气不去上课”不通。"}, {"text": "理由", "is_correct": true, "explanation": "正确：“有什么理由”是询问原因的固定说法，“不去上课”需要一个根据，符合句意。"}, {"text": "力气", "is_correct": false, "explanation": "语义：力气不能作为不去上课的根据，句意不通。"}], "explanations": {"教室": "语义：教室不是不去上课的原因，“有什么教室不去上课”说不通。", "天气": "搭配：“有什么”后接的是可以说明原因的词，“天气”不能这样接，“有什么天气不去上课”不通。", "理由": "正确：“有什么理由”是询问原因的固定说法，“不去上课”需要一个根据，符合句意。", "力气": "语义：力气不能作为不去上课的根据，句意不通。"}, "sentence_index": 0, "correct_answer": "理由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的理由很先进，大家都很佩服。", "explanation": "这里应该用〈理念〉。“先进”形容理念、技术等，“理由”指做事的根据，不能说“很先进”。"}, {"text": "他提出了一块理由。", "explanation": "量词不当：理由是抽象的，应说“一个理由”或“一条理由”；“块”用于块状的东西，不用于理由。"}, {"text": "这次火灾的理由是电线老化。", "explanation": "这里应该用〈原因〉。“理由”指人做事或说明做法的根据，火灾等事情的起因应说“原因”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "配价：“给”要求能被给予的事物作宾语，月亮不能被公司给人，句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以一个一个数着送给人的东西，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“三个”后接“天空”不符合常规的计量说法，“三个天空”不通。"}, {"text": "理由", "is_correct": true, "explanation": "正确：“理由”是可数名词，“公司给了我们三个理由”符合句意，表示公司提出的三点根据。"}], "explanations": {"月亮": "配价：“给”要求能被给予的事物作宾语，月亮不能被公司给人，句意不通。", "大海": "语义：大海不是可以一个一个数着送给人的东西，句意不通。", "天空": "搭配：“三个”后接“天空”不符合常规的计量说法，“三个天空”不通。", "理由": "正确：“理由”是可数名词，“公司给了我们三个理由”符合句意，表示公司提出的三点根据。"}, "sentence_index": 6, "correct_answer": "理由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发生了理由，所以没来。", "explanation": "词义混淆：“发生”多用于事件、事故，“理由”指做事的根据，不是事件；这里应说“事件”，不说“理由发生”。"}, {"text": "我们的理由很远大，值得尊敬。", "explanation": "这里应该用〈理想〉。“远大”形容理想、抱负，“理由”指做事的根据，不能说“很远大”。"}, {"text": "这个理由重了五公斤。", "explanation": "用法错误：“理由”是抽象的根据，没有重量，不能说“重了五公斤”；说重量的应是“行李”等实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了三张理由。", "corrected_sentence": "他提出了三条理由。", "error_description": "量词错误：“理由”应说“三条理由”或“三个理由”；“张”用于纸张、桌子等平面的东西，不能用来数理由。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有出说理由。", "corrected_sentence": "他没有说出理由。", "error_description": "补语位置错误：结果补语“出”应紧跟动词“说”，说“说出理由”；“出说理由”的语序不对，母语者会立刻察觉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "设或是“要是”的意思，说一件还没发生的事。", "primary_collocate": null, "pronunciation": "shè huò", "ipa": "ʂɤ˥˩ xwo˥˩", "syllable_count": 2, "sentences": [{"text": "设或你明年去北京，可以住在我家。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或明天考试，你今晚就早点睡吧。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或我忘了带钥匙，你能给我开门吗？", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或下个月涨工资，我就买一台新电脑。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或他明天不来，会议就改到后天。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或你将来回到这里，一定要来找我。", "target_word": "设或", "complexity_tier": "T3", "furigana": "shè huò nǐ jiānglái huídào zhèlǐ, yídìng yào lái zhǎo wǒ。", "sentence_source": "generated"}, {"text": "设或这次比赛赢了，我请大家吃饭。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或你迷路了，就给我打电话。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或明早起不来，请你叫我一声。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或买不到票，我们就明天再走。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "設或", "label": "繁体"}], "register": "书面", "sense_fingerprint": "连词，相当于“要是”，假设一件还没发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7f8796-b995-49d4-a98e-f68767af4dc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，句中没有相反的前文，不能引出假设。"}, {"text": "设或", "is_correct": true, "explanation": "正确：相当于“要是”，假设你明年去北京。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”要接在原因或结果之后，不能引出还没发生的假设。"}, {"text": "何况", "is_correct": false, "explanation": "语义：“何况”表示递进，要以前文为基础，不能用来引出假设的条件。"}], "explanations": {"然而": "语义：“然而”表示转折，句中没有相反的前文，不能引出假设。", "设或": "正确：相当于“要是”，假设你明年去北京。", "因此": "搭配：“因此”要接在原因或结果之后，不能引出还没发生的假设。", "何况": "语义：“何况”表示递进，要以前文为基础，不能用来引出假设的条件。"}, "sentence_index": 0, "correct_answer": "设或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "设或我昨天已经买了电脑，你就不用再买了。", "explanation": "这里应该用〈既然〉。“设或”只说尚未发生的假设，这里说的是已经发生的事。"}, {"text": "设或天气很冷，他昨天还是跑步去了。", "explanation": "这里应该用〈虽然〉。「设或」表示假设，不能与「昨天」这样已经发生的时间搭配，应说「虽然……还是」。"}, {"text": "这道题设或老师昨天都没做出来。", "explanation": "这里应该用〈连〉。「设或」表示假设，不能表示强调，且这里说的是昨天已经发生的情况，应说「连……都」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否则", "is_correct": false, "explanation": "语义：「否则」表示不然会怎样，要接在前句的做法之后，不能引出「比赛赢了」这一假设条件。"}, {"text": "设或", "is_correct": true, "explanation": "正确：相当于“要是”，假设这次比赛赢了。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，不能引出假设的条件。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示进一步补充理由，不能用来引出假设。"}], "explanations": {"否则": "语义：「否则」表示不然会怎样，要接在前句的做法之后，不能引出「比赛赢了」这一假设条件。", "设或": "正确：相当于“要是”，假设这次比赛赢了。", "反而": "语义：“反而”表示与预期相反，不能引出假设的条件。", "况且": "语义：“况且”表示进一步补充理由，不能用来引出假设。"}, "sentence_index": 6, "correct_answer": "设或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你坐火车设或飞机都可以。", "explanation": "这里应该用〈或者〉。“设或”表示假如，不表示选择。"}, {"text": "他一直在努力，设或昨天终于成功了。", "explanation": "这里应该用〈终于〉。「设或」只说尚未发生的假设，这里说的是昨天已经发生的结果。"}, {"text": "他没有准备，考试设或昨天已经失败了。", "explanation": "这里应该用〈因此〉。「设或」只表示假设，这里说的是已经发生的结果，应说「因此」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "设或了天气好，我们就去爬山。", "corrected_sentence": "设或天气好，我们就去爬山。", "error_description": "错误：“设或了天气好”，应为“设或天气好”。假设连词“设或”后不能加“了”，“了”表示已经完成，与尚未发生的假设相矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "设或的你不喜欢这家，我们就换一家。", "corrected_sentence": "设或你不喜欢这家，我们就换一家。", "error_description": "错误：“设或的你”，应为“设或你”。连词“设或”后面直接接分句的主语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
