INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把文章、词语、作品等收进书籍或汇集中。", "primary_collocate": null, "pronunciation": "shōu lù", "ipa": "ʂoʊ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这部词典收录了五万个词语。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套课本收录了很多经典文章。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的三篇文章都收录进了文集。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站收录了许多老电影的资料。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新版词典也收录了“网红”这个词。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本诗选没有收录这首诗。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "编辑把她的小说收录到年度选集里。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书收录过很多名家的散文。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文集里收录着他一生的作品。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这本杂志收录这篇文章吗？", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "收录了", "label": "体标"}, {"form": "收录过", "label": "体标"}, {"form": "收錄", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "把文章、词语、作品等编入书籍或汇集", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965e8b9c-2139-44a0-a62f-27461e03fcbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
