INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里人是住在同一个地方的人。", "primary_collocate": null, "pronunciation": "lǐ rén", "ipa": "li˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他和我是里人，从小一起长大。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的里人都很热情。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "里人都来帮他盖房子。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地人来了，里人热情地招待他们。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇上的里人互相照应，关系很亲近。", "target_word": "里人", "complexity_tier": "T3", "furigana": "zhè gè xiǎo zhèn shàng de lǐ rén hù xiāng zhào yìng, guān xì hěn qīn jìn.", "sentence_source": "generated"}, {"text": "过年时，里人聚在一起吃饭。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我搬来以后，里人都说这里的水特别甜。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在村口遇到了一位里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是我们村里最老的里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难，里人总会互相帮忙。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "里人:住在同一个地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：住在同一个地方的人，与“从小一起长大”的关系相合。"}, {"text": "外人", "is_correct": false, "explanation": "语义：“外人”指不属于自己圈子的人，与“从小一起长大”的亲近关系相矛盾。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”指互不认识的人，与“从小一起长大”明显不合。"}, {"text": "宾客", "is_correct": false, "explanation": "语域：“宾客”是正式用词，与“从小一起长大”这种口语化叙述的语域不合。"}], "explanations": {"里人": "里人：住在同一个地方的人，与“从小一起长大”的关系相合。", "外人": "语义：“外人”指不属于自己圈子的人，与“从小一起长大”的亲近关系相矛盾。", "陌生人": "语义：“陌生人”指互不认识的人，与“从小一起长大”明显不合。", "宾客": "语域：“宾客”是正式用词，与“从小一起长大”这种口语化叙述的语域不合。"}, "sentence_index": 0, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指学校，应改用〈母校〉。"}, {"text": "景区的里人都来自各地。", "explanation": "这里不能用〈里人〉：“里人”指住在同一个地方的人，来自各地的游客不住在同一个地方，应改用〈游客〉。"}, {"text": "两个国家的人在联合国开会，他们都是里人。", "explanation": "这里不能用〈里人〉：两国的人分属不同的国家，与“住在同一个地方”不符，应改用〈代表〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：住在同一个地方的人，说话人也是这里的人，与“这里的水”的语境相合。"}, {"text": "祖先", "is_correct": false, "explanation": "语义：“祖先”已故，不能说话评价眼前的水，与“说”不合。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”还不会表达这种评价，与“说这里的水特别甜”不合。"}, {"text": "陛下", "is_correct": false, "explanation": "语域：“陛下”是对君主的敬称，与这句日常叙述的语域不合。"}], "explanations": {"里人": "里人：住在同一个地方的人，说话人也是这里的人，与“这里的水”的语境相合。", "祖先": "语义：“祖先”已故，不能说话评价眼前的水，与“说”不合。", "婴儿": "语义：“婴儿”还不会表达这种评价，与“说这里的水特别甜”不合。", "陛下": "语域：“陛下”是对君主的敬称，与这句日常叙述的语域不合。"}, "sentence_index": 6, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的里人是我远在国外的亲哥哥。", "explanation": "这里不能用〈里人〉：“里人”指住在同一个地方的人，远在国外的亲哥哥不在同一地方，应改用〈家人〉。"}, {"text": "我在国外遇到的中国人都是我的里人。", "explanation": "这里不能用〈里人〉：国外的中国人与我不在同一个地方，应改用〈同胞〉。"}, {"text": "这只狗是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指动物，应改用〈宠物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节时，一只里人回来团聚。", "corrected_sentence": "春节时，一位里人回来团聚。", "error_description": "量词错误：“里人”指人，应用〈位〉，不能用〈只〉（〈只〉多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很里人都来帮我修房子。", "corrected_sentence": "我的里人都来帮我修房子。", "error_description": "“很”是程度副词，不能修饰名词“里人”。“我”与“里人”之间应加“的”，应说“我的里人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
