INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同乡的人;同里的人(旧时用语)。", "primary_collocate": null, "pronunciation": "lǐ rén", "ipa": "li˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他乡遇到里人，格外高兴。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，那位客人是他的里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时里人常常互相照应。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门在外，里人最亲。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在京城认识了几位里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位里人在异地相见，聊了很久。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先生是我的里人，也姓李。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "里人听说他回来了，都来看望。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在京城相遇，原来竟是多年的里人。", "target_word": "里人", "complexity_tier": "T3", "furigana": "tā men zài jīng chéng xiāng yù, yuán lái jìng shì duō nián de lǐ rén.", "sentence_source": "generated"}, {"text": "里人来信说，家乡今年丰收了。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "旧时用语", "sense_fingerprint": "里人:同乡的人,旧时用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：同乡的人，在他乡遇到同乡，格外亲切。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”是有仇怨的对头，他乡相遇不会“格外高兴”，与同乡之义相反。"}, {"text": "债主", "is_correct": false, "explanation": "语义：“债主”指向别人讨债的人，与他乡相遇的“格外高兴”不合，也不是同乡。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”指偷东西的人，与“格外高兴”的情感相矛盾，也不是同乡。"}], "explanations": {"里人": "里人：同乡的人，在他乡遇到同乡，格外亲切。", "仇人": "语义：“仇人”是有仇怨的对头，他乡相遇不会“格外高兴”，与同乡之义相反。", "债主": "语义：“债主”指向别人讨债的人，与他乡相遇的“格外高兴”不合，也不是同乡。", "小偷": "语义：“小偷”指偷东西的人，与“格外高兴”的情感相矛盾，也不是同乡。"}, "sentence_index": 0, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指同乡的人，指的是人，北京是地方，应改用〈故乡〉。"}, {"text": "他在京城认识了几位里人，他们来自五大洲。", "explanation": "这里不能用〈里人〉：“里人”指同乡，来自五大洲的人不可能是同乡，应改用〈朋友〉。"}, {"text": "这家公司的里人都是外国人。", "explanation": "这里不能用〈里人〉：“里人”指同乡，外国员工与我们不是同乡，应改用〈同事〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：同乡的人，说明这位先生与我是同乡，与“也姓李”的叙述相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“我的陌生人”前后矛盾，不能用“我的”修饰“陌生人”。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指过路的人，与“是我的”这种关系不合，也与“也姓李”的说法不符。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：“外国人”指他国国籍的人，与同姓“李”的语境不合。"}], "explanations": {"里人": "里人：同乡的人，说明这位先生与我是同乡，与“也姓李”的叙述相合。", "陌生人": "搭配：“我的陌生人”前后矛盾，不能用“我的”修饰“陌生人”。", "路人": "语义：“路人”指过路的人，与“是我的”这种关系不合，也与“也姓李”的说法不符。", "外国人": "语义：“外国人”指他国国籍的人，与同姓“李”的语境不合。"}, "sentence_index": 6, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和路人都是里人。", "explanation": "这里不能用〈里人〉：路人与我素不相识，未必同乡，应改用〈陌生人〉。"}, {"text": "这只猫是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指动物，应改用〈宠物〉。"}, {"text": "这辆车是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指车辆，应改用〈爱车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在北京遇到一只里人，倍感亲切。", "corrected_sentence": "他在北京遇到一位里人，倍感亲切。", "error_description": "量词错误：“里人”指人，应用〈位〉，不能用〈只〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "里人了托人带口信，问我近况。", "corrected_sentence": "里人托人带口信，问我近况。", "error_description": "“了”不能放在“里人”后面。这里不是完成的动作，应直接说“里人托人带口信”，不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
