INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外国返回本国。", "primary_collocate": null, "pronunciation": "huí guó", "ipa": "xweɪ˧˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他结束了国外的工作，决定回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在英国读书，今年六月回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回国以后，他开了一家小公司。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回国前，买了很多礼物给家人。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回国后很不习惯这里的天气。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大使完成任务后，坐飞机回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在德国工作，很少回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚回国，还没找到合适的工作。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情结束后，很多人终于能回国了。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位歌手在法国住了很久，最近回国了。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回国了", "label": "体标"}, {"form": "回過國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从外国返回本国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7f8796-b995-49d4-a98e-f68767af4dc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回国", "is_correct": true, "explanation": "回国：从外国返回本国。这是本词。"}, {"text": "回锅", "is_correct": false, "explanation": "回锅（huíguō）与 huíguó 第二个音节声调不同（guō 第一声），意思是把食物再加热。"}, {"text": "悔过", "is_correct": false, "explanation": "悔过（huǐguò）与 huíguó 两个音节声调都不同，意思是认识错误并改正。"}, {"text": "回过", "is_correct": false, "explanation": "回过（huíguò）与 huíguó 第二个音节声调不同（guò 第四声），意思是转过或恢复，如“回过神”。"}, {"text": "回顾", "is_correct": false, "explanation": "回顾（huígù）与 huíguó 韵母不同（gù 与 guó），意思是回头看、追述过去。"}], "explanations": {"回国": "回国：从外国返回本国。这是本词。", "回锅": "回锅（huíguō）与 huíguó 第二个音节声调不同（guō 第一声），意思是把食物再加热。", "悔过": "悔过（huǐguò）与 huíguó 两个音节声调都不同，意思是认识错误并改正。", "回过": "回过（huíguò）与 huíguó 第二个音节声调不同（guò 第四声），意思是转过或恢复，如“回过神”。", "回顾": "回顾（huígù）与 huíguó 韵母不同（gù 与 guó），意思是回头看、追述过去。"}, "sentence_index": null, "correct_answer": "回国"}, "level_3": {"options": [{"text": "回国", "is_correct": true, "explanation": "正确：前句说他结束了国外的工作，决定返回本国，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“结束国外工作、做决定”的语境无关，句意不通。"}, {"text": "打针", "is_correct": false, "explanation": "语义：打针是就医行为，与句中的决定不符，句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与“结束工作后决定……”的语境无关，句意不通。"}], "explanations": {"回国": "正确：前句说他结束了国外的工作，决定返回本国，符合句意。", "睡觉": "语义：睡觉与“结束国外工作、做决定”的语境无关，句意不通。", "打针": "语义：打针是就医行为，与句中的决定不符，句意不通。", "吃饭": "语义：吃饭与“结束工作后决定……”的语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "回国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天下班回国做饭，很累。", "explanation": "这里应该用〈回家〉。回国指从外国回到本国，每天下班回到住处不能用“回国”。"}, {"text": "我是中国人，这个暑假想回国去泰国玩。", "explanation": "这里应该用〈出国〉。回国指从外国回到本国，中国人去泰国玩是离开本国，应说“出国”。"}, {"text": "他刚从办公室出来，又回国去拿文件。", "explanation": "这里应该用〈回办公室〉。回国只指从外国回到本国，在办公楼之间往返不能用“回国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回国", "is_correct": true, "explanation": "正确：前句说哥哥在德国工作，所以很少回到本国，符合句意。"}, {"text": "上学", "is_correct": false, "explanation": "语义：哥哥已在德国工作，不是去上学，“上学”与语境不符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”意为结束工作，与“在德国工作”相矛盾，不能说很少退休。"}, {"text": "入学", "is_correct": false, "explanation": "搭配：“入学”针对学生，不能用于正在工作的人。"}], "explanations": {"回国": "正确：前句说哥哥在德国工作，所以很少回到本国，符合句意。", "上学": "语义：哥哥已在德国工作，不是去上学，“上学”与语境不符。", "退休": "语义：“退休”意为结束工作，与“在德国工作”相矛盾，不能说很少退休。", "入学": "搭配：“入学”针对学生，不能用于正在工作的人。"}, "sentence_index": 6, "correct_answer": "回国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是中国人，住在广州，周末回国看朋友。", "explanation": "这里应该用〈回老家〉。住在广州的中国人回老家，是国内移动，不能用“回国”。"}, {"text": "周末我回国自习。", "explanation": "这里应该用〈回学校〉。回国只指从外国回到本国，回学校自习不能用“回国”。"}, {"text": "累了，他回国睡觉。", "explanation": "这里应该用〈回房间〉。回国指从外国返回本国，回到住处的房间不能用“回国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天被回国了。", "corrected_sentence": "他昨天回国了。", "error_description": "错误：“被回国了”。“回国”不能用于被动句，句中多出“被”，应删去，改为“他昨天回国了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚把回国了。", "corrected_sentence": "他刚回国了。", "error_description": "错误：“把回国了”。“回国”不能用于“把”字处置式，句中多出“把”，应删去，改为“他刚回国了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大方", "is_correct": false, "explanation": "与“高兴”没有反义关系，“大方”形容举止不拘谨或不吝啬。"}, {"text": "难过", "is_correct": true, "explanation": "“难过”表示心情不好，与“高兴”的愉快情绪相反，是反义词。"}, {"text": "粗心", "is_correct": false, "explanation": "与“高兴”没有反义关系，“粗心”形容做事不仔细。"}, {"text": "热闹", "is_correct": false, "explanation": "与“高兴”没有反义关系，“热闹”形容场面喧闹、人多。"}], "correct_answer": "难过", "explanations": {"大方": "与“高兴”没有反义关系，“大方”形容举止不拘谨或不吝啬。", "难过": "“难过”表示心情不好，与“高兴”的愉快情绪相反，是反义词。", "粗心": "与“高兴”没有反义关系，“粗心”形容做事不仔细。", "热闹": "与“高兴”没有反义关系，“热闹”形容场面喧闹、人多。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "认真", "is_correct": false, "explanation": "与“高兴”没有反义关系，“认真”形容态度专注、不马虎。"}, {"text": "伤心", "is_correct": true, "explanation": "“伤心”表示难过，与“高兴”的愉快情绪相反，是反义词。"}, {"text": "简单", "is_correct": false, "explanation": "与“高兴”没有反义关系，“简单”形容不复杂。"}, {"text": "明亮", "is_correct": false, "explanation": "与“高兴”没有反义关系，“明亮”形容光线或颜色。"}], "correct_answer": "伤心", "explanations": {"认真": "与“高兴”没有反义关系，“认真”形容态度专注、不马虎。", "伤心": "“伤心”表示难过，与“高兴”的愉快情绪相反，是反义词。", "简单": "与“高兴”没有反义关系，“简单”形容不复杂。", "明亮": "与“高兴”没有反义关系，“明亮”形容光线或颜色。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高兴是心里很快乐,想笑。", "primary_collocate": null, "pronunciation": "gāo xìng", "ipa": "kɑʊ̯˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "看到小狗，孩子很高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天心里特别高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她高兴得一直笑个不停。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟收到新玩具，高兴极了。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷看着我们，高兴地笑了。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见朋友来了，她高兴地拍起手来。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你高兴的时候，喜欢做什么？", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天天气好，大家都很高兴。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她过生日，我们也跟着高兴。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听见孩子的笑声，妈妈心里很高兴。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高兴了", "label": "体标"}, {"form": "高高兴兴", "label": "重叠"}, {"form": "高興", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里快乐想笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤心", "is_correct": false, "explanation": "语义：“伤心”表示难过，与“看到小狗”后孩子的情绪不符。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容神情郑重，与看到小狗时的愉快情绪不符。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”表示心里快乐，与“看到小狗”的情境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述孩子的心情。"}], "explanations": {"伤心": "语义：“伤心”表示难过，与“看到小狗”后孩子的情绪不符。", "严肃": "语义：“严肃”形容神情郑重，与看到小狗时的愉快情绪不符。", "高兴": "“高兴”表示心里快乐，与“看到小狗”的情境相符。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述孩子的心情。"}, "sentence_index": 0, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很高兴那只狗。", "explanation": "这里应该用〈怕〉。高兴表示心里快乐，不能用来表示对某物的害怕。"}, {"text": "这次晚会的气氛很高兴。", "explanation": "这里应该用〈热烈〉。高兴只用来描述人的心情，不能用来形容场合的气氛。"}, {"text": "我很高兴小时候的老朋友。", "explanation": "这里应该用〈怀念〉。高兴表示当下的愉快，不能表示对过去之人的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身材，与“喜欢做什么”的语境不符。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来描述心情或状态。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”表示心里快乐，与“喜欢做什么”的语境相符。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”形容价格低，不能用来形容人或心情状态。"}], "explanations": {"瘦": "体貌：“瘦”形容身材，与“喜欢做什么”的语境不符。", "矮": "体貌：“矮”形容身高，不能用来描述心情或状态。", "高兴": "“高兴”表示心里快乐，与“喜欢做什么”的语境相符。", "便宜": "语义：“便宜”形容价格低，不能用来形容人或心情状态。"}, "sentence_index": 6, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很高兴这本书。", "explanation": "这里应该用〈喜欢〉。高兴表示心里愉快，不能直接带事物作宾语表示喜爱。"}, {"text": "这次展览很高兴。", "explanation": "这里应该用〈精彩〉。高兴只描述人的心情，不能用来评价展览、演出等事物。"}, {"text": "我很高兴远方的亲人。", "explanation": "这里应该用〈思念〉。高兴不能表示对远方亲人的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天很高兴地。", "corrected_sentence": "他今天很高兴。", "error_description": "错误：“很高兴地”。正确：“很高兴”。形容词单独作谓语时后面不加“地”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个高兴孩子笑了。", "corrected_sentence": "那个高兴的孩子笑了。", "error_description": "错误：“高兴孩子”。正确：“高兴的孩子”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难过", "is_correct": true, "explanation": "“难过”表示心情不好，与“高兴”的愉快情绪正相反，是反义词。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“高兴”没有反义关系，“漂亮”形容外貌。"}, {"text": "聪明", "is_correct": false, "explanation": "与“高兴”没有反义关系，“聪明”形容智力。"}, {"text": "干净", "is_correct": false, "explanation": "与“高兴”没有反义关系，“干净”形容没有污垢，与情绪无关。"}], "correct_answer": "难过", "explanations": {"难过": "“难过”表示心情不好，与“高兴”的愉快情绪正相反，是反义词。", "漂亮": "与“高兴”没有反义关系，“漂亮”形容外貌。", "聪明": "与“高兴”没有反义关系，“聪明”形容智力。", "干净": "与“高兴”没有反义关系，“干净”形容没有污垢，与情绪无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示难过，与“高兴”的愉快情绪相反，是反义词。"}, {"text": "坚硬", "is_correct": false, "explanation": "与“高兴”没有反义关系，“坚硬”形容质地硬，与情绪无关。"}, {"text": "热情", "is_correct": false, "explanation": "与“高兴”没有反义关系，“热情”形容待人的态度。"}, {"text": "清楚", "is_correct": false, "explanation": "与“高兴”没有反义关系，“清楚”形容明白、不模糊。"}], "correct_answer": "伤心", "explanations": {"伤心": "“伤心”表示难过，与“高兴”的愉快情绪相反，是反义词。", "坚硬": "与“高兴”没有反义关系，“坚硬”形容质地硬，与情绪无关。", "热情": "与“高兴”没有反义关系，“热情”形容待人的态度。", "清楚": "与“高兴”没有反义关系，“清楚”形容明白、不模糊。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "愉快而兴奋。", "primary_collocate": null, "pronunciation": "gāo xìng", "ipa": "kɑʊ̯˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听到好消息，我很高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她拿到礼物，高兴得跳了起来。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "见到你，我非常高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试得了第一名，他高兴极了。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们高兴地唱着歌回家。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天你为什么这么高兴？", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说：“我今天特别高兴！”", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，大家都很高兴。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我高兴地告诉妈妈，我找到工作了。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没这么高兴过。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高兴了", "label": "体标"}, {"form": "高高兴兴", "label": "重叠"}, {"form": "高興", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到好事而愉快兴奋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤心", "is_correct": false, "explanation": "语义：“伤心”表示难过，与“听到好消息”带来的情绪相反。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”表示愉快，与“好消息”的内容相符，正好填入空位。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”表示孤单、无人作伴的感觉，与听到好消息后的情绪不符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述心情。"}], "explanations": {"伤心": "语义：“伤心”表示难过，与“听到好消息”带来的情绪相反。", "高兴": "“高兴”表示愉快，与“好消息”的内容相符，正好填入空位。", "寂寞": "语义：“寂寞”表示孤单、无人作伴的感觉，与听到好消息后的情绪不符。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述心情。"}, "sentence_index": 0, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很高兴这个礼物。", "explanation": "这里应该用〈喜欢〉。高兴表示心里愉快，不能直接带事物作宾语表示喜爱。"}, {"text": "我很高兴他的勇气。", "explanation": "这里应该用〈佩服〉。高兴只表示心情愉快，不表示对他人品质的敬重。"}, {"text": "童年的时光非常高兴。", "explanation": "这里应该用〈快乐〉。高兴只用来形容人当下的心情，不能用来形容时光或时期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示愤怒，与“笑着说”的状态相矛盾。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”表示恐惧，与“笑着说”的状态相矛盾。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”与“笑着说”的状态一致，符合“特别”和感叹语气。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身材，不能用来描述心情。"}], "explanations": {"生气": "语义：“生气”表示愤怒，与“笑着说”的状态相矛盾。", "害怕": "语义：“害怕”表示恐惧，与“笑着说”的状态相矛盾。", "高兴": "“高兴”与“笑着说”的状态一致，符合“特别”和感叹语气。", "瘦": "体貌：“瘦”形容身材，不能用来描述心情。"}, "sentence_index": 6, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很高兴这只狗。", "explanation": "这里应该用〈怕〉。高兴表示心里愉快，不能用来表示对某物的害怕。"}, {"text": "这次会议很高兴。", "explanation": "这里应该用〈愉快〉。高兴的主语应是人，表示人的心情；形容会议、活动等事情要用〈愉快〉。"}, {"text": "我很高兴远方的家人。", "explanation": "这里应该用〈想念〉。高兴不能表示对远方亲人的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我很高兴地。", "corrected_sentence": "今天我很高兴。", "error_description": "错误：“很高兴地”。正确：“很高兴”。形容词单独作谓语时后面不加“地”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个高兴人走过来。", "corrected_sentence": "一个高兴的人走过来。", "error_description": "错误：“高兴人”。正确：“高兴的人”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：“私人的”指归个人所有，与“国有”（归国家所有）相对。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容声音或环境，与所有权的意义无关。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”形容外貌或景色，与所有权无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：“整齐”形容排列或外观，与所有权无关。"}], "correct_answer": "私人", "explanations": {"私人": "反义：“私人的”指归个人所有，与“国有”（归国家所有）相对。", "安静": "无关：“安静”形容声音或环境，与所有权的意义无关。", "美丽": "无关：“美丽”形容外貌或景色，与所有权无关。", "整齐": "无关：“整齐”形容排列或外观，与所有权无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私有", "is_correct": true, "explanation": "反义：“私有”指归个人所有，与“国有”相对。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情，与所有权无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白或清晰，与所有权无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌，与所有权无关。"}], "correct_answer": "私有", "explanations": {"私有": "反义：“私有”指归个人所有，与“国有”相对。", "高兴": "无关：“高兴”形容心情，与所有权无关。", "清楚": "无关：“清楚”形容明白或清晰，与所有权无关。", "漂亮": "无关：“漂亮”形容外貌，与所有权无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属于国家所有的。", "primary_collocate": null, "pronunciation": "guó yǒu", "ipa": "kwo˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家银行是国有银行，不是私人的。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块土地是国有的，不能随便卖。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家国有企业工作。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国有资产要好好保护。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大桥是国有的，不是私人的。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在国有医院当医生。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家国有公司有一万多名工人。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国有土地上不能自己盖房子。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂以前是国有的，现在卖给了私人公司。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去国有银行贷款买房子。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國有", "label": "繁体"}, {"form": "国有企业", "label": "复合"}, {"form": "国有化", "label": "复合"}], "register": "中性", "sense_fingerprint": "属于国家所有的，与私人的相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e97b369-c5b3-4f14-9e9f-6e44fef3be27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国有", "is_correct": true, "explanation": "正确。“国有”修饰银行，表示归国家所有，与后半句“不是私人的”相呼应。"}, {"text": "私人", "is_correct": false, "explanation": "语义：“私人银行”与后半句“不是私人的”正面矛盾，句子自相抵触。"}, {"text": "私营", "is_correct": false, "explanation": "语义：“私营”指民间经营，与后半句“不是私人的”矛盾。"}, {"text": "国产", "is_correct": false, "explanation": "搭配：“国产”多用于商品，一般不说“国产银行”。"}], "explanations": {"国有": "正确。“国有”修饰银行，表示归国家所有，与后半句“不是私人的”相呼应。", "私人": "语义：“私人银行”与后半句“不是私人的”正面矛盾，句子自相抵触。", "私营": "语义：“私营”指民间经营，与后半句“不是私人的”矛盾。", "国产": "搭配：“国产”多用于商品，一般不说“国产银行”。"}, "sentence_index": 0, "correct_answer": "国有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国有很大，人口也很多。", "explanation": "“国有”是形容词，指财产归国家所有，不能用来指“国家”本身，这里应该用〈国家〉。"}, {"text": "我对你的感情是国有的，别人不要管。", "explanation": "“国有”指财产归国家所有，只能修饰事物，不能用来描述感情；这里应该用〈私人〉表示个人的、不让别人管。"}, {"text": "我的爸爸是国有的，每天都去公司上班。", "explanation": "“国有”只能说财产或企业归国家所有，不能用来指人；把人说成国家的所有物，应该用〈国民〉表示“国家的公民”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国有", "is_correct": true, "explanation": "正确。“国有”修饰公司，表示归国家所有，与“一万多名工人”的规模相合。"}, {"text": "小型", "is_correct": false, "explanation": "语义：“小型”指规模小，与“有一万多名工人”的规模矛盾。"}, {"text": "微型", "is_correct": false, "explanation": "语义：“微型”指极小，与“一万多名工人”明显矛盾。"}, {"text": "国产", "is_correct": false, "explanation": "搭配：“国产”多用于商品，不用来修饰“公司”。"}], "explanations": {"国有": "正确。“国有”修饰公司，表示归国家所有，与“一万多名工人”的规模相合。", "小型": "语义：“小型”指规模小，与“有一万多名工人”的规模矛盾。", "微型": "语义：“微型”指极小，与“一万多名工人”明显矛盾。", "国产": "搭配：“国产”多用于商品，不用来修饰“公司”。"}, "sentence_index": 6, "correct_answer": "国有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国之间的交流是国有的。", "explanation": "“国有”指财产归国家所有，不能表示“国与国之间”，这里应该用〈国际〉。"}, {"text": "我对妈妈的爱非常国有。", "explanation": "“国有”只修饰财产或企业，不能用来形容感情；形容爱的程度应该用〈深厚〉。"}, {"text": "这次演习是国有的任务，很重要。", "explanation": "“国有”指财产归国家所有，不能表示“用于国家防卫”，这里应该用〈国防〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂是国有的的，由政府管理。", "corrected_sentence": "这家工厂是国有的，由政府管理。", "error_description": "错误：“国有”后多加了一个“的”，写成“国有的的”。应去掉重复的“的”，说“是国有的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹在一家很国有银行工作。", "corrected_sentence": "我妹妹在一家国有银行工作。", "error_description": "错误：“国有”是属性词，不能受程度副词“很”修饰。应去掉“很”，说“一家国有银行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
