INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89211, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "否则是说如果不是这样,就会有别的结果。", "primary_collocate": null, "pronunciation": "fǒu zé", "ipa": "foʊ̯˨˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "快点儿吃，否则饭就凉了。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你必须努力，否则不会成功。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别忘了锁门，否则不安全。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以前回家，否则妈妈会担心。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要早点出发，否则赶不上火车。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把窗户关上，否则房间会很冷。", "target_word": "否则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，必须交作业，否则不能考试。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一定没看到信息，否则早就回电话了。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要带着护照，否则上不了飞机。", "target_word": "否则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完药要休息，否则病好得慢。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "否則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "如果不是这样就会有别的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“快点儿吃”与“饭就凉了”之间不构成因果关系。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与“快点儿吃”的要求及后果的关系不符。"}, {"text": "否则", "is_correct": true, "explanation": "“否则”引出“不这样就会”的后果，与“快点儿吃”和“饭就凉了”的关系相符。"}, {"text": "还是", "is_correct": false, "explanation": "搭配：“还是”表示选择，“快点儿吃”与“饭凉”之间不构成选择关系。"}], "explanations": {"所以": "语义：“所以”表示因果，“快点儿吃”与“饭就凉了”之间不构成因果关系。", "但是": "语义：“但是”表示转折，与“快点儿吃”的要求及后果的关系不符。", "否则": "“否则”引出“不这样就会”的后果，与“快点儿吃”和“饭就凉了”的关系相符。", "还是": "搭配：“还是”表示选择，“快点儿吃”与“饭凉”之间不构成选择关系。"}, "sentence_index": 0, "correct_answer": "否则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很累，否则想睡觉。", "explanation": "这里应该用〈所以〉。否则只引出与前文相反的假设后果，不能引出顺理成章的结果。"}, {"text": "他不是老师，否则是医生。", "explanation": "这里应该用〈而是〉。否则不能用于否定后的正面对比。"}, {"text": "他很友好，否则很幽默。", "explanation": "这里应该用〈并且〉。否则不表示并列的两个性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，“不能考试”不能作为“必须交作业”的原因。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，与“必须交作业”的要求不符。"}, {"text": "否则", "is_correct": true, "explanation": "“否则”引出“不这样就会”的后果，与“必须交作业”和“不能考试”的关系相符。"}, {"text": "例如", "is_correct": false, "explanation": "语义：“例如”引出举例，与前面的要求之间没有举例关系。"}], "explanations": {"因为": "搭配：“因为”要引出原因，“不能考试”不能作为“必须交作业”的原因。", "幸好": "语义：“幸好”表示庆幸，与“必须交作业”的要求不符。", "否则": "“否则”引出“不这样就会”的后果，与“必须交作业”和“不能考试”的关系相符。", "例如": "语义：“例如”引出举例，与前面的要求之间没有举例关系。"}, "sentence_index": 6, "correct_answer": "否则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我洗完澡，否则睡觉了。", "explanation": "这里应该用〈然后〉。否则表示“不这样就会”，不能表示动作的先后顺序。"}, {"text": "他喜欢唱歌，否则喜欢跳舞。", "explanation": "这里应该用〈另外〉。否则不能表示在已有爱好之外再增加一项。"}, {"text": "她在看书，否则在听音乐。", "explanation": "这里应该用〈同时〉。否则只引出假设性的另一种结果，不能表示两件事同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你要快点写，否则了作业写不完。", "corrected_sentence": "你要快点写，否则作业写不完。", "error_description": "错误：“否则”后面加了“了”。正确：“否则”后面不带“了”，应为“否则作业写不完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要早点起床，否则否则赶不上车。", "corrected_sentence": "你要早点起床，否则赶不上车。", "error_description": "错误：“否则否则”重复了连词。正确：“否则”只用一次，放在后一分句句首引出结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
