INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "涉及或由多个国家组成的。", "primary_collocate": null, "pronunciation": "duō guó", "ipa": "tuo˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "这家多国合资企业在十个国家都有工厂。", "target_word": "多国", "complexity_tier": "T3", "furigana": "duō guó", "sentence_source": "generated"}, {"text": "多国会议下个星期在北京开。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个国家签了一份多国协议。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部多国合拍的电影。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多国合作让这个研究很快做完了。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察和多国调查组一起查这件事。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多国项目需要很多钱和时间。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条多国铁路把五个国家连在了一起。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们参加了一次多国考察，去了三个国家。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多国基金由六个国家一起出钱。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多國", "label": "繁体"}, {"form": "多国公司", "label": "复合"}, {"form": "多国会议", "label": "复合"}], "register": "书面语", "sense_fingerprint": "涉及多个国家或由多国组成的机构、事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3325f6b1-73dc-4a1c-9d96-b519a163574c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE