INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多国", "is_correct": true, "explanation": "多国（duō guó）指涉及或由多个国家组成，是本题的正确答案。"}, {"text": "躲过", "is_correct": false, "explanation": "躲过（duǒ guò）与多国（duō guó）两个音节的声调都不同，意思是避开。"}, {"text": "夺过", "is_correct": false, "explanation": "夺过（duó guò）与多国（duō guó）两个音节的声调都不同，意思是抢过来。"}, {"text": "剁过", "is_correct": false, "explanation": "剁过（duò guò）与多国（duō guó）两个音节的声调都不同，意思是用刀切过。"}], "explanations": {"多国": "多国（duō guó）指涉及或由多个国家组成，是本题的正确答案。", "躲过": "躲过（duǒ guò）与多国（duō guó）两个音节的声调都不同，意思是避开。", "夺过": "夺过（duó guò）与多国（duō guó）两个音节的声调都不同，意思是抢过来。", "剁过": "剁过（duò guò）与多国（duō guó）两个音节的声调都不同，意思是用刀切过。"}, "sentence_index": null, "correct_answer": "多国"}, "level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "“这家多国合资企业”指由多个国家共同投资的企业，与“十个国家都有工厂”相符。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指一个地方，与“在十个国家都有工厂”相矛盾。"}, {"text": "手工", "is_correct": false, "explanation": "搭配：“手工”修饰企业不合搭配，“手工”多用于手工业或手工制品。"}, {"text": "红色", "is_correct": false, "explanation": "体貌：“红色”描述颜色，不能修饰企业的性质。"}], "explanations": {"多国": "“这家多国合资企业”指由多个国家共同投资的企业，与“十个国家都有工厂”相符。", "本地": "语义：“本地”指一个地方，与“在十个国家都有工厂”相矛盾。", "手工": "搭配：“手工”修饰企业不合搭配，“手工”多用于手工业或手工制品。", "红色": "体貌：“红色”描述颜色，不能修饰企业的性质。"}, "sentence_index": 0, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一家多国工厂，由北京市政府单独投资。", "explanation": "这里应该用〈市属〉。由一个城市政府单独投资的企业要说市属，多国指多个国家共同参与的机构。"}, {"text": "这是我多国的事情，与别人无关。", "explanation": "这里应该用〈个人〉。只涉及一个人的事情要说个人，多国用于涉及多个国家的事务。"}, {"text": "这是一项多国政策，只在本省有效。", "explanation": "这里应该用〈地方〉。只在本省有效的政策属于地方政策，多国政策涉及多个国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.mo