INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "“这个多国项目”指涉及多个国家的项目，符合语境。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“免费”与“需要很多钱”相矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能修饰项目。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指没有内容，与“需要很多钱和时间”不符。"}], "explanations": {"多国": "“这个多国项目”指涉及多个国家的项目，符合语境。", "免费": "语义：“免费”与“需要很多钱”相矛盾。", "瘦": "体貌：“瘦”形容人或动物的身材，不能修饰项目。", "空": "语义：“空”指没有内容，与“需要很多钱和时间”不符。"}, "sentence_index": 6, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个多国项目，只由中国一个国家出资。", "explanation": "这里应该用〈国内〉。只由一个国家出资的项目属于国内，多国项目需要多个国家共同参与。"}, {"text": "这是一场多国比赛，只有中国的队伍参加。", "explanation": "这里应该用〈全国〉。只有中国队伍参加的比赛属于全国性比赛，多国比赛需要多个国家的队伍参加。"}, {"text": "这是一个多国协会，会员全都是中国人。", "explanation": "这里应该用〈本国〉。会员全都是中国人的协会属于本国，多国协会由多个国家的人组成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次合作是多国。", "corrected_sentence": "这次合作是多国的。", "error_description": "“是多国”作谓语应带结构助词“的”，应说“这次合作是多国的”，学习者常漏掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项很多国合作由三个国家一起完成。", "corrected_sentence": "这项多国合作由三个国家一起完成。", "error_description": "错误：“很多国合作”。正确：“多国合作”。“多国”是非等级形容词，不能被副词“很”修饰，应删去“很”，直接作定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
