INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "星期,七天的时间。", "primary_collocate": null, "pronunciation": "zhōu", "ipa": "ʈʂoʊ˥", "syllable_count": 1, "sentences": [{"text": "我在这家公司工作了三周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了两周,现在好了。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看了一周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步,已经跑了三周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你等我一周,好吗?", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去海边玩了一周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药要吃两周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一周,他才回来。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学做饭学了四周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行只有一周的时间。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "週", "label": "繁体"}, {"form": "一周", "label": "复合"}], "register": "中性", "sense_fingerprint": "连续七天的一段时间,用来计算时长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "周", "is_correct": true, "explanation": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。"}, {"text": "抽", "is_correct": false, "explanation": "chōu 与 zhōu 只有声母不同（zh/ch），chōu 是抽烟、抽时间的意思。"}, {"text": "收", "is_correct": false, "explanation": "shōu 与 zhōu 只有声母不同（zh/sh），shōu 是收起、收获的意思。"}, {"text": "咒", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，咒是咒语、诅咒的意思。"}], "explanations": {"周": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。", "抽": "chōu 与 zhōu 只有声母不同（zh/ch），chōu 是抽烟、抽时间的意思。", "收": "shōu 与 zhōu 只有声母不同（zh/sh），shōu 是收起、收获的意思。", "咒": "zhòu（第四声）与 zhōu（第一声）声调不同，咒是咒语、诅咒的意思。"}, "sentence_index": null, "correct_answer": "周"}, "level_3": {"options": [{"text": "周", "is_correct": true, "explanation": "正确：「三周」表示三个星期的时段，与「工作了」的时长相符。"}, {"text": "顿", "is_correct": false, "explanation": "语义：「顿」用于饭食或训斥，「工作了三顿」不能表示时长。"}, {"text": "节", "is_correct": false, "explanation": "搭配：「节」多与「课」等搭配，「工作了三节」不能表示时长。"}, {"text": "人", "is_correct": false, "explanation": "搭配：「工作了三人」说的是人数，不是时长，与「工作了」不搭配。"}], "explanations": {"周": "正确：「三周」表示三个星期的时段，与「工作了」的时长相符。", "顿": "语义：「顿」用于饭食或训斥，「工作了三顿」不能表示时长。", "节": "搭配：「节」多与「课」等搭配，「工作了三节」不能表示时长。", "人": "搭配：「工作了三人」说的是人数，不是时长，与「工作了」不搭配。"}, "sentence_index": 0, "correct_answer": "周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天是三周。", "explanation": "这里应该用〈星期三〉。「三周」指三个星期的时长，说今天是哪一天要用「星期三」。"}, {"text": "我们班买了三周粉笔。", "explanation": "这里应该用〈盒〉。「周」是时间单位，不能作粉笔的量词，称粉笔应说〈盒〉。"}, {"text": "他的安排很周。", "explanation": "这里应该用〈周到〉。「周」不能单独作形容词，形容安排细致应说「周到」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "周", "is_correct": true, "explanation": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。"}, {"text": "昼", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，昼是白天的意思。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，皱是皱纹的意思。"}, {"text": "轴", "is_correct": false, "explanation": "zhóu（第二声）与 zhōu（第一声）声调不同，轴是车轴的意思。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhōu（第一声）声调不同，肘是手肘的意思。"}], "explanations": {"周": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。", "昼": "zhòu（第四声）与 zhōu（第一声）声调不同，昼是白天的意思。", "皱": "zhòu（第四声）与 zhōu（第一声）声调不同，皱是皱纹的意思。", "轴": "zhóu（第二声）与 zhōu（第一声）声调不同，轴是车轴的意思。", "肘": "zhǒu（第三声）与 zhōu（第一声）声调不同，肘是手肘的意思。"}, "sentence_index": null, "correct_answer": "周"}, "level_3": {"options": [{"text": "周", "is_correct": true, "explanation": "正确：「两周」表示两个星期的时段，与「吃药」的时长相符。"}, {"text": "张", "is_correct": false, "explanation": "语义：「张」用于纸、床等扁平物，不能作「吃」的计量，「这个药要吃两张」不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」不能被「吃」，「这个药要吃两桌子」不成立。"}, {"text": "杯", "is_correct": false, "explanation": "搭配：「吃」不与「杯」搭配，「两杯」多用于饮品，与「这个药」不合。"}], "explanations": {"周": "正确：「两周」表示两个星期的时段，与「吃药」的时长相符。", "张": "语义：「张」用于纸、床等扁平物，不能作「吃」的计量，「这个药要吃两张」不成立。", "桌子": "语义：「桌子」不能被「吃」，「这个药要吃两桌子」不成立。", "杯": "搭配：「吃」不与「杯」搭配，「两杯」多用于饮品，与「这个药」不合。"}, "sentence_index": 6, "correct_answer": "周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去过三周这个城市。", "explanation": "这里应该用〈次〉。「周」表示七天的时长，计算去过几次要用〈次〉，不能用「周」。"}, {"text": "这次旅行只有一周小时的时间。", "explanation": "这里应该用〈一个小时〉。「周」表示七天，不能与「小时」这样的小单位搭配。"}, {"text": "他这周十点起床。", "explanation": "这里应该用〈今天〉或〈每天〉。「这周」指一个星期，不能与具体钟点搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹学了三个周钢琴。", "corrected_sentence": "妹妹学了三周钢琴。", "error_description": "量词错误：表示时段的「周」前不加量词「个」，应说「学了三周钢琴」，不说「学了三个周钢琴」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在北京住了的两周。", "corrected_sentence": "我在北京住了两周。", "error_description": "多余的「的」：「住了两周」是动词加时段补语，中间不能插入「的」，应说「住了两周」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
