INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃得又多又快。", "primary_collocate": null, "pronunciation": "dà chī", "ipa": "ta˥˩ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他饿坏了，坐下就大吃起来。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，他在饭桌上大吃了一顿。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天过节，我们可以大吃一顿了。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饿了一天，晚上大吃了两碗面。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家店的烤肉很好，我们想去大吃一顿。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家围着桌子大吃起来。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟看见红烧肉，立刻大吃起来。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥结束了，她高兴地大吃了一顿。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边大吃海鲜。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别大吃了，小心肚子疼。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大吃了", "label": "完成体"}, {"form": "大吃起来", "label": "复合"}, {"form": "大吃一顿", "label": "固定搭配"}], "register": "口语", "sense_fingerprint": "饿了或高兴时吃得又多又快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e262c980-de0c-4b91-944b-cfed1898ea21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大吃", "is_correct": true, "explanation": "正确：“大吃起来”指开始大口吃，与“饿坏了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐下之后不能游泳，与句子的吃饭情境不符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”要求参观的对象作宾语，不能用来描述吃饭的动作。"}, {"text": "绝食", "is_correct": false, "explanation": "语义：“绝食”指不吃饭，与“饿坏了”后马上吃的情况矛盾。"}], "explanations": {"大吃": "正确：“大吃起来”指开始大口吃，与“饿坏了”相符。", "游泳": "语义：坐下之后不能游泳，与句子的吃饭情境不符。", "参观": "搭配：“参观”要求参观的对象作宾语，不能用来描述吃饭的动作。", "绝食": "语义：“绝食”指不吃饭，与“饿坏了”后马上吃的情况矛盾。"}, "sentence_index": 0, "correct_answer": "大吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他渴坏了，一口气大吃了两杯水。", "explanation": "这里应该用〈大喝〉。“吃”用于固体食物，水要用“喝”。"}, {"text": "他慢慢地大吃了一顿。", "explanation": "这里应该用〈细嚼〉。“大吃”指吃得又多又快，与“慢慢地”的细嚼慢咽相反。"}, {"text": "感冒后，他每天大吃三次药。", "explanation": "这里应该用〈服〉。“大吃”指大量吃食物，吃药要用“服”，不能说“大吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大吃", "is_correct": true, "explanation": "正确：“大吃起来”指开始大口吃，与“看见红烧肉”的反应相符。"}, {"text": "逛", "is_correct": false, "explanation": "语义：“逛”指随意走看，与看见红烧肉就吃的情境不符。"}, {"text": "跳伞", "is_correct": false, "explanation": "语义：“跳伞”需要飞机和高空，与看见红烧肉的情境完全不符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：看见红烧肉后应是吃东西，“睡”指睡觉，与情境不符。"}], "explanations": {"大吃": "正确：“大吃起来”指开始大口吃，与“看见红烧肉”的反应相符。", "逛": "语义：“逛”指随意走看，与看见红烧肉就吃的情境不符。", "跳伞": "语义：“跳伞”需要飞机和高空，与看见红烧肉的情境完全不符。", "睡": "语义：看见红烧肉后应是吃东西，“睡”指睡觉，与情境不符。"}, "sentence_index": 6, "correct_answer": "大吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工地上大吃了一顿砖头，累得直不起腰。", "explanation": "这里应该用〈搬〉。“大吃”的对象必须是食物，“砖头”不能吃，应说“搬砖头”。"}, {"text": "他把一支笔大吃了下去。", "explanation": "这里应该用〈吞〉。笔不是食物，“大吃”只用于食物；“吞服”仅用于药物，不能用于笔。"}, {"text": "他在屋里大吃了一包烟，呛得直咳嗽。", "explanation": "这里应该用〈抽〉。“大吃”的对象必须是食物，烟不能吃，应说“抽烟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚饭后，弟弟又大吃过了一碗饭。", "corrected_sentence": "晚饭后，弟弟又大吃了一碗饭。", "error_description": "体标叠用：“大吃”后已有“了”，不能再加“过”，应说“又大吃了一碗饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在饭店大了吃一顿。", "corrected_sentence": "我们在饭店大吃一顿。", "error_description": "词内插入：“大吃”是一个完整的词，“了”不能插在“大”和“吃”之间，应说“大吃一顿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
