INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基金是大家放在一起、要用来做好事或赚钱的钱。", "primary_collocate": null, "pronunciation": "jī jīn", "ipa": "tɕi˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "爸爸买了一些基金,想多赚点钱。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只基金今年赚了不少钱。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把钱放进基金里,一起做好事。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每月买一千元的基金。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买基金以前,要先看清楚。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基金去年赔了钱。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们办了一个小基金,帮助穷孩子。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不懂基金,所以没有买。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说买基金比存钱赚得多。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基金每年都给山区学校捐钱。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "基金会", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家合在一起、用来投资赚钱或做公益的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89237, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基金", "is_correct": true, "explanation": "正确。基金指大家合在一起用来投资或做公益的钱，读作 jī jīn，两个音节都是第一声。"}, {"text": "挤进", "is_correct": false, "explanation": "挤进 jǐ jìn 的两个音节声调都与 jī jīn 不同（第三声、第四声），指用力钻入。"}, {"text": "几近", "is_correct": false, "explanation": "几近 jǐ jìn 与 jī jīn 声调不同，表示接近、差不多。"}, {"text": "七斤", "is_correct": false, "explanation": "七斤 qī jīn 的第一个音节声母是 q，与 jī 的 j 不同，指七斤重量。"}, {"text": "鸡心", "is_correct": false, "explanation": "鸡心 jī xīn 的第二个音节声母是 x，与 jīn 的 j 不同，指心形的吊坠。"}], "explanations": {"基金": "正确。基金指大家合在一起用来投资或做公益的钱，读作 jī jīn，两个音节都是第一声。", "挤进": "挤进 jǐ jìn 的两个音节声调都与 jī jīn 不同（第三声、第四声），指用力钻入。", "几近": "几近 jǐ jìn 与 jī jīn 声调不同，表示接近、差不多。", "七斤": "七斤 qī jīn 的第一个音节声母是 q，与 jī 的 j 不同，指七斤重量。", "鸡心": "鸡心 jī xīn 的第二个音节声母是 x，与 jīn 的 j 不同，指心形的吊坠。"}, "sentence_index": null, "correct_answer": "基金"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是自然界的气体，不是可以买来赚钱的东西，与“赚点钱”不相容。"}, {"text": "基金", "is_correct": true, "explanation": "正确。“买了一些基金”指买入基金用来投资，与“想多赚点钱”搭配。"}, {"text": "广场", "is_correct": false, "explanation": "语义：广场是公共场所，不能买卖，无法用来赚钱。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“买”不与“阳光”搭配，阳光不能用钱买。"}], "explanations": {"空气": "语义：空气是自然界的气体，不是可以买来赚钱的东西，与“赚点钱”不相容。", "基金": "正确。“买了一些基金”指买入基金用来投资，与“想多赚点钱”搭配。", "广场": "语义：广场是公共场所，不能买卖，无法用来赚钱。", "阳光": "搭配：“买”不与“阳光”搭配，阳光不能用钱买。"}, "sentence_index": 0, "correct_answer": "基金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每个月都把工资存进银行，攒成了一笔基金。", "explanation": "这里应该用〈存款〉。存进银行、个人积攒的钱叫存款；基金是大家合在一起投资的钱，不是个人存款。"}, {"text": "她向朋友借了一笔基金，准备买房。", "explanation": "这里应该用〈借款〉。向别人借来的钱叫借款；基金是大家合在一起投资或做公益的钱，不能说“借了一笔基金”。"}, {"text": "她每月买一座基金，希望能赚些钱。", "explanation": "这里应该用〈只〉。投资用的基金口语里常说“一只基金”；“座”用于山、桥、建筑等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89237, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基金", "is_correct": true, "explanation": "正确。基金指大家合在一起用来投资或做公益的钱，读作 jī jīn，两个音节都是第一声。"}, {"text": "鸡精", "is_correct": false, "explanation": "鸡精 jī jīng 的第二个音节韵母是 -ng，与 jīn 的 -n 不同，指一种调味料。"}, {"text": "激进", "is_correct": false, "explanation": "激进 jī jìn 的第二个音节是第四声，与 jīn（第一声）声调不同，指思想或行动过激。"}, {"text": "急进", "is_correct": false, "explanation": "急进 jí jìn 与 jī jīn 声调不同，指急于求成、要求过快。"}, {"text": "几斤", "is_correct": false, "explanation": "几斤 jǐ jīn 的第一个音节是第三声，与 jī（第一声）声调不同，是问重量的说法。"}], "explanations": {"基金": "正确。基金指大家合在一起用来投资或做公益的钱，读作 jī jīn，两个音节都是第一声。", "鸡精": "鸡精 jī jīng 的第二个音节韵母是 -ng，与 jīn 的 -n 不同，指一种调味料。", "激进": "激进 jī jìn 的第二个音节是第四声，与 jīn（第一声）声调不同，指思想或行动过激。", "急进": "急进 jí jìn 与 jī jīn 声调不同，指急于求成、要求过快。", "几斤": "几斤 jǐ jīn 的第一个音节是第三声，与 jī（第一声）声调不同，是问重量的说法。"}, "sentence_index": null, "correct_answer": "基金"}, "level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然的大水域，不能被“办”成用来帮助孩子的项目。"}, {"text": "基金", "is_correct": true, "explanation": "正确。“办一个小基金”指朋友们集资设立的小型专项资金，用来帮助穷孩子。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是贬义的口语词，用在“办一个小……帮助穷孩子”这样郑重的慈善语境中很不得体。"}, {"text": "螃蟹", "is_correct": false, "explanation": "语义：螃蟹是动物，不能被“办”成一个用来帮助孩子的项目。"}], "explanations": {"海洋": "语义：海洋是自然的大水域，不能被“办”成用来帮助孩子的项目。", "基金": "正确。“办一个小基金”指朋友们集资设立的小型专项资金，用来帮助穷孩子。", "垃圾": "语域：“垃圾”是贬义的口语词，用在“办一个小……帮助穷孩子”这样郑重的慈善语境中很不得体。", "螃蟹": "语义：螃蟹是动物，不能被“办”成一个用来帮助孩子的项目。"}, "sentence_index": 6, "correct_answer": "基金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的基金链断了，只好裁员。", "explanation": "这里应该用〈资金〉。公司周转用的钱叫资金，“资金链”是固定说法；基金是大家合在一起投资或做公益的钱，不能说“基金链”。"}, {"text": "大家凑了一幅基金，一起投资赚钱。", "explanation": "这里应该用〈笔〉。基金作为款项要用“笔”计量，“幅”用于画、布等平面的东西。"}, {"text": "他上班迟到，被老板罚了一笔基金。", "explanation": "这里应该用〈罚款〉。因违规而交付的钱叫罚款；基金是大家合在一起投资或做公益的钱，不能用来罚人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把一部分工资投进了一座基金。", "corrected_sentence": "她把一部分工资投进了一笔基金。", "error_description": "量词错误：投资的基金是一笔款项，应该说“一笔基金”（口语里也可说“一只基金”）；“座”用于山、桥、建筑等大型物体，不能修饰“基金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅基金去年赔了不少钱。", "corrected_sentence": "这笔基金去年赔了不少钱。", "error_description": "量词错误：“基金”是一笔款项，应该说“这笔基金”；“幅”用于画、布等平面的东西，不能修饰“基金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
