INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为某种目的而设立的专门资金。", "primary_collocate": null, "pronunciation": "jī jīn", "ipa": "tɕi˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "学校设立了一个教育基金。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔基金专门用来帮助生病的孩子。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司成立了一个科学研究基金。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府用这笔基金修了一座桥。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给学校的助学基金捐了钱。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基金是为老人设立的。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家为农民建立了一个新基金。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请这个基金的人很多。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基金的钱只能用在读书上。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用基金的钱完成了研究。", "target_word": "基金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "基金会", "label": "复合"}], "register": "中性", "sense_fingerprint": "为教育、科研、救助等目的设立的专项资金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89238, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基金", "is_correct": true, "explanation": "正确。基金指为某种目的设立的专门资金，读作 jī jīn，两个音节都是第一声。"}, {"text": "鸡精", "is_correct": false, "explanation": "鸡精 jī jīng 的第二个音节韵母是 -ng，与 jīn 的 -n 不同，指一种调味料。"}, {"text": "激进", "is_correct": false, "explanation": "激进 jī jìn 的第二个音节是第四声，与 jīn（第一声）声调不同，指思想或行动过激。"}, {"text": "几斤", "is_correct": false, "explanation": "几斤 jǐ jīn 的第一个音节是第三声，与 jī（第一声）声调不同，是问重量的说法。"}, {"text": "七斤", "is_correct": false, "explanation": "七斤 qī jīn 的第一个音节声母是 q，与 jī 的 j 不同，指七斤重量。"}], "explanations": {"基金": "正确。基金指为某种目的设立的专门资金，读作 jī jīn，两个音节都是第一声。", "鸡精": "鸡精 jī jīng 的第二个音节韵母是 -ng，与 jīn 的 -n 不同，指一种调味料。", "激进": "激进 jī jìn 的第二个音节是第四声，与 jīn（第一声）声调不同，指思想或行动过激。", "几斤": "几斤 jǐ jīn 的第一个音节是第三声，与 jī（第一声）声调不同，是问重量的说法。", "七斤": "七斤 qī jīn 的第一个音节声母是 q，与 jī 的 j 不同，指七斤重量。"}, "sentence_index": null, "correct_answer": "基金"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“设立”的对象是机构或资金，桌子是具体物件，不能被设立为“教育”的事物。"}, {"text": "基金", "is_correct": true, "explanation": "正确。“设立一个教育基金”指为教育目的设立专门资金，与“学校”“教育”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“设立”不与“天气”搭配，“教育天气”也不成词。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“设立”不能用于人，老师是人，不能被设立为一个教育对象。"}], "explanations": {"桌子": "语义：“设立”的对象是机构或资金，桌子是具体物件，不能被设立为“教育”的事物。", "基金": "正确。“设立一个教育基金”指为教育目的设立专门资金，与“学校”“教育”搭配。", "天气": "搭配：“设立”不与“天气”搭配，“教育天气”也不成词。", "老师": "语义：“设立”不能用于人，老师是人，不能被设立为一个教育对象。"}, "sentence_index": 0, "correct_answer": "基金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天下班后，把工资存进银行，攒成了一笔基金。", "explanation": "这里应该用〈存款〉。存进银行、个人积攒的钱叫存款；基金是为某种目的设立的专门资金，不是个人存款。"}, {"text": "他超速被交警罚了一笔基金。", "explanation": "这里应该用〈罚款〉。因违法被交给政府的钱叫罚款；基金是为某种目的设立的专门资金，不能用来处罚。"}, {"text": "学校收到了一座基金，用来资助贫困的学生。", "explanation": "这里应该用〈笔〉。基金作为一笔款项要用“笔”计量，“座”用于山、桥、建筑等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89238, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基金", "is_correct": true, "explanation": "正确。基金指为某种目的设立的专门资金，读作 jī jīn，两个音节都是第一声。"}, {"text": "挤进", "is_correct": false, "explanation": "挤进 jǐ jìn 的两个音节声调都与 jī jīn 不同（第三声、第四声），指用力钻入。"}, {"text": "几近", "is_correct": false, "explanation": "几近 jǐ jìn 与 jī jīn 声调不同，表示接近、差不多。"}, {"text": "急进", "is_correct": false, "explanation": "急进 jí jìn 与 jī jīn 声调不同，指急于求成、要求过快。"}, {"text": "鸡心", "is_correct": false, "explanation": "鸡心 jī xīn 的第二个音节声母是 x，与 jīn 的 j 不同，指心形的吊坠。"}], "explanations": {"基金": "正确。基金指为某种目的设立的专门资金，读作 jī jīn，两个音节都是第一声。", "挤进": "挤进 jǐ jìn 的两个音节声调都与 jī jīn 不同（第三声、第四声），指用力钻入。", "几近": "几近 jǐ jìn 与 jī jīn 声调不同，表示接近、差不多。", "急进": "急进 jí jìn 与 jī jīn 声调不同，指急于求成、要求过快。", "鸡心": "鸡心 jī xīn 的第二个音节声母是 x，与 jīn 的 j 不同，指心形的吊坠。"}, "sentence_index": null, "correct_answer": "基金"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“建立”用于机构、制度或资金，学生是人，不能被建立。"}, {"text": "基金", "is_correct": true, "explanation": "正确。“建立一个新基金”指为农民设立专门资金，与“国家”“为农民”搭配。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“建立”不与“早餐”搭配，不说“建立早餐”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是具体的交通工具，不能被“建立”为面向农民的项目。"}], "explanations": {"学生": "语义：“建立”用于机构、制度或资金，学生是人，不能被建立。", "基金": "正确。“建立一个新基金”指为农民设立专门资金，与“国家”“为农民”搭配。", "早餐": "搭配：“建立”不与“早餐”搭配，不说“建立早餐”。", "汽车": "语义：汽车是具体的交通工具，不能被“建立”为面向农民的项目。"}, "sentence_index": 6, "correct_answer": "基金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不小心打碎了邻居家的窗户，只好赔了一笔基金。", "explanation": "这里应该用〈赔款〉。因损坏他人财物而付出的钱叫赔款；基金是为某种目的设立的专门资金，不能用来赔偿。"}, {"text": "大家凑了一幅基金，一起帮助山区的孩子。", "explanation": "这里应该用〈笔〉。基金作为款项要用“笔”计量，“幅”用于画、布等平面的东西。"}, {"text": "这家公司的基金链断了，只好裁员。", "explanation": "这里应该用〈资金〉。公司周转用的钱叫资金，“资金链”是固定说法；基金是为某种目的专门设立的款项，不能说“基金链”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座基金是为了救助灾区的学生设立的。", "corrected_sentence": "这笔基金是为了救助灾区的学生设立的。", "error_description": "量词错误：“基金”是一笔款项，应该说“这笔基金”；“座”用于山、桥、建筑等大型物体，不能修饰“基金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅基金用来资助科学研究。", "corrected_sentence": "这笔基金用来资助科学研究。", "error_description": "量词错误：“基金”是一笔款项，应该说“这笔基金”；“幅”用于画、布等平面的东西，不能修饰“基金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
