INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学者是学问很深,一直研究知识的人。", "primary_collocate": null, "pronunciation": "xué zhě", "ipa": "ɕɥe˧˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位学者一生都在读书和研究。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老学者每天早上都去图书馆。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很有学问的学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位学者知道很多古代的故事。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者说,读书要多想。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者家里有一万多本书。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想长大以后做一名学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人常常去请教那位老学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者八十岁了,还在看书写字。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者的房间里放满了书。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學者", "label": "繁体"}, {"form": "学者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "学问很深、长期读书研究的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学者", "is_correct": true, "explanation": "正确：「学者」指学问深、一直读书研究的人，与「一生都在读书和研究」相符。"}, {"text": "工人", "is_correct": false, "explanation": "语义：工人以体力劳动为主，句子说的是一生读书研究，与「工人」不合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，与「读书和研究」不相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机以驾驶为业，与「读书和研究」不相符。"}], "explanations": {"学者": "正确：「学者」指学问深、一直读书研究的人，与「一生都在读书和研究」相符。", "工人": "语义：工人以体力劳动为主，句子说的是一生读书研究，与「工人」不合。", "厨师": "语义：厨师的工作是做饭，与「读书和研究」不相符。", "司机": "语义：司机以驾驶为业，与「读书和研究」不相符。"}, "sentence_index": 0, "correct_answer": "学者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位学者是刚入学的新生。", "explanation": "这里应该用〈学生〉。「学者」指学问深、长期研究的人，刚入学的新生应称「学生」。"}, {"text": "这位学者在医院给病人看病。", "explanation": "这里应该用〈医生〉。「学者」指学问深的人，不指给病人看病的医生。"}, {"text": "那位学者在工厂里开机器。", "explanation": "这里应该用〈工人〉。「学者」指学问深的人，在工厂开机器的是工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学者", "is_correct": true, "explanation": "正确：「做一名学者」指以研究学问为职业，与「长大以后」的志向相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：「老人」是年龄状态，「长大以后」要做的不是「老人」这种身份。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：「婴儿」与「长大以后」的语义相反，不能作职业的对象。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：「做一名学生」不常说，「学生」是身份而非职业，与「做一名」不搭配。"}], "explanations": {"学者": "正确：「做一名学者」指以研究学问为职业，与「长大以后」的志向相符。", "老人": "语义：「老人」是年龄状态，「长大以后」要做的不是「老人」这种身份。", "婴儿": "语义：「婴儿」与「长大以后」的语义相反，不能作职业的对象。", "学生": "搭配：「做一名学生」不常说，「学生」是身份而非职业，与「做一名」不搭配。"}, "sentence_index": 6, "correct_answer": "学者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位学者在饭馆里端盘子。", "explanation": "这里应该用〈服务员〉。「学者」指学问深的人，在饭馆端盘子的是服务员。"}, {"text": "这位学者每天给病人打针。", "explanation": "这里应该用〈护士〉。「学者」指学问深的人，给病人打针的是护士。"}, {"text": "这位学者每天开车送客人。", "explanation": "这里应该用〈司机〉。「学者」指学问深的人，开车送客人的是司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只学者每天在书房里写文章。", "corrected_sentence": "那位学者每天在书房里写文章。", "error_description": "量词错误：指人的「学者」应用量词「位」，不能用「只」，应说「那位学者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
