INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学术上有专门研究、有成就的人。", "primary_collocate": null, "pronunciation": "xué zhě", "ipa": "ɕɥe˧˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是研究历史的著名学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者在经济方面很有成就。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多学者来参加这次会议。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者写了十本关于语言的书。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们正在讨论新的研究结果。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位有名的法律学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外的学者来我们大学做报告。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者得到了很多奖。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位学者研究中国文学三十年了。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位学者对这个问题的看法不同。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學者", "label": "繁体"}, {"form": "学者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "在某个学术领域有专门研究和成就的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76ec1b6f-74b6-4677-8d0b-c921f1e066ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学者", "is_correct": true, "explanation": "正确：「学者」指在某个学术领域有专门研究和成就的人，与「研究历史的著名」相符。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的工作是唱歌，与「研究历史」不相符。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员以表演为业，与「研究历史」的专业不符。"}, {"text": "建筑", "is_correct": false, "explanation": "搭配：「他是……建筑」不成立，「建筑」指物，不指人。"}], "explanations": {"学者": "正确：「学者」指在某个学术领域有专门研究和成就的人，与「研究历史的著名」相符。", "歌手": "语义：歌手的工作是唱歌，与「研究历史」不相符。", "演员": "语义：演员以表演为业，与「研究历史」的专业不符。", "建筑": "搭配：「他是……建筑」不成立，「建筑」指物，不指人。"}, "sentence_index": 0, "correct_answer": "学者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位学者给十个病人看病。", "explanation": "这里应该用〈医生〉。「学者」指学术上有研究成就的人，给病人看病的是医生。"}, {"text": "这位学者做了十道拿手菜。", "explanation": "这里应该用〈厨师〉。「学者」指学术研究者，做拿手菜的是厨师。"}, {"text": "这位学者在菜市场卖水果。", "explanation": "这里应该用〈小贩〉。「学者」指学术上有成就的人，在菜市场卖水果的是小贩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学者", "is_correct": true, "explanation": "正确：「国外的学者来大学做报告」，「学者」是在学术上有成就的人，与句意相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：「游客」一般不做学术报告，与「来大学做报告」的句意不合。"}, {"text": "司机", "is_correct": false, "explanation": "语义：「司机」的职责是驾驶，与「做报告」的语境不合。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：「做报告」的人应是讲者，「厨师」与「做报告」搭配不当。"}], "explanations": {"学者": "正确：「国外的学者来大学做报告」，「学者」是在学术上有成就的人，与句意相符。", "游客": "语义：「游客」一般不做学术报告，与「来大学做报告」的句意不合。", "司机": "语义：「司机」的职责是驾驶，与「做报告」的语境不合。", "厨师": "搭配：「做报告」的人应是讲者，「厨师」与「做报告」搭配不当。"}, "sentence_index": 6, "correct_answer": "学者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位学者抓到了那个小偷。", "explanation": "这里应该用〈警察〉。「学者」指学术研究者，抓捕小偷的是警察。"}, {"text": "这位学者在银行里数钱。", "explanation": "这里应该用〈出纳〉。「学者」指学术研究者，在银行数钱的是出纳。"}, {"text": "这位学者在机场帮游客拿行李。", "explanation": "这里应该用〈搬运工〉。「学者」指学术研究者，帮游客拿行李的是搬运工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只研究哲学的知名学者。", "corrected_sentence": "她是一位研究哲学的知名学者。", "error_description": "量词错误：「学者」指人，应用量词「位」，不能用「只」，应说「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座学者很受大家尊敬。", "corrected_sentence": "那位学者很受大家尊敬。", "error_description": "量词错误：「学者」指人，应用量词「位」，「座」用于山、楼、桥等大型物体，应说「那位学者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae74548d-df6b-4f71-850a-6e367d625b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
