INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把声音或画面留下来，以后还能听或看。", "primary_collocate": null, "pronunciation": "lù", "ipa": "lu˥˩", "syllable_count": 1, "sentences": [{"text": "我用手机录了一段视频。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课时，我用手机把声音录下来了。", "target_word": "录", "complexity_tier": "T3", "furigana": "lǎo shī jiǎng kè shí, wǒ yòng shǒu jī bǎ shēng yīn lù xià lái le。", "sentence_source": "generated"}, {"text": "你能帮我把这首歌录下来吗？", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上在家录节目。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的比赛我没看，朋友帮我录了。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子唱歌的样子太可爱了，我马上录了下来。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想录孩子第一次说话的声音。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别说话，我正在录。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在教室里录一个英语节目。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把爷爷讲的故事录下来。", "target_word": "录", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "录了", "label": "完成体"}, {"form": "录过", "label": "经历体"}, {"form": "录下来", "label": "复合"}], "register": "通用", "sense_fingerprint": "用手机或机器把声音、画面留下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e262c980-de0c-4b91-944b-cfed1898ea21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89249, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "录", "is_correct": true, "explanation": "lù（第四声）：把声音或画面留下来，以后还能听或看。"}, {"text": "绿", "is_correct": false, "explanation": "lǜ 与 lù 的韵母不同（ü 与 u），意思是绿色。"}, {"text": "炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 lù 声母不同（n 与 l），意思是愤怒。"}, {"text": "鲁", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁国或粗鲁。"}], "explanations": {"录": "lù（第四声）：把声音或画面留下来，以后还能听或看。", "绿": "lǜ 与 lù 的韵母不同（ü 与 u），意思是绿色。", "炉": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。", "怒": "nù 与 lù 声母不同（n 与 l），意思是愤怒。", "鲁": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁国或粗鲁。"}, "sentence_index": null, "correct_answer": "录"}, "level_3": {"options": [{"text": "录", "is_correct": true, "explanation": "录：把视频记录下来，与“用手机”“一段视频”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”要求唱出歌曲，不能说唱视频。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，视频不能煮。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”常用于照片、衣物，不能说“洗了一段视频”。"}], "explanations": {"录": "录：把视频记录下来，与“用手机”“一段视频”相符。", "唱": "语义：“唱”要求唱出歌曲，不能说唱视频。", "煮": "语义：“煮”的对象是食物，视频不能煮。", "洗": "搭配：“洗”常用于照片、衣物，不能说“洗了一段视频”。"}, "sentence_index": 0, "correct_answer": "录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手机录了一张照片。", "explanation": "这里应该用〈拍〉。录指保存声音或影像，拍照片要用拍。"}, {"text": "书店里录了很多书。", "explanation": "这里应该用〈印〉。录指记录声音或影像，印书要用印。"}, {"text": "他把窗户录开了。", "explanation": "这里应该用〈打〉。录用于声音、影像，开窗要用打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89249, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "录", "is_correct": true, "explanation": "lù（第四声）：把声音或画面留下来，以后还能听或看。"}, {"text": "律", "is_correct": false, "explanation": "lǜ 与 lù 的韵母不同（ü 与 u），意思是法律或规律。"}, {"text": "滤", "is_correct": false, "explanation": "lǜ 与 lù 的韵母不同（ü 与 u），意思是过滤。"}, {"text": "芦", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。"}, {"text": "卤", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是卤水。"}], "explanations": {"录": "lù（第四声）：把声音或画面留下来，以后还能听或看。", "律": "lǜ 与 lù 的韵母不同（ü 与 u），意思是法律或规律。", "滤": "lǜ 与 lù 的韵母不同（ü 与 u），意思是过滤。", "芦": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。", "卤": "lǔ（第三声）与 lù（第四声）声调不同，意思是卤水。"}, "sentence_index": null, "correct_answer": "录"}, "level_3": {"options": [{"text": "录", "is_correct": true, "explanation": "录：把声音留下来，与“想……孩子说话的声音”相符。"}, {"text": "尝", "is_correct": false, "explanation": "语义：“尝”指品尝味道，声音不能尝。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅，声音不能闻。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱”的对象是人或物体，声音不能抱。"}], "explanations": {"录": "录：把声音留下来，与“想……孩子说话的声音”相符。", "尝": "语义：“尝”指品尝味道，声音不能尝。", "闻": "语义：“闻”指用鼻子嗅，声音不能闻。", "抱": "搭配：“抱”的对象是人或物体，声音不能抱。"}, "sentence_index": 6, "correct_answer": "录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用铅笔录了一幅画。", "explanation": "这里应该用〈绘〉。录用于声音、影像，用铅笔描绘图形要用绘。"}, {"text": "他的字录得很漂亮。", "explanation": "这里应该用〈写〉。录用于声音、影像，写字要用写。"}, {"text": "他一口气录完了一碗饭。", "explanation": "这里应该用〈吃〉。录用于声音、影像，吃饭要用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手机把一段声音录下了来。", "corrected_sentence": "他用手机把一段声音录下来了。", "error_description": "补语“下来”被拆开。“了”应放在句末，应说“录下来了”，不能说“录下了来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想这段对话录下来。", "corrected_sentence": "他想把这段对话录下来。", "error_description": "把字句漏掉“把”。“录下来”的宾语“这段对话”前要用“把”引出，应说“他想把这段对话录下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
