INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从那个时候开始，一直到后来。", "primary_collocate": null, "pronunciation": "cóng cǐ", "ipa": "tsʰʊŋ˧˥ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他搬到了北京，从此很少回家。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次生病以后，她从此不再吃肉。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明学会了游泳，从此天天去河边。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在车站见了面，从此成了好朋友。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机丢了，从此再也不乱放东西。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学毕业后，他从此离开了家乡。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她得了奖，从此更努力地学习。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师笑了笑，从此没有再提这件事。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一只小狗，从此每天都很开心。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天以后，两个人从此没有再见面。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從此", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从过去某个时间点起一直持续到后来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e97b369-c5b3-4f14-9e9f-6e44fef3be27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从此", "is_correct": true, "explanation": "正确。“从此”表示搬家之后起持续下来的情况，与“很少回家”相合。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常”指反复发生，与“很少回家”矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”强调瞬间发生，与“很少回家”这种长期状态不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰程度，与“很少”的程度叠加，句子不通。"}], "explanations": {"从此": "正确。“从此”表示搬家之后起持续下来的情况，与“很少回家”相合。", "经常": "语义：“经常”指反复发生，与“很少回家”矛盾。", "立刻": "语义：“立刻”强调瞬间发生，与“很少回家”这种长期状态不合。", "非常": "搭配：“非常”修饰程度，与“很少”的程度叠加，句子不通。"}, "sentence_index": 0, "correct_answer": "从此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去了超市，从此买了一瓶水。", "explanation": "“从此”指从某时起持续下去的变化，用于一次性的动作不自然；这里应该用〈然后〉表示动作的先后。"}, {"text": "明天我们从此要去北京出差。", "explanation": "“从此”需承接已发生的事件，与“明天”这一未来时间冲突；应去掉“从此”。"}, {"text": "从此到学校只要五分钟。", "explanation": "“从此”只指时间，不指地点，不能表示“从这里”，这里应该用〈从这里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从此", "is_correct": true, "explanation": "正确。“从此”表示得奖之后起一直更努力，与前句相合。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“随便”不能修饰“更努力地学习”，句子不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“更努力地学习”的持续状态矛盾。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期如此，与“得了奖”引出的变化不合。"}], "explanations": {"从此": "正确。“从此”表示得奖之后起一直更努力，与前句相合。", "随便": "搭配：“随便”不能修饰“更努力地学习”，句子不通。", "偶尔": "语义：“偶尔”表示不常发生，与“更努力地学习”的持续状态矛盾。", "一向": "语义：“一向”表示长期如此，与“得了奖”引出的变化不合。"}, "sentence_index": 6, "correct_answer": "从此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行很累，从此我想睡觉。", "explanation": "“从此”只表示时间上的延续，不表示因果，这里应该用〈因此〉。"}, {"text": "这本书很厚，我从此读了三天。", "explanation": "“从此”指从那时起持续下去的变化，不表示时间的长短；这里应该用〈整整〉来强调时间长。"}, {"text": "他洗完澡，从此穿上了衣服。", "explanation": "“从此”表示时间的延续，不表示动作的先后顺序；这里应该用〈接着〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年结了婚，从此的再也没回过老家。", "corrected_sentence": "他去年结了婚，从此再也没回过老家。", "error_description": "错误：副词“从此”后多加了“的”，写成“从此的再也”。副词不带“的”，应去掉，说“从此再也没回过老家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次比赛以后，他从此从此不再迟到了。", "corrected_sentence": "那次比赛以后，他从此不再迟到了。", "error_description": "错误：“从此”重复出现。只需一个“从此”，应说“他从此不再迟到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '231fc583-55f8-4858-9c7c-4728624d1dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
