INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "春节前后的一段时间;年底。", "primary_collocate": null, "pronunciation": "nián xià", "ipa": "niɛn˧˥ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "年下工作很忙，我常常加班。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年下天气冷，大家都穿厚衣服。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年下车票很难买，要早点儿订。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年下商店里人多，东西也贵一些。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈年下要做很多好吃的菜。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司年下发奖金，大家都很高兴。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年下我想回老家看看爷爷奶奶。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年下银行里排队的人特别多。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们盼着年下能收到红包。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了年下，街上挂满了红灯笼。", "target_word": "年下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "年下：春节前后的一段时间，年底", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58f48c7e-7c39-41bb-a691-24e290a8a1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能工作，句子说“工作很忙、我常常加班”，主语必须是能工作的人或时段。"}, {"text": "年下", "is_correct": true, "explanation": "正确。年下指春节前后一段时间，句子说这段时间工作忙、要加班。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不上班，不能说“工作很忙、我常常加班”。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不说“工作很忙”，这里需要表示一段时间的词。"}], "explanations": {"石头": "语义：石头不能工作，句子说“工作很忙、我常常加班”，主语必须是能工作的人或时段。", "年下": "正确。年下指春节前后一段时间，句子说这段时间工作忙、要加班。", "小狗": "语义：小狗不上班，不能说“工作很忙、我常常加班”。", "身体": "搭配：“身体”不说“工作很忙”，这里需要表示一段时间的词。"}, "sentence_index": 0, "correct_answer": "年下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年下的时候，田里的玉米正在收割。", "explanation": "这里应该用〈秋天〉。玉米收割在秋天；年下指春节前后，田里的庄稼早已收完。"}, {"text": "年下的时候天气很热，我们常去游泳。", "explanation": "这里应该用〈年中〉。年下天气寒冷，不能和“天气很热、去游泳”搭配；这种情况要用年中。"}, {"text": "年下学校放暑假，同学们都在海边玩儿。", "explanation": "这里应该用〈暑假〉。暑假在七八月，天气最热；年下指春节前后，学校不会放暑假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不能作“想回老家”的主语，句子的主语应是人。"}, {"text": "年下", "is_correct": true, "explanation": "正确。年下指春节前后一段时间，句子表示在这段时间回老家探望爷爷奶奶。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会想回老家，句子需要有想法的人作主语。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不与“想回老家看看爷爷奶奶”搭配。"}], "explanations": {"电脑": "语义：“电脑”不能作“想回老家”的主语，句子的主语应是人。", "年下": "正确。年下指春节前后一段时间，句子表示在这段时间回老家探望爷爷奶奶。", "桌子": "语义：桌子不会想回老家，句子需要有想法的人作主语。", "空气": "搭配：“空气”不与“想回老家看看爷爷奶奶”搭配。"}, "sentence_index": 6, "correct_answer": "年下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年下我们公司的业绩增长很快，一月到六月都很好。", "explanation": "这里应该用〈上半年〉。年下指年底或春节前后，与“一月到六月”这一整段时间不符。"}, {"text": "年下六点，公园里很安静。", "explanation": "这里应该用〈清晨〉。年下是一段时间，不能与具体钟点“六点”连用。"}, {"text": "年下的晚上，大家在院子里吃西瓜聊天。", "explanation": "这里应该用〈夏天〉。年下指年底或春节前后，天气寒冷，不适合在院子里吃西瓜；这种情况要用夏天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很年下，公司的事情特别多，大家都很累。", "corrected_sentence": "年下公司的事情特别多，大家都很累。", "error_description": "错误：“很年下”。“年下”是时间词，不能用“很”修饰，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很年下我回老家陪爷爷奶奶过节。", "corrected_sentence": "年下我回老家陪爷爷奶奶过节。", "error_description": "错误：“很年下”。“年下”是时间词，不能用“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
