INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89265, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在手机上发短短的话和照片给大家看的地方。", "primary_collocate": null, "pronunciation": "wēi bó", "ipa": "weɪ̯˥ pwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "我在微博上发了一张照片。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都用手机看微博。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开手机上的微博，朋友们发的新内容一眼就能看到。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的微博里有很多旅行照片。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在微博上写了今天的心情。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这张图发到微博上。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看了我昨天发的微博吗？", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷也学会了发微博。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的微博每天都有新照片。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，我常常刷一会儿微博。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "微博用户", "label": "复合"}], "register": "口语", "sense_fingerprint": "手机上发短话和照片给大家看的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微博", "is_correct": true, "explanation": "正确：微博是可以在手机上发布照片的平台，与“发”和“照片”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“发照片”需要一个发布内容的平台，桌子不是这样的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能用来发布照片，句子说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不能在上面发布照片。"}], "explanations": {"微博": "正确：微博是可以在手机上发布照片的平台，与“发”和“照片”搭配。", "桌子": "搭配：“发照片”需要一个发布内容的平台，桌子不是这样的地方。", "冰箱": "语义：冰箱不能用来发布照片，句子说不通。", "课本": "语义：课本是学习用的书，不能在上面发布照片。"}, "sentence_index": 0, "correct_answer": "微博"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每周都用微博给老家寄一次特产。", "explanation": "这里应该用〈快递〉。寄特产要靠快递，微博是发布短文和图片的平台，不能用来寄东西。"}, {"text": "我每天用微博收发工作文件。", "explanation": "这里应该用〈邮箱〉。收发工作文件要用邮箱，微博是公开发布短文和图片的平台，不能用来传文件。"}, {"text": "他用微博拍了一张照片。", "explanation": "这里应该用〈照相机〉。微博是发布内容的平台，不能用来拍照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微博", "is_correct": true, "explanation": "正确：“发的微博”指发布在网上的动态，符合句子的语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以发布的内容，句子说不通。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不能被“发”出去，句子说不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“发”一般不用于花园，花园不能作为“发的”对象。"}], "explanations": {"微博": "正确：“发的微博”指发布在网上的动态，符合句子的语境。", "窗户": "语义：窗户不是可以发布的内容，句子说不通。", "书桌": "语义：书桌是家具，不能被“发”出去，句子说不通。", "花园": "搭配：“发”一般不用于花园，花园不能作为“发的”对象。"}, "sentence_index": 6, "correct_answer": "微博"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常去微博存钱。", "explanation": "这里应该用〈银行〉。存钱要去银行，微博是网络平台，不能存钱。"}, {"text": "微博每天都在讲课。", "explanation": "这里应该用〈老师〉。讲课的是人，微博是平台，不会讲课。"}, {"text": "他把这条微博摔碎了。", "explanation": "这里应该用〈杯子〉。“摔碎”指有形的器物被摔坏，微博是网络上的内容，不能被摔碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天看了一只朋友的微博。", "corrected_sentence": "我今天看了一条朋友的微博。", "error_description": "错误形式：一只微博。“微博”以“条”为量词，应说“一条微博”，“只”多用于动物，不能用来数微博。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在微博上发了过很多旅行照片。", "corrected_sentence": "他在微博上发过很多旅行照片。", "error_description": "错误形式：发了过。“了”和“过”不能同时用在同一个动词后面。正确形式：发过，表示曾经有过这样的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
