INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89267, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "度是量温度这些东西用的单位。", "primary_collocate": null, "pronunciation": "dù", "ipa": "tu˥˩", "syllable_count": 1, "sentences": [{"text": "今天最高气温三十五度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发烧了，体温三十九度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水烧到一百度就开了。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天室内要开到二十度才暖和。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天夜里零下五度，真冷。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调调到二十六度最舒服。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天早上量了体温，三十七度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京夏天常常超过三十度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡只有四十度，不太热。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说洗澡水四十度正好。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "度：计量温度的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58f48c7e-7c39-41bb-a691-24e290a8a1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "正确。dù（第四声），计量温度的量词，如“三十五度”。"}, {"text": "都", "is_correct": false, "explanation": "dōu（第一声）与 dù（第四声）韵母和声调都不同，意思是“都”。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）声调不同，意思是“堵塞”。"}, {"text": "毒", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是“毒”。"}, {"text": "读", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是“阅读”。"}], "explanations": {"度": "正确。dù（第四声），计量温度的量词，如“三十五度”。", "都": "dōu（第一声）与 dù（第四声）韵母和声调都不同，意思是“都”。", "堵": "dǔ（第三声）与 dù（第四声）声调不同，意思是“堵塞”。", "毒": "dú（第二声）与 dù（第四声）声调不同，意思是“毒”。", "读": "dú（第二声）与 dù（第四声）声调不同，意思是“阅读”。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "个", "is_correct": false, "explanation": "搭配：“个”不用于计量气温，这里应说“三十五度”。"}, {"text": "度", "is_correct": true, "explanation": "正确。“度”是计量温度的量词，“三十五度”表示最高气温。"}, {"text": "米", "is_correct": false, "explanation": "语义：“米”计量长度，不能用来计量气温。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”指分数或分钟，不能计量气温。"}], "explanations": {"个": "搭配：“个”不用于计量气温，这里应说“三十五度”。", "度": "正确。“度”是计量温度的量词，“三十五度”表示最高气温。", "米": "语义：“米”计量长度，不能用来计量气温。", "分": "语义：“分”指分数或分钟，不能计量气温。"}, "sentence_index": 0, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车时速开到了一百二十度。", "explanation": "这里应该用〈公里〉。度用于温度、角度、电量等，车速要用“公里”，说“时速一百二十公里”。"}, {"text": "这个西瓜重五度。", "explanation": "这里应该用〈公斤〉。度不用于计量重量，西瓜的重量要用“公斤”，说“重五公斤”。"}, {"text": "他考了九十度。", "explanation": "这里应该用〈分〉。度不用于计量成绩，考试成绩要用“分”，说“考了九十分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89267, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "正确。dù（第四声），计量温度的量词，如“三十五度”。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）声调不同，意思是“打赌”。"}, {"text": "独", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是“单独”。"}, {"text": "督", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，意思是“监督”。"}, {"text": "嘟", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，常用于“嘟嘟声”。"}], "explanations": {"度": "正确。dù（第四声），计量温度的量词，如“三十五度”。", "赌": "dǔ（第三声）与 dù（第四声）声调不同，意思是“打赌”。", "独": "dú（第二声）与 dù（第四声）声调不同，意思是“单独”。", "督": "dū（第一声）与 dù（第四声）声调不同，意思是“监督”。", "嘟": "dū（第一声）与 dù（第四声）声调不同，常用于“嘟嘟声”。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "斤", "is_correct": false, "explanation": "语义：“斤”计量重量，不能用来计量体温。"}, {"text": "元", "is_correct": false, "explanation": "语义：“元”是货币单位，不能用来计量体温。"}, {"text": "度", "is_correct": true, "explanation": "正确。“度”计量体温，“三十七度”表示体温数值。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”不用于体温这类数值，这里应说“度”。"}], "explanations": {"斤": "语义：“斤”计量重量，不能用来计量体温。", "元": "语义：“元”是货币单位，不能用来计量体温。", "度": "正确。“度”计量体温，“三十七度”表示体温数值。", "只": "搭配：“只”不用于体温这类数值，这里应说“度”。"}, "sentence_index": 6, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今年十八度了。", "explanation": "这里应该用〈岁〉。度不用于计量年龄，年龄要用“岁”，说“十八岁”。"}, {"text": "这条河宽一百度。", "explanation": "这里应该用〈米〉。度不用于计量长度，河宽要用“米”，说“一百米”。"}, {"text": "这件衣服卖一百度。", "explanation": "这里应该用〈元〉。度不用于计量价钱，价格要用“元”，说“卖一百元”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天最低气温零下三个度，要多穿点衣服。", "corrected_sentence": "明天最低气温零下三度，要多穿点衣服。", "error_description": "错误：“三个度”。“度”本身就是量词，前面不能再加“个”，应说“零下三度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我早上量体温，只有三十七个度，没发烧。", "corrected_sentence": "我早上量体温，只有三十七度，没发烧。", "error_description": "错误：“三十七个度”。“度”本身就是量词，前面不能再加“个”，应说“三十七度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9669a7e4-0e8c-408b-97e6-4c608d54c33e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
